-- public._canonical_caller_in_org(p_org uuid) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=790327b594315e14103d9dc4bff95019 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public._canonical_caller_in_org(p_org uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.organization_users
     WHERE organization_id = p_org AND user_id = auth.uid()
  );
$function$;

-- public._canonical_spine_enabled(p_org uuid) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=7c3f64e6c4cb7363d03212050a606009 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public._canonical_spine_enabled(p_org uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT canonical_spine_v1 FROM public.org_settings WHERE organization_id = p_org LIMIT 1),
    false
  );
$function$;

-- public._check_questionnaire_token_rate_limit(p_token_hash text) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=4ea0aec8631b2c05e573634d316a3c3f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public._check_questionnaire_token_rate_limit(p_token_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_window TIMESTAMPTZ := date_trunc('minute', now()) - make_interval(mins => (extract(minute from now())::int % 5));
  v_count INT;
BEGIN
  INSERT INTO public.questionnaire_token_attempts(token_hash, window_start, count)
  VALUES (p_token_hash, v_window, 1)
  ON CONFLICT (token_hash, window_start)
  DO UPDATE SET count = public.questionnaire_token_attempts.count + 1
  RETURNING count INTO v_count;

  IF v_count > 30 THEN
    RAISE EXCEPTION 'Rate limit exceeded';
  END IF;
END;
$function$;

-- public._hash_token(p_token text) -> text
--   language=sql volatility=immutable security_definer=False search_path=search_path=public, extensions
--   definition_hash=b4dc7aeeb3a2603f0ff4253bac9d860e (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public._hash_token(p_token text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT encode(extensions.digest(p_token::bytea, 'sha256'), 'hex')
$function$;

-- public._require_valid_questionnaire_link(p_instance_id uuid, p_token text) -> questionnaire_public_links
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6f337e9712ac659547fb9bfd60760607 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public._require_valid_questionnaire_link(p_instance_id uuid, p_token text)
 RETURNS questionnaire_public_links
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hash TEXT;
  v_link public.questionnaire_public_links;
BEGIN
  v_hash := public._hash_token(p_token);

  PERFORM public._check_questionnaire_token_rate_limit(v_hash);

  SELECT * INTO v_link
  FROM public.questionnaire_public_links
  WHERE questionnaire_instance_id = p_instance_id
    AND token_hash = v_hash
  LIMIT 1;

  IF NOT FOUND THEN
    INSERT INTO public.questionnaire_access_log(questionnaire_instance_id, token_hash, action)
    VALUES (p_instance_id, v_hash, 'invalid_token');
    RAISE EXCEPTION 'Invalid questionnaire link';
  END IF;

  IF v_link.revoked_at IS NOT NULL THEN
    INSERT INTO public.questionnaire_access_log(questionnaire_instance_id, token_hash, action)
    VALUES (p_instance_id, v_hash, 'revoked');
    RAISE EXCEPTION 'Questionnaire link has been revoked';
  END IF;

  IF v_link.expires_at <= now() THEN
    INSERT INTO public.questionnaire_access_log(questionnaire_instance_id, token_hash, action)
    VALUES (p_instance_id, v_hash, 'expired');
    RAISE EXCEPTION 'Questionnaire link has expired';
  END IF;

  RETURN v_link;
END;
$function$;

