-- public.can_manage_automation_rules_check(_user_id uuid, _org_id uuid) -> boolean
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=8a6187c8cee93468f747ec22ce028d1f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.can_manage_automation_rules_check(_user_id uuid, _org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mode TEXT;
BEGIN
  -- Get org setting
  SELECT automation_rule_management_mode INTO v_mode
  FROM org_settings
  WHERE organization_id = _org_id;
  
  -- Default to owner_admin_manager if no setting
  IF v_mode IS NULL THEN
    v_mode := 'owner_admin_manager';
  END IF;
  
  IF v_mode = 'owner_admin_only' THEN
    RETURN user_has_role_at_least(_user_id, _org_id, 'admin');
  ELSE
    RETURN user_has_role_at_least(_user_id, _org_id, 'manager');
  END IF;
END;
$function$;

