-- public.cancel_stale_onboarding_applications(p_organization_id uuid) -> integer
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=e4a690f5d5706af1bd57ab8c15797477 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.cancel_stale_onboarding_applications(p_organization_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  IF NOT public.user_has_organization_access(p_organization_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  WITH cancelled AS (
    UPDATE public.onboarding_applications
    SET status = 'cancelled',
        updated_at = now()
    WHERE organization_id = p_organization_id
      AND status IN ('draft', 'in_progress')
      AND quote_id IS NULL
      AND lead_id IS NULL
      AND client_id IS NULL
      AND company_id IS NULL
      AND created_at < now() - interval '90 days'
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM cancelled;

  RETURN v_count;
END;
$function$;

-- public.cancel_workflow_instance(p_instance_id uuid, p_reason text) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=93c262a5b15b54bc18b51a676a67c520 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.cancel_workflow_instance(p_instance_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.automation_workflow_instances
     SET status = 'CANCELLED', cancelled_at = now(), last_error = COALESCE(p_reason, last_error), updated_at = now()
   WHERE id = p_instance_id
     AND status NOT IN ('CANCELLED', 'COMPLETED')
     AND org_id IN (SELECT organization_id FROM organization_users WHERE user_id = auth.uid());
END;
$function$;

-- public.check_automation_rate_limit(p_organization_id uuid, p_rule_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=7f307c5d8379ee6f0ffcb3bdf4d4f175 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.check_automation_rate_limit(p_organization_id uuid, p_rule_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_settings org_settings%ROWTYPE;
  v_rule_hour_count INT := 0;
  v_rule_day_count INT := 0;
  v_org_hour_count INT := 0;
  v_org_day_count INT := 0;
  v_allowed BOOLEAN := true;
BEGIN
  -- Use the safe function to get settings
  v_settings := get_org_settings_safe(p_organization_id);

  -- Get rule-level counts if rule_id provided
  IF p_rule_id IS NOT NULL THEN
    SELECT COALESCE(action_count, 0) INTO v_rule_hour_count
    FROM automation_rate_limits
    WHERE organization_id = p_organization_id 
      AND automation_rule_id = p_rule_id 
      AND window_type = 'hour' 
      AND window_start > now() - interval '1 hour';
      
    SELECT COALESCE(action_count, 0) INTO v_rule_day_count
    FROM automation_rate_limits
    WHERE organization_id = p_organization_id 
      AND automation_rule_id = p_rule_id 
      AND window_type = 'day' 
      AND window_start > now() - interval '1 day';
  END IF;

  -- Get org-level counts
  SELECT COALESCE(SUM(action_count), 0) INTO v_org_hour_count
  FROM automation_rate_limits
  WHERE organization_id = p_organization_id 
    AND window_type = 'hour' 
    AND window_start > now() - interval '1 hour';
    
  SELECT COALESCE(SUM(action_count), 0) INTO v_org_day_count
  FROM automation_rate_limits
  WHERE organization_id = p_organization_id 
    AND window_type = 'day' 
    AND window_start > now() - interval '1 day';

  -- Check limits
  IF p_rule_id IS NOT NULL THEN
    IF v_rule_hour_count >= v_settings.automation_rate_limit_per_rule_hour THEN
      v_allowed := false;
    END IF;
    IF v_rule_day_count >= v_settings.automation_rate_limit_per_rule_day THEN
      v_allowed := false;
    END IF;
  END IF;
  
  IF v_org_hour_count >= v_settings.automation_rate_limit_org_hour THEN
    v_allowed := false;
  END IF;
  IF v_org_day_count >= v_settings.automation_rate_limit_org_day THEN
    v_allowed := false;
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_allowed,
    'rule_hour_count', v_rule_hour_count,
    'rule_hour_limit', v_settings.automation_rate_limit_per_rule_hour,
    'rule_day_count', v_rule_day_count,
    'rule_day_limit', v_settings.automation_rate_limit_per_rule_day,
    'org_hour_count', v_org_hour_count,
    'org_hour_limit', v_settings.automation_rate_limit_org_hour,
    'org_day_count', v_org_day_count,
    'org_day_limit', v_settings.automation_rate_limit_org_day
  );
END;
$function$;

-- public.check_bank_balance_integrity(p_bank_account_id uuid, p_as_of_date date) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=bf06e61bd8aed6a31eb66b45809d8166 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.check_bank_balance_integrity(p_bank_account_id uuid, p_as_of_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_bank record;
  v_gl_balance numeric := 0;
  v_txn_balance numeric := 0;
  v_unposted_count int := 0;
  v_user_id uuid := auth.uid();
BEGIN
  SELECT * INTO v_bank FROM public.bank_accounts WHERE id = p_bank_account_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank account not found'; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_bank.organization_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  IF v_bank.account_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No GL account mapped');
  END IF;

  -- GL balance (base currency) on the mapped account, entity-scoped
  SELECT COALESCE(SUM(le.debit - le.credit), 0)
  INTO v_gl_balance
  FROM public.ledger_entries le
  WHERE le.account_id = v_bank.account_id
    AND le.organization_id = v_bank.organization_id
    AND le.transaction_date <= p_as_of_date
    AND (
      (v_bank.company_id IS NOT NULL AND le.company_id = v_bank.company_id) OR
      (v_bank.client_id IS NOT NULL AND le.client_id = v_bank.client_id)
    );

  -- Posted bank transaction sum (status MATCHED or RECONCILED) in base currency
  SELECT
    COALESCE(SUM(COALESCE(bt.amount_base, bt.amount)), 0),
    COUNT(*) FILTER (WHERE bt.status IN ('UNREVIEWED', 'PENDING'))
  INTO v_txn_balance, v_unposted_count
  FROM public.bank_transactions bt
  WHERE bt.bank_account_id = p_bank_account_id
    AND bt.transaction_date <= p_as_of_date
    AND bt.status IN ('MATCHED', 'RECONCILED');

  RETURN jsonb_build_object(
    'success', true,
    'as_of_date', p_as_of_date,
    'gl_balance', v_gl_balance,
    'posted_txn_balance', v_txn_balance,
    'drift', ROUND(v_gl_balance - v_txn_balance, 2),
    'in_balance', ABS(v_gl_balance - v_txn_balance) < 0.005,
    'unposted_transactions', v_unposted_count
  );
END;
$function$;

-- public.check_suppression(p_org_id uuid, p_email text, p_category text) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=d4328e5551fcab346930cb1ab1b6e93c (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.check_suppression(p_org_id uuid, p_email text, p_category text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS(
    SELECT 1 FROM email_suppressions
    WHERE organization_id = p_org_id
      AND lower(email) = lower(p_email)
      AND (category IS NULL OR category = p_category)
  ) OR EXISTS(
    SELECT 1 FROM email_preferences
    WHERE organization_id = p_org_id
      AND lower(coalesce(email,'')) = lower(p_email)
      AND category = p_category
      AND opted_out_at IS NOT NULL
  );
$function$;

-- public.claim_email_queue_row(p_email_id uuid, p_stale_before timestamp with time zone) -> TABLE(id uuid, organization_id uuid, to_email text, to_name text, subject text, body_html text, body_text text, mailbox_id uuid, provider text, created_by uuid, attachments jsonb)
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=bd54373bc38fd5981f45914b880e1fdf (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.claim_email_queue_row(p_email_id uuid, p_stale_before timestamp with time zone)
 RETURNS TABLE(id uuid, organization_id uuid, to_email text, to_name text, subject text, body_html text, body_text text, mailbox_id uuid, provider text, created_by uuid, attachments jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  UPDATE public.email_queue q
     SET claimed_at = now(),
         updated_at = now()
   WHERE q.id = p_email_id
     AND q.status = 'pending'
     AND (q.claimed_at IS NULL OR q.claimed_at < p_stale_before)
  RETURNING
     q.id,
     q.organization_id,
     q.to_email,
     q.to_name,
     q.subject,
     q.body_html,
     q.body_text,
     q.mailbox_id,
     q.provider,
     q.created_by,
     q.attachments;
END;
$function$;

-- public.claim_idempotency_key(p_org_id uuid, p_key text, p_rule_id uuid, p_chaser_policy_id uuid, p_workflow_instance_id uuid) -> boolean
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=1590b15004f0d5e94a72e8c87a50be1f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.claim_idempotency_key(p_org_id uuid, p_key text, p_rule_id uuid DEFAULT NULL::uuid, p_chaser_policy_id uuid DEFAULT NULL::uuid, p_workflow_instance_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  BEGIN
    INSERT INTO automation_idempotency_keys(organization_id, key, rule_id, chaser_policy_id, workflow_instance_id)
    VALUES (p_org_id, p_key, p_rule_id, p_chaser_policy_id, p_workflow_instance_id);
    RETURN true;
  EXCEPTION WHEN unique_violation THEN
    RETURN false;
  END;
END;$function$;

