-- public.client_has_portal_access(check_user_id uuid, check_client_id uuid, check_company_id uuid) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=42a15640532186576d6d802febcfcbc4 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.client_has_portal_access(check_user_id uuid, check_client_id uuid DEFAULT NULL::uuid, check_company_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.portal_access
    WHERE user_id = check_user_id
      AND (is_active IS NULL OR is_active = true)
      AND status = 'active'
      AND (
        (check_client_id IS NOT NULL AND client_id = check_client_id) OR
        (check_company_id IS NOT NULL AND company_id = check_company_id)
      )
  )
$function$;

-- public.complete_bank_reconciliation(p_reconciliation_id uuid, p_force boolean) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=9bfad887ddd5f412b4943e0aec8f9ade (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.complete_bank_reconciliation(p_reconciliation_id uuid, p_force boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec public.reconciliations%ROWTYPE;
  v_sum numeric;
  v_expected numeric;
  v_diff numeric;
BEGIN
  SELECT * INTO v_rec FROM public.reconciliations WHERE id = p_reconciliation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reconciliation not found'; END IF;
  IF v_rec.status <> 'in_progress' THEN
    RAISE EXCEPTION 'Reconciliation already %', v_rec.status;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_rec.organization_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for this organization';
  END IF;

  PERFORM public.assert_no_locked_period_write(
    v_rec.organization_id, v_rec.client_id, v_rec.company_id, v_rec.statement_end_date
  );

  SELECT COALESCE(SUM(amount),0) INTO v_sum
  FROM public.reconciliation_lines WHERE reconciliation_id = p_reconciliation_id;

  v_expected := v_rec.statement_closing_balance - v_rec.statement_opening_balance;
  v_diff := v_expected - v_sum;

  IF ABS(v_diff) > 0.005 AND NOT p_force THEN
    RAISE EXCEPTION 'Reconciliation does not balance: expected movement %, lines sum %, difference %',
      v_expected, v_sum, v_diff;
  END IF;

  UPDATE public.reconciliations
     SET status = 'completed',
         completed_by = auth.uid(),
         completed_at = now(),
         difference = v_diff,
         updated_at = now()
   WHERE id = p_reconciliation_id;

  INSERT INTO public.bookkeeping_audit_log (
    organization_id, client_id, company_id, entity_type, entity_id, action, performed_by, metadata
  ) VALUES (
    v_rec.organization_id, v_rec.client_id, v_rec.company_id,
    'reconciliation', p_reconciliation_id, 'complete_bank_reconciliation', auth.uid(),
    jsonb_build_object(
      'expected_movement', v_expected,
      'lines_sum', v_sum,
      'difference', v_diff,
      'forced', p_force
    )
  );

  RETURN p_reconciliation_id;
END;
$function$;

-- public.consume_unsubscribe_token(p_token text, p_category text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=573748f0e532748dd238242c4c99c99a (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.consume_unsubscribe_token(p_token text, p_category text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v_cat text;
BEGIN
  SELECT * INTO r FROM email_unsubscribe_tokens WHERE token = p_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','invalid'); END IF;
  IF r.used_at IS NOT NULL THEN RETURN jsonb_build_object('ok',true,'already',true); END IF;
  v_cat := COALESCE(p_category, r.category);
  INSERT INTO email_suppressions(organization_id, email, category, reason, source)
  VALUES (r.organization_id, r.email, v_cat, 'unsubscribe', 'one_click_token')
  ON CONFLICT DO NOTHING;
  UPDATE email_unsubscribe_tokens SET used_at = now() WHERE id = r.id;
  RETURN jsonb_build_object('ok',true);
END;$function$;

-- public.create_automation_rule_safe(p_organization_id uuid, p_name text, p_trigger_type text, p_trigger_config jsonb, p_action_type text, p_action_config jsonb, p_is_active boolean, p_email_mode text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=5dd4a94d1af99fd6401791e6f0c697f2 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_automation_rule_safe(p_organization_id uuid, p_name text, p_trigger_type text, p_trigger_config jsonb DEFAULT '{}'::jsonb, p_action_type text DEFAULT NULL::text, p_action_config jsonb DEFAULT '{}'::jsonb, p_is_active boolean DEFAULT true, p_email_mode text DEFAULT 'draft'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_rule_id uuid;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF NOT public.user_has_role_at_least(v_user_id, p_organization_id, 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Manager role required');
  END IF;

  INSERT INTO automation_rules (
    organization_id, name, trigger_type, trigger_config, action_type, action_config, is_active, email_mode
  ) VALUES (
    p_organization_id, p_name, p_trigger_type, p_trigger_config, p_action_type, p_action_config, p_is_active, p_email_mode
  ) RETURNING id INTO v_rule_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (p_organization_id, 'automation_rule', v_rule_id, 'created', v_user_id);

  RETURN jsonb_build_object('success', true, 'rule_id', v_rule_id);
END;
$function$;

-- public.create_bill_draft_safe(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_supplier_id uuid, p_bill_number text, p_reference text, p_issue_date date, p_due_date date, p_notes text, p_currency text, p_lines jsonb) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=72e05a886ba52a62c6164f1876a21ad0 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_bill_draft_safe(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_bill_number text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_issue_date date DEFAULT CURRENT_DATE, p_due_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_currency text DEFAULT 'GBP'::text, p_lines jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_bill_id uuid;
  v_line jsonb;
  v_line_number int := 0;
  v_total_net numeric := 0;
  v_total_vat numeric := 0;
  v_total_gross numeric := 0;
  v_quantity numeric;
  v_unit_price numeric;
  v_vat_rate numeric;
  v_net numeric;
  v_vat numeric;
  v_gross numeric;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  
  IF p_entity_type NOT IN ('client', 'company') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid entity_type');
  END IF;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_quantity := public.try_parse_numeric(v_line->>'quantity');
    v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
    IF v_quantity IS NULL OR v_unit_price IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Invalid line data');
    END IF;
  END LOOP;

  INSERT INTO bills (
    organization_id, client_id, company_id, supplier_id, bill_number,
    reference, issue_date, due_date, notes, currency, status
  ) VALUES (
    p_organization_id,
    CASE WHEN p_entity_type = 'client' THEN p_entity_id ELSE NULL END,
    CASE WHEN p_entity_type = 'company' THEN p_entity_id ELSE NULL END,
    p_supplier_id, p_bill_number, p_reference, p_issue_date,
    COALESCE(p_due_date, p_issue_date + 30), p_notes, p_currency, 'DRAFT'
  ) RETURNING id INTO v_bill_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_line_number := v_line_number + 1;
    v_quantity := public.try_parse_numeric(v_line->>'quantity');
    v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
    v_vat_rate := COALESCE(public.try_parse_numeric(v_line->>'vat_rate'), 0);
    
    v_net := ROUND(v_quantity * v_unit_price, 2);
    v_vat := ROUND(v_net * v_vat_rate / 100, 2);
    v_gross := v_net + v_vat;
    
    v_total_net := v_total_net + v_net;
    v_total_vat := v_total_vat + v_vat;
    v_total_gross := v_total_gross + v_gross;
    
    INSERT INTO bill_lines (
      bill_id, line_number, description, quantity, unit_price,
      vat_rate, net_amount, vat_amount, gross_amount, account_id, vat_code_id
    ) VALUES (
      v_bill_id, v_line_number, v_line->>'description',
      v_quantity, v_unit_price, v_vat_rate, v_net, v_vat, v_gross,
      NULLIF(v_line->>'account_id', '')::uuid,
      NULLIF(v_line->>'vat_code_id', '')::uuid
    );
  END LOOP;

  UPDATE bills SET total_net = v_total_net, total_vat = v_total_vat, total_gross = v_total_gross
  WHERE id = v_bill_id;

  INSERT INTO audit_log (organization_id, user_id, entity_type, entity_id, action, after_state)
  VALUES (p_organization_id, v_user_id, 'bill', v_bill_id, 'created',
    jsonb_build_object('status', 'DRAFT', 'total_gross', v_total_gross));

  RETURN jsonb_build_object('success', true, 'bill_id', v_bill_id);
END;
$function$;

-- public.create_customer_safe(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_name text, p_email text, p_phone text, p_billing_address jsonb, p_company_name text, p_vat_number text, p_payment_terms_days integer, p_default_currency text, p_internal_notes text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=058dddeeafd553bafba5e4e12c93869f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_customer_safe(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_name text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_billing_address jsonb DEFAULT NULL::jsonb, p_company_name text DEFAULT NULL::text, p_vat_number text DEFAULT NULL::text, p_payment_terms_days integer DEFAULT 30, p_default_currency text DEFAULT 'GBP'::text, p_internal_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id     uuid;
  v_customer_id uuid;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF p_entity_type IS NULL OR p_entity_type NOT IN ('client', 'company') THEN
    RAISE EXCEPTION 'Invalid entity_type: expected ''client'' or ''company''' USING ERRCODE = '22023';
  END IF;

  IF p_name IS NULL OR length(trim(p_name)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Customer name required');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.clients
      WHERE p_entity_type = 'client' AND id = p_entity_id AND organization_id = p_organization_id
    UNION ALL
    SELECT 1 FROM public.companies
      WHERE p_entity_type = 'company' AND id = p_entity_id AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'Entity does not belong to organization' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.customers (
    organization_id, client_id, company_id,
    name, email, phone,
    address_line_1, address_line_2, city, postcode, country,
    company_name, vat_number, payment_terms_days, default_currency, notes
  ) VALUES (
    p_organization_id,
    CASE WHEN p_entity_type = 'client'  THEN p_entity_id ELSE NULL END,
    CASE WHEN p_entity_type = 'company' THEN p_entity_id ELSE NULL END,
    trim(p_name), p_email, p_phone,
    NULLIF(p_billing_address->>'line1', ''),
    NULLIF(p_billing_address->>'line2', ''),
    NULLIF(p_billing_address->>'city', ''),
    NULLIF(p_billing_address->>'postcode', ''),
    COALESCE(NULLIF(p_billing_address->>'country', ''), 'United Kingdom'),
    p_company_name,
    p_vat_number,
    COALESCE(p_payment_terms_days, 30),
    COALESCE(NULLIF(p_default_currency, ''), 'GBP'),
    p_internal_notes
  ) RETURNING id INTO v_customer_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (p_organization_id, 'customer', v_customer_id, 'created', v_user_id);

  RETURN jsonb_build_object('success', true, 'customer_id', v_customer_id);
END;
$function$;

-- public.create_invoice_draft_safe(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_invoice_type text, p_customer_id uuid, p_contact_name text, p_contact_email text, p_invoice_number text, p_reference text, p_issue_date text, p_due_date text, p_notes text, p_currency text, p_lines jsonb) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=e989e584148f06e96e33e75f29d1bea1 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_invoice_draft_safe(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_invoice_type text DEFAULT 'SALES'::text, p_customer_id uuid DEFAULT NULL::uuid, p_contact_name text DEFAULT NULL::text, p_contact_email text DEFAULT NULL::text, p_invoice_number text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_issue_date text DEFAULT NULL::text, p_due_date text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_currency text DEFAULT 'GBP'::text, p_lines jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_invoice_id uuid;
  v_line jsonb;
  v_line_number integer := 0;
  v_quantity numeric; v_unit_price numeric; v_vat_rate numeric;
  v_net_amount numeric; v_vat_amount numeric; v_gross_amount numeric;
  v_total_net numeric := 0; v_total_vat numeric := 0; v_total_gross numeric := 0;
  v_is_portal boolean := false;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_entity_type NOT IN ('client', 'company') THEN
    RAISE EXCEPTION 'Invalid entity_type' USING ERRCODE = '22023';
  END IF;

  -- Portal capability preserved (owner ruling 2026-07-30): resolve the security
  -- difference between the overloads in favour of KEEPING the capability.
  v_is_portal := public.portal_has_perm(
    CASE WHEN p_entity_type = 'client'  THEN p_entity_id END,
    CASE WHEN p_entity_type = 'company' THEN p_entity_id END,
    'allow_invoice_create');

  IF NOT v_is_portal THEN
    IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
      RAISE EXCEPTION 'Access denied to organization' USING ERRCODE = '42501';
    END IF;
    IF NOT public.can_create_invoices(v_user_id, p_organization_id) THEN
      RAISE EXCEPTION 'Permission denied: cannot create invoices' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Relationship check, from the other overload: without it an invoice could be attached
  -- to another tenant's entity.
  IF NOT EXISTS (
    SELECT 1 FROM public.clients
      WHERE p_entity_type = 'client' AND id = p_entity_id AND organization_id = p_organization_id
    UNION ALL
    SELECT 1 FROM public.companies
      WHERE p_entity_type = 'company' AND id = p_entity_id AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'Entity does not belong to organization' USING ERRCODE = '42501';
  END IF;

  IF p_customer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.customers WHERE id = p_customer_id AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'Customer does not belong to organization' USING ERRCODE = '42501';
  END IF;

  INSERT INTO invoices (
    organization_id, client_id, company_id, customer_id, invoice_type, status,
    contact_name, contact_email, invoice_number, reference, issue_date, due_date,
    notes, currency, total_net, total_vat, total_gross, amount_paid, remaining_balance
  ) VALUES (
    p_organization_id,
    CASE WHEN p_entity_type = 'client' THEN p_entity_id ELSE NULL END,
    CASE WHEN p_entity_type = 'company' THEN p_entity_id ELSE NULL END,
    p_customer_id, COALESCE(p_invoice_type, 'SALES'), 'DRAFT',
    p_contact_name, p_contact_email, p_invoice_number, p_reference,
    COALESCE(p_issue_date::date, CURRENT_DATE),
    COALESCE(p_due_date::date, CURRENT_DATE + 30),
    p_notes, COALESCE(p_currency, 'GBP'), 0, 0, 0, 0, 0
  ) RETURNING id INTO v_invoice_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_line_number := v_line_number + 1;
    v_quantity := public.try_parse_numeric(v_line->>'quantity');
    v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
    v_vat_rate := COALESCE(public.try_parse_numeric(v_line->>'vat_rate'), 0);

    IF v_quantity IS NULL OR v_unit_price IS NULL THEN
      RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: quantity or unit_price is missing/invalid', v_line_number), ERRCODE = '22023';
    END IF;
    IF v_quantity <= 0 THEN
      RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: quantity must be > 0', v_line_number), ERRCODE = '22023';
    END IF;
    IF v_unit_price < 0 THEN
      RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: unit_price must be >= 0', v_line_number), ERRCODE = '22023';
    END IF;
    IF v_vat_rate < 0 OR v_vat_rate > 100 THEN
      RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: vat_rate must be between 0 and 100', v_line_number), ERRCODE = '22023';
    END IF;
    IF NULLIF(v_line->>'account_id', '') IS NULL THEN
      RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: account_id is required', v_line_number), ERRCODE = '22023';
    END IF;
    IF NULLIF(v_line->>'account_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: account_id is not a valid identifier', v_line_number), ERRCODE = '22023';
    END IF;
    IF NULLIF(v_line->>'vat_code_id', '') IS NOT NULL
       AND NULLIF(v_line->>'vat_code_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: vat_code_id is not a valid identifier', v_line_number), ERRCODE = '22023';
    END IF;

    v_net_amount := ROUND(v_quantity * v_unit_price, 2);
    v_vat_amount := ROUND(v_net_amount * (v_vat_rate / 100), 2);
    v_gross_amount := v_net_amount + v_vat_amount;
    v_total_net := v_total_net + v_net_amount;
    v_total_vat := v_total_vat + v_vat_amount;
    v_total_gross := v_total_gross + v_gross_amount;

    INSERT INTO invoice_lines (
      invoice_id, line_number, description, quantity, unit_price, vat_rate,
      vat_code_id, account_id, net_amount, vat_amount, gross_amount
    ) VALUES (
      v_invoice_id, v_line_number, COALESCE(v_line->>'description', ''),
      v_quantity, v_unit_price, v_vat_rate,
      NULLIF(v_line->>'vat_code_id', '')::uuid, NULLIF(v_line->>'account_id', '')::uuid,
      v_net_amount, v_vat_amount, v_gross_amount
    );
  END LOOP;

  UPDATE invoices SET
    total_net = v_total_net, total_vat = v_total_vat, total_gross = v_total_gross,
    remaining_balance = v_total_gross
  WHERE id = v_invoice_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (p_organization_id, 'invoice', v_invoice_id, 'created', v_user_id,
    jsonb_build_object('status', 'DRAFT', 'line_count', v_line_number,
                       'via', CASE WHEN v_is_portal THEN 'portal' ELSE 'staff' END));

  RETURN jsonb_build_object('success', true, 'invoice_id', v_invoice_id);
END;
$function$;

-- public.create_invoice_safe(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_input jsonb) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=f5d7c89bac5ed50de40ed97a1824be59 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_invoice_safe(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_invoice_id uuid;
  v_invoice_number text;
BEGIN
  v_user_id := auth.uid();
  
  -- Permission check: staff+
  IF NOT public.can_create_invoices(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: requires staff role or higher');
  END IF;
  
  -- Generate invoice number
  SELECT 'INV-' || LPAD((COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM 5) AS INTEGER)), 0) + 1)::text, 6, '0')
  INTO v_invoice_number
  FROM invoices 
  WHERE organization_id = p_organization_id;
  
  -- Create the invoice
  INSERT INTO invoices (
    organization_id,
    client_id,
    company_id,
    customer_id,
    invoice_number,
    issue_date,
    due_date,
    currency,
    notes,
    status
  )
  VALUES (
    p_organization_id,
    CASE WHEN p_entity_type = 'client' THEN p_entity_id ELSE NULL END,
    CASE WHEN p_entity_type = 'company' THEN p_entity_id ELSE NULL END,
    (p_input->>'customer_id')::uuid,
    v_invoice_number,
    COALESCE((p_input->>'issue_date')::date, CURRENT_DATE),
    COALESCE((p_input->>'due_date')::date, CURRENT_DATE + INTERVAL '30 days'),
    COALESCE(p_input->>'currency', 'GBP'),
    p_input->>'notes',
    'DRAFT'
  )
  RETURNING id INTO v_invoice_id;
  
  -- Write audit log
  INSERT INTO audit_log (
    organization_id,
    entity_type,
    entity_id,
    action,
    user_id,
    new_value,
    metadata
  )
  VALUES (
    p_organization_id,
    'invoice',
    v_invoice_id,
    'created',
    v_user_id,
    jsonb_build_object('invoice_number', v_invoice_number, 'status', 'DRAFT'),
    jsonb_build_object('entity_type', p_entity_type, 'entity_id', p_entity_id)
  );
  
  RETURN jsonb_build_object(
    'success', true,
    'invoice_id', v_invoice_id,
    'invoice_number', v_invoice_number
  );
END;
$function$;

-- public.create_job_from_template(p_template_id uuid, p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_engagement_id uuid, p_service_id uuid, p_period_start date, p_period_end date, p_filing_deadline date, p_name text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=505a2c05439e5d4e82514e3c7938e065 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_job_from_template(p_template_id uuid, p_organization_id uuid, p_client_id uuid DEFAULT NULL::uuid, p_company_id uuid DEFAULT NULL::uuid, p_engagement_id uuid DEFAULT NULL::uuid, p_service_id uuid DEFAULT NULL::uuid, p_period_start date DEFAULT NULL::date, p_period_end date DEFAULT NULL::date, p_filing_deadline date DEFAULT NULL::date, p_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_template templates%ROWTYPE;
  v_template_content jsonb;
  v_job_id uuid;
  v_task record;
  v_task_id uuid;
  v_job_name text;
  v_workpaper_instance_id uuid;
  v_service services_catalog%ROWTYPE;
BEGIN
  -- Get template
  SELECT * INTO v_template FROM templates WHERE id = p_template_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Template not found');
  END IF;
  
  v_template_content := v_template.content;
  
  -- Get service if provided
  IF p_service_id IS NOT NULL THEN
    SELECT * INTO v_service FROM services_catalog WHERE id = p_service_id;
  END IF;
  
  -- Determine job name
  v_job_name := COALESCE(p_name, v_template.name);
  
  -- Create the job
  INSERT INTO jobs (
    organization_id,
    client_id,
    company_id,
    engagement_id,
    service_id,
    name,
    status,
    priority,
    period_start,
    period_end,
    filing_deadline,
    source_template_id
  ) VALUES (
    p_organization_id,
    p_client_id,
    p_company_id,
    p_engagement_id,
    p_service_id,
    v_job_name,
    'not_started',
    'medium',
    p_period_start,
    p_period_end,
    p_filing_deadline,
    p_template_id
  ) RETURNING id INTO v_job_id;
  
  -- Create tasks from template
  IF v_template_content->'tasks' IS NOT NULL THEN
    FOR v_task IN SELECT * FROM jsonb_array_elements(v_template_content->'tasks')
    LOOP
      INSERT INTO job_tasks (
        job_id,
        organization_id,
        title,
        description,
        status,
        template_task_id,
        is_client_facing,
        relative_due_days,
        due_date,
        task_order
      ) VALUES (
        v_job_id,
        p_organization_id,
        v_task.value->>'name',
        v_task.value->>'description',
        'not_started',
        v_task.value->>'id',
        COALESCE((v_task.value->>'isClientFacing')::boolean, false),
        (v_task.value->>'relativeDueDays')::integer,
        CASE 
          WHEN (v_task.value->>'relativeDueDays')::integer IS NOT NULL AND p_filing_deadline IS NOT NULL
          THEN p_filing_deadline - ((v_task.value->>'relativeDueDays')::integer || ' days')::interval
          ELSE NULL
        END,
        (v_task.value->>'order')::integer
      );
    END LOOP;
  END IF;
  
  -- Create workpaper if service has workpaper template
  IF v_service.workpaper_template_id IS NOT NULL THEN
    INSERT INTO workpaper_instances (
      organization_id,
      template_id,
      job_id,
      client_id,
      company_id,
      status,
      field_values
    ) VALUES (
      p_organization_id,
      v_service.workpaper_template_id,
      v_job_id,
      p_client_id,
      p_company_id,
      'draft',
      '{}'::jsonb
    ) RETURNING id INTO v_workpaper_instance_id;
    
    -- Link workpaper to job
    UPDATE jobs SET workpaper_instance_id = v_workpaper_instance_id WHERE id = v_job_id;
  END IF;
  
  -- Log audit
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, metadata)
  VALUES (
    p_organization_id,
    'job',
    v_job_id,
    'created_from_template',
    jsonb_build_object('template_id', p_template_id, 'template_name', v_template.name)
  );
  
  RETURN jsonb_build_object(
    'success', true,
    'job_id', v_job_id,
    'workpaper_instance_id', v_workpaper_instance_id
  );
END;
$function$;

-- public.create_officer_register_event() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=5afaa5195ae83d21fef1b66226472304 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_officer_register_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id UUID;
BEGIN
  SELECT c.id INTO v_company_id FROM companies c 
  JOIN company_officers co ON co.company_id = c.id 
  WHERE co.id = COALESCE(NEW.id, OLD.id);
  
  IF TG_OP = 'INSERT' THEN
    INSERT INTO company_register_events (
      company_id, event_type, event_date, source, details,
      person_id, officer_id, created_by
    )
    VALUES (
      NEW.company_id, 'appointment', NEW.appointed_at, 'workpaper',
      jsonb_build_object('role', NEW.role),
      NEW.person_id, NEW.id, auth.uid()
    );
  ELSIF TG_OP = 'UPDATE' AND NEW.resigned_at IS NOT NULL AND OLD.resigned_at IS NULL THEN
    INSERT INTO company_register_events (
      company_id, event_type, event_date, source, details,
      person_id, officer_id, created_by
    )
    VALUES (
      NEW.company_id, 
      CASE WHEN NEW.role = 'director' THEN 'resignation' ELSE 'termination' END,
      NEW.resigned_at, 'workpaper',
      jsonb_build_object('role', NEW.role),
      NEW.person_id, NEW.id, auth.uid()
    );
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$function$;

-- public.create_org_settings_on_org_create() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=a13b14fda49007108839587bcaca03ca (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_org_settings_on_org_create()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO org_settings (organization_id)
  VALUES (NEW.id)
  ON CONFLICT (organization_id) DO NOTHING;
  RETURN NEW;
END;
$function$;

-- public.create_organization_with_owner(org_name text) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=56f705ed30c46c84fc17be638ee54b2b (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_organization_with_owner(org_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  existing_org uuid;
  new_org uuid;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT organization_id INTO existing_org
    FROM public.organization_users
   WHERE user_id = uid
   ORDER BY created_at ASC
   LIMIT 1;

  IF existing_org IS NOT NULL THEN
    RETURN existing_org;
  END IF;

  INSERT INTO public.organizations (name)
    VALUES (COALESCE(NULLIF(trim(org_name), ''), 'My Practice'))
    RETURNING id INTO new_org;

  BEGIN
    INSERT INTO public.organization_users (organization_id, user_id, role)
      VALUES (new_org, uid, 'owner');
  EXCEPTION WHEN unique_violation THEN
    DELETE FROM public.organizations WHERE id = new_org;
    SELECT organization_id INTO existing_org
      FROM public.organization_users
     WHERE user_id = uid
     ORDER BY created_at ASC
     LIMIT 1;
    RETURN existing_org;
  END;

  -- Seed default catalogue, templates and chaser policies.
  PERFORM public.seed_organization_defaults(new_org);

  RETURN new_org;
END;
$function$;

-- public.create_psc_register_event() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=5183d69ba8d47c82ff00aca48fb75f75 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_psc_register_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO company_register_events (
      company_id, event_type, event_date, source, details,
      person_id, psc_id, created_by
    )
    VALUES (
      NEW.company_id, 'psc_added', NEW.notified_at, 'workpaper',
      jsonb_build_object('nature_of_control', NEW.nature_of_control),
      NEW.person_id, NEW.id, auth.uid()
    );
  ELSIF TG_OP = 'UPDATE' AND NEW.ceased_at IS NOT NULL AND OLD.ceased_at IS NULL THEN
    INSERT INTO company_register_events (
      company_id, event_type, event_date, source, details,
      person_id, psc_id, created_by
    )
    VALUES (
      NEW.company_id, 'psc_ceased', NEW.ceased_at, 'workpaper',
      jsonb_build_object('nature_of_control', NEW.nature_of_control),
      NEW.person_id, NEW.id, auth.uid()
    );
  ELSIF TG_OP = 'UPDATE' AND NEW.nature_of_control IS DISTINCT FROM OLD.nature_of_control THEN
    INSERT INTO company_register_events (
      company_id, event_type, event_date, source, details,
      person_id, psc_id, created_by
    )
    VALUES (
      NEW.company_id, 'psc_updated', CURRENT_DATE, 'workpaper',
      jsonb_build_object(
        'old_nature_of_control', OLD.nature_of_control,
        'new_nature_of_control', NEW.nature_of_control
      ),
      NEW.person_id, NEW.id, auth.uid()
    );
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$function$;

-- public.create_questionnaire_public_link(p_instance_id uuid, p_expires_at timestamp with time zone) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=22dd7997b37ce7408eaf6c63df8f5a4a (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_questionnaire_public_link(p_instance_id uuid, p_expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id UUID;
  v_user_id UUID := auth.uid();
  v_token TEXT;
  v_hash TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT organization_id INTO v_org_id
  FROM public.questionnaire_instances
  WHERE id = p_instance_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Questionnaire not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = v_user_id
      AND organization_id = v_org_id
  ) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  -- Generate secure random token (48 hex chars = 24 bytes)
  v_token := encode(gen_random_bytes(24), 'hex');
  -- Use the helper function for hashing
  v_hash := public._hash_token(v_token);

  -- Revoke any existing non-revoked links for this instance
  UPDATE public.questionnaire_public_links
  SET revoked_at = now()
  WHERE questionnaire_instance_id = p_instance_id
    AND revoked_at IS NULL;

  INSERT INTO public.questionnaire_public_links(questionnaire_instance_id, token_hash, expires_at)
  VALUES (p_instance_id, v_hash, p_expires_at);

  -- Update instance status to 'sent' if it was draft
  UPDATE public.questionnaire_instances
  SET status = 'sent'
  WHERE id = p_instance_id AND status = 'draft';

  -- Return raw token ONCE to caller to build URL; never store raw token
  RETURN jsonb_build_object(
    'instance_id', p_instance_id,
    'token', v_token,
    'expires_at', p_expires_at
  );
END;
$function$;

-- public.create_test_ct600_filing(p_organization_id uuid, p_test_run_key text, p_period_start date, p_period_end date) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=38c8312c1428c30cff5d2ac1dabeae5f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.create_test_ct600_filing(p_organization_id uuid, p_test_run_key text, p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing_filing_id UUID;
  v_company_id UUID;
  v_ct_snapshot_id UUID;
  v_model_snapshot_id UUID;
  v_filing_id UUID;
  v_company_number TEXT;
  v_utr TEXT;
  v_company_name TEXT;
  v_hash_hex TEXT;
  v_ct600_artefact_id UUID;
  v_ixbrl_accounts_id UUID;
  v_ixbrl_computation_id UUID;
  v_ct_data JSONB;
  v_snapshot_hash TEXT;
BEGIN
  -- Generate deterministic values from test_run_key
  v_hash_hex := encode(sha256(p_test_run_key::bytea), 'hex');
  v_company_number := 'TC' || UPPER(LEFT(v_hash_hex, 6));
  -- Extract 10 numeric digits from hash for UTR (format-valid only)
  v_utr := LPAD(
    (('x' || LEFT(v_hash_hex, 8))::bit(32)::bigint % 10000000000)::text, 
    10, '0'
  );
  v_company_name := 'Test CT600 Company - ' || p_test_run_key;

  -- Check for existing filing with same test_run_key (idempotency)
  SELECT f.id, f.company_id, f.ct_snapshot_id, f.model_snapshot_id
  INTO v_existing_filing_id, v_company_id, v_ct_snapshot_id, v_model_snapshot_id
  FROM public.filings f
  WHERE f.organization_id = p_organization_id
    AND f.filing_data->>'test_run_key' = p_test_run_key;

  IF v_existing_filing_id IS NOT NULL THEN
    -- Return existing filing
    SELECT fa.id INTO v_ct600_artefact_id
    FROM public.filing_artefacts fa
    WHERE fa.filing_id = v_existing_filing_id AND fa.artefact_type = 'CT600_XML'
    LIMIT 1;

    SELECT fa.id INTO v_ixbrl_accounts_id
    FROM public.filing_artefacts fa
    WHERE fa.filing_id = v_existing_filing_id AND fa.artefact_type = 'IXBRL_ACCOUNTS'
    LIMIT 1;

    SELECT fa.id INTO v_ixbrl_computation_id
    FROM public.filing_artefacts fa
    WHERE fa.filing_id = v_existing_filing_id AND fa.artefact_type = 'IXBRL_CT_COMPUTATION'
    LIMIT 1;

    RETURN jsonb_build_object(
      'filing_id', v_existing_filing_id,
      'company_id', v_company_id,
      'ct_snapshot_id', v_ct_snapshot_id,
      'model_snapshot_id', v_model_snapshot_id,
      'artefact_ids', jsonb_build_object(
        'CT600_XML', v_ct600_artefact_id,
        'IXBRL_ACCOUNTS', v_ixbrl_accounts_id,
        'IXBRL_CT_COMPUTATION', v_ixbrl_computation_id
      ),
      'test_run_key', p_test_run_key,
      'already_existed', true
    );
  END IF;

  -- Create test company
  INSERT INTO public.companies (
    organization_id,
    company_name,
    company_number,
    utr,
    address_line_1,
    city,
    postcode,
    country,
    incorporation_date,
    is_active
  ) VALUES (
    p_organization_id,
    v_company_name,
    v_company_number,
    v_utr,
    '123 Test Street',
    'London',
    'EC1A 1BB',
    'United Kingdom',
    p_period_start - INTERVAL '1 year',
    true
  )
  RETURNING id INTO v_company_id;

  -- Create CT computation data
  v_ct_data := jsonb_build_object(
    'accounting_profit', 100000,
    'total_add_backs', 5000,
    'add_backs_breakdown', jsonb_build_array(
      jsonb_build_object('description', 'Depreciation', 'amount', 5000, 'category', 'depreciation')
    ),
    'total_deductions', 0,
    'deductions_breakdown', jsonb_build_array(),
    'total_capital_allowances', 3000,
    'balancing_charges', 0,
    'net_capital_allowances', 3000,
    'pools_summary', jsonb_build_array(),
    'claims_summary', jsonb_build_array(),
    'taxable_total_profits', 102000,
    'applicable_rate', 'marginal',
    'effective_rate', 0.2175,
    'adjusted_lower_limit', 50000,
    'adjusted_upper_limit', 250000,
    'tax_at_main_rate', 25500,
    'marginal_relief_fraction', 0.015,
    'marginal_relief_amount', 2220,
    'corporation_tax_due', 23280,
    'short_period_factor', 1,
    'associated_companies_count', 0,
    'period_start', p_period_start,
    'period_end', p_period_end,
    'balance_sheet', jsonb_build_object(
      'tangible_assets', 10000,
      'cash_at_bank', 50000,
      'debtors', 15000,
      'creditors_within_one_year', 8000,
      'net_current_assets', 57000,
      'total_assets_less_current_liabilities', 67000,
      'creditors_after_one_year', 0,
      'net_assets', 67000,
      'share_capital', 1,
      'retained_earnings', 66999,
      'total_equity', 67000
    )
  );

  -- Generate snapshot hash
  v_snapshot_hash := encode(sha256(v_ct_data::text::bytea), 'hex');

  -- Create CT computation snapshot
  INSERT INTO public.ct_computation_snapshots (
    organization_id,
    company_id,
    period_start,
    period_end,
    snapshot_data,
    snapshot_hash,
    status,
    generator_version
  ) VALUES (
    p_organization_id,
    v_company_id,
    p_period_start,
    p_period_end,
    v_ct_data,
    v_snapshot_hash,
    'approved',
    '1.2.0'
  )
  RETURNING id INTO v_ct_snapshot_id;

  -- Create filing model snapshot
  INSERT INTO public.filing_model_snapshots (
    organization_id,
    company_id,
    snapshot_type,
    period_start,
    period_end,
    snapshot_data,
    snapshot_hash,
    status,
    generator_version
  ) VALUES (
    p_organization_id,
    v_company_id,
    'ct600',
    p_period_start,
    p_period_end,
    v_ct_data,
    v_snapshot_hash,
    'approved',
    '1.2.0'
  )
  RETURNING id INTO v_model_snapshot_id;

  -- Create filing record
  INSERT INTO public.filings (
    organization_id,
    company_id,
    filing_type,
    filing_body,
    period_start,
    period_end,
    status,
    ct_snapshot_id,
    model_snapshot_id,
    filing_data,
    environment
  ) VALUES (
    p_organization_id,
    v_company_id,
    'CT600_HMRC',
    'HMRC',
    p_period_start,
    p_period_end,
    'approved',
    v_ct_snapshot_id,
    v_model_snapshot_id,
    jsonb_build_object(
      'test_run_key', p_test_run_key,
      'is_test_filing', true,
      'company_name', v_company_name,
      'company_number', v_company_number,
      'utr', v_utr
    ),
    'test'
  )
  RETURNING id INTO v_filing_id;

  -- Create CT600 XML artefact (minimal valid structure)
  INSERT INTO public.filing_artefacts (
    filing_id,
    organization_id,
    artefact_type,
    content,
    content_hash,
    content_encoding,
    metadata
  ) VALUES (
    v_filing_id,
    p_organization_id,
    'CT600_XML',
    '<TradingProfits><TurnoverPerAccounts>105000</TurnoverPerAccounts><TotalTradingProfits>105000</TotalTradingProfits></TradingProfits><TaxCalculation><TaxableProfit>102000</TaxableProfit><CorporationTaxDue>23280</CorporationTaxDue><MarginalRelief>2220</MarginalRelief><TotalCorporationTax>23280</TotalCorporationTax></TaxCalculation>',
    encode(sha256('CT600_XML_' || p_test_run_key), 'hex'),
    'utf8',
    jsonb_build_object(
      'generator_version', '1.2.0',
      'generated_at', NOW(),
      'test_artefact', true
    )
  )
  RETURNING id INTO v_ct600_artefact_id;

  -- Create iXBRL Accounts artefact (minimal valid structure)
  INSERT INTO public.filing_artefacts (
    filing_id,
    organization_id,
    artefact_type,
    content,
    content_hash,
    content_encoding,
    taxonomy_version,
    metadata
  ) VALUES (
    v_filing_id,
    p_organization_id,
    'IXBRL_ACCOUNTS',
    '<?xml version="1.0" encoding="UTF-8"?><!DOCTYPE html><html xmlns="http://www.w3.org/1999/xhtml" xmlns:ix="http://www.xbrl.org/2013/inlineXBRL" xmlns:xbrli="http://www.xbrl.org/2003/instance" xmlns:uk-gaap="http://xbrl.frc.org.uk/reports/2022-01-01/uk-gaap" xml:lang="en"><head><title>' || v_company_name || ' - Test Accounts</title></head><body><ix:header><ix:resources><xbrli:context id="ctx1"><xbrli:entity><xbrli:identifier scheme="http://www.companieshouse.gov.uk/">' || v_company_number || '</xbrli:identifier></xbrli:entity><xbrli:period><xbrli:instant>' || p_period_end || '</xbrli:instant></xbrli:period></xbrli:context><xbrli:unit id="GBP"><xbrli:measure>iso4217:GBP</xbrli:measure></xbrli:unit></ix:resources></ix:header><h1>' || v_company_name || '</h1><p>Test iXBRL Accounts</p></body></html>',
    encode(sha256('IXBRL_ACCOUNTS_' || p_test_run_key), 'hex'),
    'utf8',
    'FRC-2022-01-01',
    jsonb_build_object(
      'generator_version', '1.2.0',
      'generated_at', NOW(),
      'test_artefact', true
    )
  )
  RETURNING id INTO v_ixbrl_accounts_id;

  -- Create iXBRL CT Computation artefact (minimal valid structure)
  INSERT INTO public.filing_artefacts (
    filing_id,
    organization_id,
    artefact_type,
    content,
    content_hash,
    content_encoding,
    taxonomy_version,
    metadata
  ) VALUES (
    v_filing_id,
    p_organization_id,
    'IXBRL_CT_COMPUTATION',
    '<?xml version="1.0" encoding="UTF-8"?><!DOCTYPE html><html xmlns="http://www.w3.org/1999/xhtml" xmlns:ix="http://www.xbrl.org/2013/inlineXBRL" xmlns:xbrli="http://www.xbrl.org/2003/instance" xmlns:ct="http://xbrl.frc.org.uk/reports/2022-01-01/uk-core" xml:lang="en"><head><title>' || v_company_name || ' - CT Computation</title></head><body><ix:header><ix:resources><xbrli:context id="ctx1"><xbrli:entity><xbrli:identifier scheme="http://www.companieshouse.gov.uk/">' || v_company_number || '</xbrli:identifier></xbrli:entity><xbrli:period><xbrli:startDate>' || p_period_start || '</xbrli:startDate><xbrli:endDate>' || p_period_end || '</xbrli:endDate></xbrli:period></xbrli:context><xbrli:unit id="GBP"><xbrli:measure>iso4217:GBP</xbrli:measure></xbrli:unit></ix:resources></ix:header><h1>' || v_company_name || '</h1><p>Test CT Computation - Tax Due: £23,280</p></body></html>',
    encode(sha256('IXBRL_CT_COMPUTATION_' || p_test_run_key), 'hex'),
    'utf8',
    'FRC-2022-01-01',
    jsonb_build_object(
      'generator_version', '1.2.0',
      'generated_at', NOW(),
      'test_artefact', true
    )
  )
  RETURNING id INTO v_ixbrl_computation_id;

  -- Return result
  RETURN jsonb_build_object(
    'filing_id', v_filing_id,
    'company_id', v_company_id,
    'ct_snapshot_id', v_ct_snapshot_id,
    'model_snapshot_id', v_model_snapshot_id,
    'artefact_ids', jsonb_build_object(
      'CT600_XML', v_ct600_artefact_id,
      'IXBRL_ACCOUNTS', v_ixbrl_accounts_id,
      'IXBRL_CT_COMPUTATION', v_ixbrl_computation_id
    ),
    'test_run_key', p_test_run_key,
    'already_existed', false
  );
END;
$function$;

-- public.data_audit_log_prevent_mutation() -> trigger
--   language=plpgsql volatility=volatile security_definer=False search_path=search_path=public, extensions
--   definition_hash=1d49f0c4ae345db9c039c56067d7e793 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.data_audit_log_prevent_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  RAISE EXCEPTION 'data_audit_log is append-only: % is not permitted', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END;
$function$;

-- public.delete_automation_rule_safe(p_rule_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=7fc01064295b50d23c04efb96888de76 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.delete_automation_rule_safe(p_rule_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_rule record;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_rule FROM automation_rules WHERE id = p_rule_id;
  IF v_rule.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rule not found');
  END IF;

  IF NOT public.user_in_organization(v_user_id, v_rule.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF NOT public.user_has_role_at_least(v_user_id, v_rule.organization_id, 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin role required');
  END IF;

  DELETE FROM automation_rules WHERE id = p_rule_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (v_rule.organization_id, 'automation_rule', p_rule_id, 'deleted', v_user_id);

  RETURN jsonb_build_object('success', true, 'rule_id', p_rule_id);
END;
$function$;

-- public.delete_email(queue_name text, message_id bigint) -> boolean
--   language=plpgsql volatility=volatile security_definer=True search_path=(not set)
--   definition_hash=a5bcd44078fb78d17dd27d9ae4a3f967 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.delete_email(queue_name text, message_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN pgmq.delete(queue_name, message_id);
EXCEPTION WHEN undefined_table THEN
  RETURN FALSE;
END;
$function$;

-- public.derive_bank_connection_status(_consent_expires_at timestamp with time zone, _status text, _last_error text, _last_synced_at timestamp with time zone) -> text
--   language=sql volatility=immutable security_definer=False search_path=(not set)
--   definition_hash=92ae7bfb0dfea3b4401aeacda1cc1013 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.derive_bank_connection_status(_consent_expires_at timestamp with time zone, _status text, _last_error text, _last_synced_at timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN _status IS NULL OR _status IN ('disconnected','revoked') THEN 'disconnected'
    WHEN _consent_expires_at IS NOT NULL AND _consent_expires_at < now() THEN 'expired'
    WHEN _last_error IS NOT NULL AND _last_error <> '' THEN 'sync_failed'
    WHEN _consent_expires_at IS NOT NULL
         AND _consent_expires_at < (now() + interval '7 days') THEN 'expiring_soon'
    WHEN _status IN ('ACTIVE','active') THEN 'connected'
    ELSE 'action_required'
  END;
$function$;

-- public.disconnect_mailbox_safe(p_mailbox_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=0ca3f4abef55eb4d0361f644dd535bce (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.disconnect_mailbox_safe(p_mailbox_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_mailbox RECORD;
  v_org_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_mailbox FROM connected_mailboxes WHERE id = p_mailbox_id;
  IF v_mailbox.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mailbox not found');
  END IF;

  v_org_id := v_mailbox.organization_id;
  
  -- Only owner/admin can disconnect mailboxes (or the mailbox owner themselves)
  IF v_mailbox.user_id != v_user_id AND NOT user_has_role_at_least(v_user_id, v_org_id, 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: admin+ required or must be mailbox owner');
  END IF;

  -- Soft delete by setting is_active = false
  UPDATE connected_mailboxes SET
    is_active = false,
    access_token = NULL,
    refresh_token = NULL,
    updated_at = now()
  WHERE id = p_mailbox_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata, actor_role)
  VALUES (v_org_id, 'connected_mailbox', p_mailbox_id, 'disconnected', v_user_id,
    jsonb_build_object('email_address', v_mailbox.email_address, 'provider', v_mailbox.provider),
    (SELECT role FROM organization_users WHERE user_id = v_user_id AND organization_id = v_org_id LIMIT 1));

  RETURN jsonb_build_object('success', true, 'mailbox_id', p_mailbox_id);
END;
$function$;

-- public.dispose_fixed_asset(p_asset_id uuid, p_disposal_date date, p_proceeds numeric, p_proceeds_account_id uuid, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=7a8b374bdacc584455fd1f75e123e584 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.dispose_fixed_asset(p_asset_id uuid, p_disposal_date date, p_proceeds numeric, p_proceeds_account_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_asset public.fixed_assets%ROWTYPE;
  v_user uuid := auth.uid();
  v_accum_acct uuid;
  v_asset_acct uuid;
  v_gain_loss numeric;
  v_nbv numeric;
  v_entries jsonb;
  v_result jsonb;
  v_gain_loss_acct uuid;
  v_reference text;
BEGIN
  SELECT * INTO v_asset FROM public.fixed_assets WHERE id = p_asset_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Asset not found'; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.organization_users WHERE user_id = v_user AND organization_id = v_asset.organization_id) THEN
    RAISE EXCEPTION 'Cross-tenant access denied';
  END IF;

  IF v_asset.status = 'disposed' THEN
    RAISE EXCEPTION 'Asset already disposed';
  END IF;

  v_accum_acct := COALESCE(v_asset.accumulated_depreciation_account_id,
    (SELECT accumulated_depreciation_account_id FROM public.org_settings WHERE organization_id = v_asset.organization_id LIMIT 1));
  v_asset_acct := COALESCE(v_asset.fixed_asset_account_id,
    (SELECT fixed_assets_account_id FROM public.org_settings WHERE organization_id = v_asset.organization_id LIMIT 1));
  v_gain_loss_acct := COALESCE(v_asset.depreciation_expense_account_id,
    (SELECT depreciation_expense_account_id FROM public.org_settings WHERE organization_id = v_asset.organization_id LIMIT 1));

  IF v_accum_acct IS NULL OR v_asset_acct IS NULL OR p_proceeds_account_id IS NULL OR v_gain_loss_acct IS NULL THEN
    RAISE EXCEPTION 'Disposal accounts not fully configured';
  END IF;

  v_nbv := v_asset.cost - COALESCE(v_asset.accumulated_depreciation,0);
  v_gain_loss := COALESCE(p_proceeds,0) - v_nbv; -- positive = gain, negative = loss
  v_reference := 'DISP-' || p_asset_id::text || '-' || to_char(p_disposal_date, 'YYYYMMDD');

  -- Build entries:
  -- Dr Proceeds account (cash/bank or receivable) for proceeds
  -- Dr Accumulated depreciation
  -- Cr Fixed asset (cost)
  -- Dr/Cr Gain or Loss balancing line
  v_entries := jsonb_build_array(
    jsonb_build_object('account_id', p_proceeds_account_id, 'debit', COALESCE(p_proceeds,0), 'credit', 0,
                       'description', 'Disposal proceeds: ' || v_asset.asset_name),
    jsonb_build_object('account_id', v_accum_acct, 'debit', COALESCE(v_asset.accumulated_depreciation,0), 'credit', 0,
                       'description', 'Remove accumulated depreciation: ' || v_asset.asset_name),
    jsonb_build_object('account_id', v_asset_acct, 'debit', 0, 'credit', v_asset.cost,
                       'description', 'Remove cost: ' || v_asset.asset_name)
  );

  IF v_gain_loss > 0 THEN
    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object('account_id', v_gain_loss_acct, 'debit', 0, 'credit', v_gain_loss,
                         'description', 'Gain on disposal: ' || v_asset.asset_name));
  ELSIF v_gain_loss < 0 THEN
    v_entries := v_entries || jsonb_build_array(
      jsonb_build_object('account_id', v_gain_loss_acct, 'debit', -v_gain_loss, 'credit', 0,
                         'description', 'Loss on disposal: ' || v_asset.asset_name));
  END IF;

  v_result := public.post_to_ledger(
    p_organization_id := v_asset.organization_id,
    p_client_id       := NULL,
    p_company_id      := v_asset.company_id,
    p_journal_date    := p_disposal_date,
    p_reference       := v_reference,
    p_description     := 'Disposal - ' || v_asset.asset_name,
    p_journal_type    := 'DISPOSAL',
    p_source_type     := 'ASSET_DISPOSAL',
    p_source_id       := p_asset_id,
    p_currency        := 'GBP',
    p_fx_rate         := 1.0,
    p_created_by      := v_user,
    p_entries         := v_entries,
    p_lock_override_reason := NULL,
    p_idempotency_key := v_reference
  );

  IF (v_result->>'success')::boolean IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'post_to_ledger failed: %', v_result->>'error';
  END IF;

  UPDATE public.fixed_assets
     SET status='disposed', disposal_date=p_disposal_date, disposal_proceeds=p_proceeds, updated_at=now()
   WHERE id=p_asset_id;

  INSERT INTO public.fixed_asset_transactions(
    fixed_asset_id, organization_id, accounting_period_start, accounting_period_end,
    transaction_type, amount_net, disposal_proceeds, notes, created_by)
  VALUES (p_asset_id, v_asset.organization_id,
          date_trunc('year', p_disposal_date)::date,
          (date_trunc('year', p_disposal_date) + interval '1 year - 1 day')::date,
          'DISPOSAL', v_nbv, p_proceeds, p_reason, v_user);

  INSERT INTO public.bookkeeping_audit_log(organization_id, entity_type, entity_id, action, actor_id, after_state)
  VALUES (v_asset.organization_id, 'fixed_asset', p_asset_id, 'dispose_asset', v_user,
          jsonb_build_object('disposal_date', p_disposal_date, 'proceeds', p_proceeds, 'nbv', v_nbv,
                             'gain_loss', v_gain_loss, 'journal_id', v_result->>'journal_id', 'reason', p_reason));

  RETURN jsonb_build_object('success', true, 'journal_id', v_result->>'journal_id',
                            'nbv', v_nbv, 'gain_loss', v_gain_loss);
END; $function$;

-- public.el_signature_progress(p_engagement_letter_id uuid) -> jsonb
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=20fe6aff754603e57b28e792e37fd122 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.el_signature_progress(p_engagement_letter_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule   text;
  v_total  int := 0;
  v_signed int := 0;
BEGIN
  IF p_engagement_letter_id IS NULL THEN
    RETURN jsonb_build_object(
      'has_signatories', false, 'signing_rule', 'all',
      'required_total', 0, 'required_signed', 0, 'satisfied', false
    );
  END IF;

  SELECT el.signing_rule INTO v_rule
    FROM public.engagement_letters el
   WHERE el.id = p_engagement_letter_id;

  -- Unknown letter id, or a NULL rule on an older row, both mean the strict default.
  v_rule := COALESCE(v_rule, 'all');

  -- Only `required` signatories count towards the rule; optional (cc'd) signatories may
  -- sign but can never hold the engagement up.
  SELECT count(*) FILTER (WHERE required),
         count(*) FILTER (WHERE required AND signed_at IS NOT NULL)
    INTO v_total, v_signed
    FROM public.engagement_letter_signatories
   WHERE engagement_letter_id = p_engagement_letter_id;

  RETURN jsonb_build_object(
    'has_signatories', (v_total > 0),
    'signing_rule',    v_rule,
    'required_total',  v_total,
    'required_signed', v_signed,
    'satisfied', CASE
      WHEN v_total = 0        THEN false
      WHEN v_rule  = 'any'    THEN v_signed >= 1
      ELSE                         v_signed = v_total
    END
  );
END;
$function$;

-- public.email_queue_dispatch() -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=""
--   definition_hash=df093f10ca7b51980cbaf70a670b5519 (hash of the ORIGINAL, pre-sanitization body)
--   *** SANITIZED-BODY: placeholders substituted below; this body is NOT executable ***
CREATE OR REPLACE FUNCTION public.email_queue_dispatch()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pgmq.q_auth_emails)
     AND NOT EXISTS (SELECT 1 FROM pgmq.q_transactional_emails) THEN
    BEGIN
      -- Serialize disarm against email_queue_wake on a shared advisory lock, then
      -- re-read under it: an enqueue racing the unschedule either committed (we
      -- see its row and leave the cron) or waits and re-arms after we commit.
      PERFORM pg_catalog.pg_advisory_xact_lock(7700000000000001);
      IF EXISTS (SELECT 1 FROM pgmq.q_auth_emails)
         OR EXISTS (SELECT 1 FROM pgmq.q_transactional_emails) THEN
        RETURN;
      END IF;
      PERFORM cron.unschedule('process-email-queue');
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'email_queue_dispatch: cron unschedule failed: %', SQLERRM;
    END;
    RETURN;
  END IF;

  IF (SELECT retry_after_until FROM public.email_send_state WHERE id = 1) > now() THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := '[SOURCE-PROJECT-EDGE-FUNCTION-URL-REMOVED: process-email-queue]',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Lovable-Context', 'cron',
      'Authorization', '[AUTH-SCHEME-REDACTED] ' || (
        SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'email_queue_service_role_key'
      )
    ),
    body := '{}'::jsonb
  );
END;
$function$;

-- public.email_queue_wake() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=""
--   definition_hash=d6e71dd6b162959616761080d1adc1c7 (hash of the ORIGINAL, pre-sanitization body)
--   *** SANITIZED-BODY: placeholders substituted below; this body is NOT executable ***
CREATE OR REPLACE FUNCTION public.email_queue_wake()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  -- Runs inside the enqueue transaction; the outer handler guarantees nothing
  -- below can roll back the customer's email. Shared advisory lock serializes
  -- arming against email_queue_dispatch's disarm.
  PERFORM pg_catalog.pg_advisory_xact_lock(7700000000000001);
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'process-email-queue') THEN
    BEGIN
      PERFORM cron.schedule('process-email-queue', '5 seconds', $cron$ SELECT public.email_queue_dispatch(); $cron$);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'email_queue_wake: cron schedule failed: %', SQLERRM;
    END;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := '[SOURCE-PROJECT-EDGE-FUNCTION-URL-REMOVED: process-email-queue]',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Lovable-Context', 'cron',
        'Authorization', '[AUTH-SCHEME-REDACTED] ' || (
          SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'email_queue_service_role_key'
        )
      ),
      body := '{}'::jsonb
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'email_queue_wake failed (enqueue preserved): %', SQLERRM;
  RETURN NULL;
END;
$function$;

-- public.emit_automation_event(p_organization_id uuid, p_event_type text, p_entity_type text, p_entity_id uuid, p_old_value jsonb, p_new_value jsonb, p_metadata jsonb) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=7ad0b1419de5d88e7b2a2200c3d5b752 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.emit_automation_event(p_organization_id uuid, p_event_type text, p_entity_type text, p_entity_id uuid, p_old_value jsonb DEFAULT NULL::jsonb, p_new_value jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id UUID;
BEGIN
  INSERT INTO public.automation_events (
    organization_id,
    event_type,
    entity_type,
    entity_id,
    old_value,
    new_value,
    metadata
  ) VALUES (
    p_organization_id,
    p_event_type,
    p_entity_type,
    p_entity_id,
    p_old_value,
    p_new_value,
    p_metadata
  )
  RETURNING id INTO v_event_id;
  
  RETURN v_event_id;
END;
$function$;

-- public.enforce_audit_log_actor_role() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=0ab2097e1791e26fd4035334c28158d9 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.enforce_audit_log_actor_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  SELECT role INTO NEW.actor_role
  FROM organization_users WHERE user_id = NEW.user_id AND organization_id = NEW.organization_id LIMIT 1;
