  END IF;
END;
$function$;

-- public.enforce_signatory_rules() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=744b511d46c7951ab3d2869aac441c59 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.enforce_signatory_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_signatory THEN
    IF NEW.resigned_at IS NOT NULL THEN
      NEW.is_signatory := false;
    ELSIF (
      SELECT count(*) FROM public.company_officers
      WHERE company_id = NEW.company_id AND is_signatory AND id <> NEW.id
    ) >= 10 THEN
      RAISE EXCEPTION 'A company can have at most 10 signatories';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

-- public.enforce_vat_filing_gate() -> trigger
--   language=plpgsql volatility=volatile security_definer=False search_path=(not set)
--   definition_hash=3def4322e57c79472f7f6ccfd37ed4c3 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.enforce_vat_filing_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF (NEW.status = 'submitted' AND COALESCE(OLD.status, '') <> 'submitted')
     OR (NEW.submitted_at IS NOT NULL AND OLD.submitted_at IS NULL) THEN
    IF NEW.model_snapshot_id IS NULL OR NEW.filing_approved_at IS NULL THEN
      RAISE EXCEPTION 'A VAT return cannot be submitted without an approved filing snapshot. Approve it for filing first.'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

-- public.enqueue_email(queue_name text, payload jsonb) -> bigint
--   language=plpgsql volatility=volatile security_definer=True search_path=(not set)
--   definition_hash=803146cb95f9a6def9330571711ca967 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.enqueue_email(queue_name text, payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN pgmq.send(queue_name, payload);
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN pgmq.send(queue_name, payload);
END;
$function$;

-- public.enqueue_unsubscribe_token(p_org_id uuid, p_email text, p_category text) -> text
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6ccb53c375907c34ba80fffa098ee5a4 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.enqueue_unsubscribe_token(p_org_id uuid, p_email text, p_category text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_token text;
BEGIN
  v_token := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  INSERT INTO email_unsubscribe_tokens(organization_id, email, token, category)
  VALUES (p_org_id, p_email, v_token, p_category);
  RETURN v_token;
END;$function$;

-- public.ensure_client_document_folder(p_client_id uuid, p_folder_name text) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=c883da3a72e2be7272e1a8ec1ee63bf8 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.ensure_client_document_folder(p_client_id uuid, p_folder_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_folder_id uuid;
  v_org uuid;
BEGIN
  IF p_client_id IS NULL OR p_folder_name IS NULL THEN
    RETURN NULL;
  END IF;

  -- Tolerate absence of document_folders table to avoid breaking environments
  IF to_regclass('public.document_folders') IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT organization_id INTO v_org FROM clients WHERE id = p_client_id;
  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  EXECUTE format(
    'SELECT id FROM public.document_folders
       WHERE client_id = %L AND lower(name) = lower(%L)
       LIMIT 1', p_client_id, p_folder_name
  ) INTO v_folder_id;

  IF v_folder_id IS NOT NULL THEN
    RETURN v_folder_id;
  END IF;

  EXECUTE format(
    'INSERT INTO public.document_folders (organization_id, client_id, name)
       VALUES (%L, %L, %L) RETURNING id',
     v_org, p_client_id, p_folder_name
  ) INTO v_folder_id;

  RETURN v_folder_id;
END;
$function$;

-- public.ensure_default_templates_for_org(_org_id uuid) -> integer
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=557494b7f8835f57fa0c7beb8d30481f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.ensure_default_templates_for_org(_org_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inserted_count integer := 0;
BEGIN
  IF _org_id IS NULL THEN
    RETURN 0;
  END IF;

  WITH ins AS (
    INSERT INTO public.templates (
      organization_id, name, description, type, service, status,
      tags, content, requires_unsubscribe_link, required_merge_fields,
      recipient_rule, source_template_id, version_number
    )
    SELECT
      _org_id,
      sys.name,
      sys.description,
      sys.type,
      sys.service,
      'inactive',
      sys.tags,
      sys.content,
      sys.requires_unsubscribe_link,
      sys.required_merge_fields,
      sys.recipient_rule,
      sys.id,
      1
    FROM public.templates sys
    WHERE sys.organization_id IS NULL
    ON CONFLICT (organization_id, source_template_id)
      WHERE source_template_id IS NOT NULL AND organization_id IS NOT NULL
      DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO inserted_count FROM ins;

  RETURN inserted_count;
END;
$function$;

-- public.ensure_onboarding_access_token() -> trigger
--   language=plpgsql volatility=volatile security_definer=False search_path=search_path=public, extensions
--   definition_hash=476508cf3253ea5e7c42e513a9edea55 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.ensure_onboarding_access_token()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF NEW.access_token IS NULL THEN
    NEW.access_token := public.gen_onboarding_access_token();
  END IF;
  IF NEW.access_token_expires_at IS NULL THEN
    NEW.access_token_expires_at := now() + interval '90 days';
  END IF;
  RETURN NEW;
END;
$function$;

-- public.ensure_org_settings(_org_id uuid) -> org_settings
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=f040648fa0d30e4e0fbabeca0fc1f0f8 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.ensure_org_settings(_org_id uuid)
 RETURNS org_settings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_settings org_settings;
BEGIN
  SELECT * INTO v_settings FROM org_settings WHERE organization_id = _org_id;
  
  IF v_settings.organization_id IS NULL THEN
    INSERT INTO org_settings (organization_id)
    VALUES (_org_id)
    RETURNING * INTO v_settings;
  END IF;
  
  RETURN v_settings;
END;
$function$;

-- public.entity_has_active_bookkeeping(_client_id uuid, _company_id uuid) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=fafd08f97a29198d02f0cbe60cc5af84 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.entity_has_active_bookkeeping(_client_id uuid, _company_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.engagements e
    JOIN public.services_catalog s ON s.id = e.service_id
    WHERE e.status = 'active'
      AND s.code IN ('BOOKKEEPING','BK-MONTHLY','BK-QUARTERLY')
      AND ((_client_id IS NOT NULL AND e.client_id = _client_id)
        OR (_company_id IS NOT NULL AND e.company_id = _company_id))
  );
$function$;

-- public.explain_bank_transaction(p_bank_transaction_id uuid, p_contra_account_id uuid, p_vat_code_id uuid, p_vat_amount numeric, p_description text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=0e74b951ceeb1063de55c5e02118eb75 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.explain_bank_transaction(p_bank_transaction_id uuid, p_contra_account_id uuid, p_vat_code_id uuid DEFAULT NULL::uuid, p_vat_amount numeric DEFAULT 0, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_txn RECORD;
  v_user_id UUID := auth.uid();
  v_result JSONB;
  v_before JSONB;
BEGIN
  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank transaction not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = v_user_id AND organization_id = v_txn.organization_id
  ) THEN
    RAISE EXCEPTION 'Not authorised for organization';
  END IF;

  IF upper(COALESCE(v_txn.status,'')) IN ('MATCHED','RECONCILED') THEN
    RAISE EXCEPTION 'Transaction is already %; unmatch first', v_txn.status;
  END IF;

  PERFORM assert_no_locked_period_write(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
  );

  v_before := to_jsonb(v_txn);

  v_result := public.post_bank_transaction(
    p_bank_transaction_id := p_bank_transaction_id,
    p_contra_account_id   := p_contra_account_id,
    p_vat_code_id         := p_vat_code_id,
    p_vat_amount          := COALESCE(p_vat_amount, 0),
    p_description         := COALESCE(p_description, v_txn.description)
  );

  INSERT INTO public.bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'explain_bank_transaction', v_user_id,
    v_before,
    jsonb_build_object('contra_account_id', p_contra_account_id, 'vat_code_id', p_vat_code_id,
                       'vat_amount', p_vat_amount),
    jsonb_build_object('post_result', v_result)
  );

  RETURN v_result;
END;
$function$;

-- public.finalize_workpaper_safe(p_workpaper_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=a0ac9750d06f81529f6e55234ad4eb52 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.finalize_workpaper_safe(p_workpaper_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_workpaper record;
  v_filing_id uuid;
BEGIN
  -- Fetch workpaper
  SELECT * INTO v_workpaper FROM workpaper_instances WHERE id = p_workpaper_id;
  
  IF v_workpaper.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Workpaper not found');
  END IF;
  
  -- Check permission
  IF NOT can_finalize_workpapers(auth.uid(), v_workpaper.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: Only managers and above can finalize workpapers');
  END IF;
  
  -- Update workpaper
  UPDATE workpaper_instances SET 
    status = 'finalised',
    finalised_by = auth.uid(),
    finalised_at = now(),
    locked = true
  WHERE id = p_workpaper_id;
  
  -- Create filing record
  INSERT INTO filings (
    organization_id, job_id, workpaper_instance_id, client_id, company_id,
    filing_type, filing_body, period_start, period_end, tax_year,
    filing_data, status
  ) VALUES (
    v_workpaper.organization_id, v_workpaper.job_id, p_workpaper_id,
    v_workpaper.client_id, v_workpaper.company_id, v_workpaper.service_type,
    'HMRC', v_workpaper.period_start, v_workpaper.period_end,
    v_workpaper.period_label, v_workpaper.field_values, 'draft'
  )
  RETURNING id INTO v_filing_id;
  
  -- Write audit logs
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, field_name, old_value, new_value, user_id)
  VALUES (v_workpaper.organization_id, 'workpaper_instance', p_workpaper_id, 'finalise', 'status', v_workpaper.status, 'finalised', auth.uid());
  
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (v_workpaper.organization_id, 'filing', v_filing_id, 'create', auth.uid());
  
  RETURN jsonb_build_object('success', true, 'filing_id', v_filing_id);
END;
$function$;

-- public.find_entities_by_email(_org_id uuid, _email text) -> TABLE(entity_type text, entity_id uuid, entity_name text, match_source text)
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=3a80327f22260c9f839435e55f8a5eed (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.find_entities_by_email(_org_id uuid, _email text)
 RETURNS TABLE(entity_type text, entity_id uuid, entity_name text, match_source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  -- Check client primary emails
  SELECT 
    'client'::TEXT as entity_type,
    c.id as entity_id,
    (c.first_name || ' ' || c.last_name)::TEXT as entity_name,
    'primary'::TEXT as match_source
  FROM clients c
  WHERE c.organization_id = _org_id
    AND LOWER(c.email) = LOWER(_email)
  
  UNION ALL
  
  -- Check company primary emails
  SELECT 
    'company'::TEXT,
    co.id,
    co.company_name::TEXT,
    'primary'::TEXT
  FROM companies co
  WHERE co.organization_id = _org_id
    AND LOWER(co.email) = LOWER(_email)
  
  UNION ALL
  
  -- Check contacts linked to clients
  SELECT DISTINCT
    'client'::TEXT,
    ct.client_id,
    (cl.first_name || ' ' || cl.last_name)::TEXT,
    'contact'::TEXT
  FROM contacts ct
  JOIN clients cl ON cl.id = ct.client_id
  WHERE ct.organization_id = _org_id
    AND LOWER(ct.email) = LOWER(_email)
    AND ct.client_id IS NOT NULL
  
  UNION ALL
  
  -- Check contacts linked to companies
  SELECT DISTINCT
    'company'::TEXT,
    ct.company_id,
    co.company_name::TEXT,
    'contact'::TEXT
  FROM contacts ct
  JOIN companies co ON co.id = ct.company_id
  WHERE ct.organization_id = _org_id
    AND LOWER(ct.email) = LOWER(_email)
    AND ct.company_id IS NOT NULL;
END;
$function$;

-- public.flag_engagement_letter_on_change() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6bc9f0dba0251f22ce3af0b392b0f773 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.flag_engagement_letter_on_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- If service_id or service_config (containing fees) changed, flag EL required
  IF (OLD.service_id IS DISTINCT FROM NEW.service_id) OR
     (OLD.service_config IS DISTINCT FROM NEW.service_config) THEN
    NEW.engagement_letter_required := true;
  END IF;
  RETURN NEW;
END;
$function$;

-- public.flush_email_queue_now(p_organization_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=4584e0be882888f7318cfd98822575f0 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.flush_email_queue_now(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_count integer;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  UPDATE public.email_queue
     SET scheduled_at = now(),
         updated_at = now()
   WHERE organization_id = p_organization_id
     AND status IN ('pending','queued')
     AND scheduled_at > now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'flushed', v_count);
END;
$function$;

