-- public.generate_filing_approval_token(p_filing_id uuid) -> text
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=0c3194527b8aa8e687c101054f016da1 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.generate_filing_approval_token(p_filing_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_token TEXT;
BEGIN
  -- Generate secure random token
  v_token := encode(gen_random_bytes(32), 'hex');
  
  -- Update filing with token (expires in 7 days)
  UPDATE public.filings
  SET approval_token = v_token,
      approval_token_expires_at = NOW() + INTERVAL '7 days'
  WHERE id = p_filing_id;
  
  RETURN v_token;
END;
$function$;

