-- public.get_user_permissions(_org_id uuid) -> jsonb
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=a433e7df9493892dc62843fed2223807 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.get_user_permissions(_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_role text;
BEGIN
  v_user_id := auth.uid();
  
  SELECT role INTO v_role FROM organization_users
  WHERE user_id = v_user_id AND organization_id = _org_id;
  
  IF v_role IS NULL THEN
    RETURN jsonb_build_object('role', null, 'permissions', jsonb_build_object());
  END IF;
  
  RETURN jsonb_build_object(
    'role', v_role,
    'permissions', jsonb_build_object(
      'can_manage_practice_settings', v_role IN ('owner', 'admin'),
      'can_manage_integrations', v_role IN ('owner', 'admin'),
      'can_manage_automation_rules', v_role IN ('owner', 'admin', 'manager'),
      'can_finalize_workpapers', v_role IN ('owner', 'admin', 'manager'),
      'can_approve_filings', v_role IN ('owner', 'admin', 'manager'),
      'can_submit_filings', v_role IN ('owner', 'admin', 'manager'),
      'can_view_all_jobs', v_role IN ('owner', 'admin', 'manager', 'staff'),
      'can_manage_billing', v_role = 'owner',
      'can_manage_team', v_role IN ('owner', 'admin'),
      'can_manage_templates', v_role IN ('owner', 'admin', 'manager'),
      'can_create_jobs', v_role IN ('owner', 'admin', 'manager', 'staff'),
      'can_view_sensitive_data', v_role IN ('owner', 'admin', 'manager'),
      'can_delete_records', v_role IN ('owner', 'admin')
    )
  );
END;
$function$;

-- public.get_user_role(_user_id uuid, _org_id uuid) -> text
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=d523fea3649be8bd0761bff190167d11 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.get_user_role(_user_id uuid, _org_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT role::text
  FROM public.organization_users
  WHERE user_id = _user_id
    AND organization_id = _org_id
  LIMIT 1
$function$;

-- public.get_vat_9box_detail(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_from date, p_to date) -> jsonb
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=e842f857a0a5df7ae84ca7ee48dfa276 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.get_vat_9box_detail(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_boxes jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = p_organization_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'Not a member of organization %', p_organization_id;
  END IF;

  IF (p_client_id IS NULL AND p_company_id IS NULL)
     OR (p_client_id IS NOT NULL AND p_company_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Exactly one of client_id or company_id must be provided';
  END IF;

  -- Pull invoice lines (sales) for the entity in the period
  WITH inv AS (
    SELECT
      il.id,
      i.issue_date AS tx_date,
      i.invoice_number AS doc_ref,
      'invoice'::text AS source_type,
      il.invoice_id AS source_id,
      il.description,
      COALESCE(vc.code, 'UNKNOWN')           AS vat_code,
      COALESCE(vc.rate, il.vat_rate, 0)      AS vat_rate,
      COALESCE(vc.vat_type, 'OUTPUT')        AS vat_type,
      ABS(COALESCE(il.net_amount,0))         AS net_amount,
      ABS(COALESCE(il.vat_amount,0))         AS vat_amount,
      'SALES'::text AS direction
    FROM public.invoice_lines il
    JOIN public.invoices i ON i.id = il.invoice_id
    LEFT JOIN public.vat_codes vc ON vc.id = il.vat_code_id
    WHERE i.organization_id = p_organization_id
      AND i.is_posted = true
      AND i.issue_date BETWEEN p_from AND p_to
      AND ( (p_client_id IS NOT NULL AND i.client_id = p_client_id)
         OR (p_company_id IS NOT NULL AND i.company_id = p_company_id) )
  ),
  bil AS (
    SELECT
      bl.id,
      b.issue_date AS tx_date,
      b.bill_number AS doc_ref,
      'bill'::text AS source_type,
      bl.bill_id AS source_id,
      bl.description,
      COALESCE(vc.code, 'UNKNOWN')          AS vat_code,
      COALESCE(vc.rate, bl.vat_rate, 0)     AS vat_rate,
      COALESCE(vc.vat_type, 'INPUT')        AS vat_type,
      ABS(COALESCE(bl.net_amount,0))        AS net_amount,
      ABS(COALESCE(bl.vat_amount,0))        AS vat_amount,
      'PURCHASES'::text AS direction
    FROM public.bill_lines bl
    JOIN public.bills b ON b.id = bl.bill_id
    LEFT JOIN public.vat_codes vc ON vc.id = bl.vat_code_id
    WHERE b.organization_id = p_organization_id
      AND b.is_posted = true
      AND b.issue_date BETWEEN p_from AND p_to
      AND ( (p_client_id IS NOT NULL AND b.client_id = p_client_id)
         OR (p_company_id IS NOT NULL AND b.company_id = p_company_id) )
  ),
  lines AS (
    SELECT * FROM inv UNION ALL SELECT * FROM bil
  ),
  -- Box mapping helper (mirrors src/lib/vat-ledger-aggregator.ts)
  mapped AS (
    SELECT
      l.*,
      CASE
        WHEN l.direction='SALES'     AND l.vat_code IN ('S20','S5','RC') THEN l.vat_amount ELSE 0 END AS box1,
      CASE
        WHEN l.direction='SALES'     AND l.vat_code = 'EU_GOODS'         THEN l.vat_amount ELSE 0 END AS box2,
      CASE
        WHEN l.direction='PURCHASES' AND l.vat_code IN ('P20','P5','RC','IMP','EU_GOODS') THEN l.vat_amount ELSE 0 END AS box4,
      CASE WHEN l.direction='SALES'     THEN l.net_amount ELSE 0 END AS box6,
      CASE WHEN l.direction='PURCHASES' THEN l.net_amount ELSE 0 END AS box7,
      CASE WHEN l.direction='SALES'     AND l.vat_code='EXP'      THEN l.net_amount ELSE 0 END AS box8,
      CASE WHEN l.direction='PURCHASES' AND l.vat_code='EU_GOODS' THEN l.net_amount ELSE 0 END AS box9
    FROM lines l
  ),
  totals AS (
    SELECT
      ROUND(SUM(box1)::numeric, 2) AS b1,
      ROUND(SUM(box2)::numeric, 2) AS b2,
      ROUND(SUM(box4)::numeric, 2) AS b4,
      ROUND(SUM(box6)::numeric, 0) AS b6,
      ROUND(SUM(box7)::numeric, 0) AS b7,
      ROUND(SUM(box8)::numeric, 0) AS b8,
      ROUND(SUM(box9)::numeric, 0) AS b9
    FROM mapped
  ),
  per_code AS (
    SELECT
      vat_code,
      MAX(vat_rate) AS vat_rate,
      MAX(vat_type) AS vat_type,
      COUNT(*)::int AS line_count,
      ROUND(SUM(net_amount)::numeric, 2) AS total_net,
      ROUND(SUM(vat_amount)::numeric, 2) AS total_vat,
      jsonb_agg(jsonb_build_object(
        'id', id,
        'tx_date', tx_date,
        'doc_ref', doc_ref,
        'source_type', source_type,
        'source_id', source_id,
        'description', description,
        'net_amount', net_amount,
        'vat_amount', vat_amount,
        'direction', direction
      ) ORDER BY tx_date, doc_ref) AS transactions
    FROM mapped
    GROUP BY vat_code
  )
  SELECT jsonb_build_object(
    'period_from', p_from,
    'period_to',   p_to,
    'organization_id', p_organization_id,
    'client_id',  p_client_id,
    'company_id', p_company_id,
    'boxes', (SELECT jsonb_build_object(
        'box1_vat_on_sales',           COALESCE(b1,0),
        'box2_vat_on_acquisitions',    COALESCE(b2,0),
        'box3_total_vat_due',          ROUND((COALESCE(b1,0)+COALESCE(b2,0))::numeric, 2),
        'box4_vat_reclaimed',          COALESCE(b4,0),
        'box5_net_vat_due',            ROUND(ABS((COALESCE(b1,0)+COALESCE(b2,0))-COALESCE(b4,0))::numeric, 2),
        'box6_total_sales_ex_vat',     COALESCE(b6,0),
        'box7_total_purchases_ex_vat', COALESCE(b7,0),
        'box8_goods_supplied_ex_vat',  COALESCE(b8,0),
        'box9_acquisitions_ex_vat',    COALESCE(b9,0)
      ) FROM totals),
    'codes', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'vat_code', vat_code,
        'vat_rate', vat_rate,
        'vat_type', vat_type,
        'line_count', line_count,
        'total_net', total_net,
        'total_vat', total_vat,
        'transactions', transactions
      ) ORDER BY vat_code) FROM per_code), '[]'::jsonb),
    'generated_at', now()
  )
  INTO v_boxes;

  RETURN v_boxes;
END;
$function$;

-- public.governance_mask_value(p_field_key text, p_val text) -> text
--   language=plpgsql volatility=stable security_definer=False search_path=search_path=public, extensions
--   definition_hash=ce1ead5674eae15ee2fbf116db84fe87 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.governance_mask_value(p_field_key text, p_val text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_sens text;
BEGIN
  IF p_val IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT sensitivity INTO v_sens
    FROM public.data_requirements
    WHERE field_key = p_field_key;

  IF v_sens IS NULL OR v_sens = 'sensitive' THEN
    IF p_field_key IN ('person.nino', 'person.utr') THEN
      RETURN '••••' || right(p_val, 2);
    END IF;
    RETURN '••••';
  END IF;

  RETURN p_val;
END;
$function$;

-- public.governance_record_merge_field(p_organization_id uuid, p_subject_kind text, p_subject_id uuid, p_field_key text, p_old_value text, p_new_value text, p_actor uuid) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public, extensions
--   definition_hash=a86bf2fd62411ee8be45650ab2f66b7f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.governance_record_merge_field(p_organization_id uuid, p_subject_kind text, p_subject_id uuid, p_field_key text, p_old_value text, p_new_value text, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  INSERT INTO public.data_point_state (
    organization_id, subject_kind, subject_id, field_key, status, source, updated_at
  )
  VALUES (
    p_organization_id, p_subject_kind, p_subject_id, p_field_key, 'provided', 'client', now()
  )
  ON CONFLICT (organization_id, subject_kind, subject_id, field_key)
  DO UPDATE SET status = 'provided', source = 'client', updated_at = now();

  INSERT INTO public.data_audit_log (
    organization_id, subject_kind, subject_id, field_key,
    old_value_masked, new_value_masked, actor, origin, event_type
  )
  VALUES (
    p_organization_id, p_subject_kind, p_subject_id, p_field_key,
    public.governance_mask_value(p_field_key, p_old_value),
    public.governance_mask_value(p_field_key, p_new_value),
    p_actor, 'onboarding', 'onboarding_merge'
  );
END;
$function$;

-- public.grant_person_portal_access(p_person_id uuid, p_user_email text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=0e1ca2f3ccdd1962fb9d37d36ea522b6 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.grant_person_portal_access(p_person_id uuid, p_user_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id uuid;
  v_linked_client_id uuid;
  v_target_user_id uuid;
  v_company record;
  v_granted int := 0;
  v_skipped int := 0;
  v_already_active boolean;
BEGIN
  SELECT organization_id, linked_client_id
  INTO v_organization_id, v_linked_client_id
  FROM public.company_persons WHERE id = p_person_id;

  IF v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Person not found: %', p_person_id;
  END IF;

  IF NOT public.user_has_organization_access(v_organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT id INTO v_target_user_id FROM auth.users WHERE email = p_user_email LIMIT 1;

  IF v_linked_client_id IS NOT NULL THEN
    v_already_active := false;
    IF v_target_user_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1 FROM public.portal_access
        WHERE client_id = v_linked_client_id
          AND user_id = v_target_user_id
          AND is_active
          AND status <> 'revoked'
      ) INTO v_already_active;
    END IF;

    IF v_already_active THEN
      v_skipped := v_skipped + 1;
    ELSE
      PERFORM public.lifecycle_grant_portal_access('client', v_linked_client_id, p_user_email);
      v_granted := v_granted + 1;
    END IF;
  END IF;

  FOR v_company IN
    SELECT DISTINCT company_id
    FROM public.company_officers
    WHERE person_id = p_person_id AND resigned_at IS NULL
  LOOP
    v_already_active := false;
    IF v_target_user_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1 FROM public.portal_access
        WHERE company_id = v_company.company_id
          AND user_id = v_target_user_id
          AND is_active
          AND status <> 'revoked'
      ) INTO v_already_active;
    END IF;

    IF v_already_active THEN
      v_skipped := v_skipped + 1;
    ELSE
      PERFORM public.lifecycle_grant_portal_access('company', v_company.company_id, p_user_email);
      v_granted := v_granted + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'person_id', p_person_id,
    'granted', v_granted,
    'skipped', v_skipped
  );
END;
$function$;

-- public.handle_accounts_snapshot_change() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=2cec5e192b3285021f6d5e4e6e265b6a (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.handle_accounts_snapshot_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filing RECORD;
  v_approval RECORD;
  v_ct_snapshot RECORD;
BEGIN
  -- Find all filings that reference this accounts snapshot
  FOR v_filing IN 
    SELECT f.* FROM public.filings f
    WHERE f.accounts_snapshot_id = OLD.id
  LOOP
    -- Revoke ACCOUNTS approval
    FOR v_approval IN 
      SELECT * FROM public.filing_approvals 
      WHERE filing_id = v_filing.id 
      AND approval_scope = 'ACCOUNTS' 
      AND revoked_at IS NULL
    LOOP
      PERFORM public.revoke_approval_with_audit(
        v_approval.id,
        OLD.id,
        OLD.snapshot_hash,
        NEW.id,
        NEW.snapshot_hash,
        'UNDERLYING_ACCOUNTS_CHANGED',
        jsonb_build_object('trigger', 'accounts_snapshot_update')
      );
    END LOOP;
    
    -- Revoke CT600 approval (CT depends on accounts)
    FOR v_approval IN 
      SELECT * FROM public.filing_approvals 
      WHERE filing_id = v_filing.id 
      AND approval_scope = 'CT600' 
      AND revoked_at IS NULL
    LOOP
      PERFORM public.revoke_approval_with_audit(
        v_approval.id,
        v_filing.ct_snapshot_id,
        NULL,
        NULL,
        NULL,
        'UNDERLYING_ACCOUNTS_CHANGED',
        jsonb_build_object('trigger', 'accounts_snapshot_update', 'cascade', true)
      );
    END LOOP;
    
    -- Regress filing status
    PERFORM public.regress_filing_status(v_filing.id, 'UNDERLYING_ACCOUNTS_CHANGED');
  END LOOP;
  
  RETURN NEW;
END;
$function$;

-- public.handle_filing_snapshot_change() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=5ddc35f768d31596480b57a930b584a6 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.handle_filing_snapshot_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_approval RECORD;
  v_old_accounts_hash TEXT;
  v_new_accounts_hash TEXT;
  v_old_ct_hash TEXT;
  v_new_ct_hash TEXT;
BEGIN
  -- Get snapshot hashes for audit
  IF OLD.accounts_snapshot_id IS NOT NULL THEN
    SELECT snapshot_hash INTO v_old_accounts_hash 
    FROM public.accounts_model_snapshots WHERE id = OLD.accounts_snapshot_id;
  END IF;
  
  IF NEW.accounts_snapshot_id IS NOT NULL THEN
    SELECT snapshot_hash INTO v_new_accounts_hash 
    FROM public.accounts_model_snapshots WHERE id = NEW.accounts_snapshot_id;
  END IF;
  
  IF OLD.ct_snapshot_id IS NOT NULL THEN
    SELECT snapshot_hash INTO v_old_ct_hash 
    FROM public.ct_computation_snapshots WHERE id = OLD.ct_snapshot_id;
  END IF;
  
  IF NEW.ct_snapshot_id IS NOT NULL THEN
    SELECT snapshot_hash INTO v_new_ct_hash 
    FROM public.ct_computation_snapshots WHERE id = NEW.ct_snapshot_id;
  END IF;

  -- Case A: Accounts snapshot changed - revoke BOTH approvals
  IF OLD.accounts_snapshot_id IS DISTINCT FROM NEW.accounts_snapshot_id THEN
    -- Revoke ACCOUNTS approval
    FOR v_approval IN 
      SELECT * FROM public.filing_approvals 
      WHERE filing_id = NEW.id 
      AND approval_scope = 'ACCOUNTS' 
      AND revoked_at IS NULL
    LOOP
      PERFORM public.revoke_approval_with_audit(
        v_approval.id,
        OLD.accounts_snapshot_id,
        v_old_accounts_hash,
        NEW.accounts_snapshot_id,
        v_new_accounts_hash,
        'UNDERLYING_ACCOUNTS_CHANGED',
        jsonb_build_object('trigger', 'filing_snapshot_change')
      );
    END LOOP;
    
    -- Revoke CT600 approval (cascade)
    FOR v_approval IN 
      SELECT * FROM public.filing_approvals 
      WHERE filing_id = NEW.id 
      AND approval_scope = 'CT600' 
      AND revoked_at IS NULL
    LOOP
      PERFORM public.revoke_approval_with_audit(
        v_approval.id,
        OLD.ct_snapshot_id,
        v_old_ct_hash,
        NEW.ct_snapshot_id,
        v_new_ct_hash,
        'UNDERLYING_ACCOUNTS_CHANGED',
        jsonb_build_object('trigger', 'filing_snapshot_change', 'cascade', true)
      );
    END LOOP;
    
    -- Regress status
    PERFORM public.regress_filing_status(NEW.id, 'UNDERLYING_ACCOUNTS_CHANGED');
    
  -- Case B: Only CT snapshot changed - revoke CT approval only
  ELSIF OLD.ct_snapshot_id IS DISTINCT FROM NEW.ct_snapshot_id THEN
    FOR v_approval IN 
      SELECT * FROM public.filing_approvals 
      WHERE filing_id = NEW.id 
      AND approval_scope = 'CT600' 
      AND revoked_at IS NULL
    LOOP
      PERFORM public.revoke_approval_with_audit(
        v_approval.id,
        OLD.ct_snapshot_id,
        v_old_ct_hash,
        NEW.ct_snapshot_id,
        v_new_ct_hash,
        'CT_COMPUTATION_CHANGED',
        jsonb_build_object('trigger', 'filing_snapshot_change')
      );
    END LOOP;
    
    -- Regress status only if not already filed
    IF NEW.status NOT IN ('filed', 'accepted', 'submitted') THEN
      PERFORM public.regress_filing_status(NEW.id, 'CT_COMPUTATION_CHANGED');
    END IF;
  END IF;
  
  RETURN NEW;
END;
$function$;

-- public.handle_new_user_profile() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=8cff48bbcfd82709cf57fdbead507a3d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.handle_new_user_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.profiles (id, email, first_name, last_name)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'first_name', NEW.raw_user_meta_data->>'given_name'),
    COALESCE(NEW.raw_user_meta_data->>'last_name', NEW.raw_user_meta_data->>'family_name')
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$function$;

-- public.handle_updated_at() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=9550931156286d9e37542104616996c5 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$;

-- public.has_any_role(_user_id uuid, _org_id uuid, _roles text[]) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=e5bf15956a622d575303023c4adc207d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.has_any_role(_user_id uuid, _org_id uuid, _roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.organization_users
    WHERE user_id = _user_id
      AND organization_id = _org_id
      AND role::text = ANY(_roles)
  )
$function$;

-- public.has_organization_role(_org_id uuid, _role text) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=2103d5793beddea5e58b999ba294f725 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.has_organization_role(_org_id uuid, _role text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 
    FROM public.organization_users 
    WHERE user_id = auth.uid() 
      AND organization_id = _org_id
      AND role = _role
  );
$function$;

-- public.has_portal_role(_user_id uuid, _role portal_role, _org_id uuid) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=7bb3b1dedff4bfc98fb40c855ffd54aa (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.has_portal_role(_user_id uuid, _role portal_role, _org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles
    WHERE user_id = _user_id
      AND role = _role
      AND organization_id = _org_id
  )
$function$;

-- public.has_role(_user_id uuid, _org_id uuid, _role app_role) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=226acc4b6becc0f50487e47fe04221cf (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _org_id uuid, _role app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.organization_users
    WHERE user_id = _user_id
      AND organization_id = _org_id
      AND role::text = _role::text
  )
$function$;

-- public.increment_automation_rate_limit(p_organization_id uuid, p_rule_id uuid, p_increment integer) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=a591d094b36ac47f2dd81ed3c4db4348 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.increment_automation_rate_limit(p_organization_id uuid, p_rule_id uuid, p_increment integer DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hour_start TIMESTAMPTZ;
  v_day_start TIMESTAMPTZ;
BEGIN
  v_hour_start := date_trunc('hour', now());
  v_day_start := date_trunc('day', now());
  
  -- Upsert hourly count
  INSERT INTO automation_rate_limits (organization_id, automation_rule_id, window_start, window_type, action_count)
  VALUES (p_organization_id, p_rule_id, v_hour_start, 'hour', p_increment)
  ON CONFLICT (organization_id, automation_rule_id, window_start, window_type)
  DO UPDATE SET action_count = automation_rate_limits.action_count + p_increment;
  
  -- Upsert daily count
  INSERT INTO automation_rate_limits (organization_id, automation_rule_id, window_start, window_type, action_count)
  VALUES (p_organization_id, p_rule_id, v_day_start, 'day', p_increment)
  ON CONFLICT (organization_id, automation_rule_id, window_start, window_type)
  DO UPDATE SET action_count = automation_rate_limits.action_count + p_increment;
END;
$function$;

-- public.is_active_onboarding_path(p_name text) -> boolean
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=b5c47a0b5b0cec16b483cc0070d4e3eb (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.is_active_onboarding_path(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_parts text[];
  v_org uuid;
  v_app uuid;
  v_status text;
BEGIN
  v_parts := string_to_array(p_name, '/');
  IF array_length(v_parts,1) < 4 THEN RETURN false; END IF;
  IF v_parts[2] <> 'onboarding' THEN RETURN false; END IF;
  BEGIN
    v_org := v_parts[1]::uuid;
    v_app := v_parts[3]::uuid;
  EXCEPTION WHEN others THEN RETURN false; END;
  SELECT status INTO v_status
    FROM public.onboarding_applications
   WHERE id = v_app AND organization_id = v_org;
  IF v_status IS NULL THEN RETURN false; END IF;
  RETURN v_status NOT IN ('approved','rejected','cancelled');
END;
$function$;

-- public.is_active_onboarding_upload_path(p_name text) -> boolean
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=34df545490c104abfe4a5ceec892cad4 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.is_active_onboarding_upload_path(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_parts text[];
  v_org uuid;
  v_app uuid;
  v_token text;
  v_row record;
BEGIN
  v_parts := string_to_array(p_name, '/');
  -- Expected path: orgId/onboarding/appId/<token>/<filename> (>=5 parts)
  IF array_length(v_parts, 1) < 5 THEN RETURN false; END IF;
  IF v_parts[2] <> 'onboarding' THEN RETURN false; END IF;
  BEGIN
    v_org := v_parts[1]::uuid;
    v_app := v_parts[3]::uuid;
  EXCEPTION WHEN others THEN RETURN false; END;
  v_token := v_parts[4];
  IF v_token IS NULL OR length(v_token) = 0 THEN RETURN false; END IF;

  SELECT status, access_token, access_token_expires_at
    INTO v_row
    FROM public.onboarding_applications
   WHERE id = v_app AND organization_id = v_org;

  IF NOT FOUND THEN RETURN false; END IF;
  IF v_row.status IN ('approved','rejected','cancelled') THEN RETURN false; END IF;
  IF v_row.access_token IS NULL OR v_row.access_token <> v_token THEN RETURN false; END IF;
  IF v_row.access_token_expires_at IS NOT NULL AND v_row.access_token_expires_at <= now() THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$function$;

-- public.is_canonical_lifecycle_enabled(p_org_id uuid) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=7ab2be413939c102bda2f47b4b11d386 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.is_canonical_lifecycle_enabled(p_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT canonical_lifecycle_enabled FROM public.organizations WHERE id = p_org_id),
    false
  );
$function$;

-- public.is_period_locked(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_target_date date) -> boolean
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=5a4beeeb69ee436a2dd29f80f67452f5 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.is_period_locked(p_organization_id uuid, p_client_id uuid, p_company_id uuid, p_target_date date)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lock_date DATE;
BEGIN
  -- Find the most restrictive lock date for this entity
  SELECT lock_date INTO v_lock_date
  FROM public.period_locks
  WHERE organization_id = p_organization_id
    AND (
      (p_client_id IS NOT NULL AND client_id = p_client_id)
      OR (p_company_id IS NOT NULL AND company_id = p_company_id)
    )
  ORDER BY lock_date DESC
  LIMIT 1;
  
  -- If no lock exists, period is not locked
  IF v_lock_date IS NULL THEN
    RETURN FALSE;
  END IF;
  
  -- Period is locked if target date is before or on lock date
  RETURN p_target_date <= v_lock_date;
END;
$function$;

-- public.is_portal_user() -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=a9b07b171e5b9d8007eb4572d96526b9 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.is_portal_user()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.portal_access WHERE user_id = auth.uid() AND is_active = true);
$function$;

-- public.issue_invoice_safe(p_invoice_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=a4a7d816cdc64323d1f439a14b27a7cd (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.issue_invoice_safe(p_invoice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_invoice record;
  v_org_settings record;
  v_invoice_number text;
  v_post jsonb;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;
  IF NOT (
    (public.user_in_organization(v_user_id, v_invoice.organization_id)
      AND public.can_issue_invoices(v_user_id, v_invoice.organization_id))
    OR (
      public.portal_has_perm(v_invoice.client_id, v_invoice.company_id, 'allow_invoice_send')
      AND NOT COALESCE((
        SELECT require_review_for_invoice_sending FROM public.portal_visibility_settings
        WHERE (v_invoice.client_id IS NOT NULL AND client_id = v_invoice.client_id)
           OR (v_invoice.company_id IS NOT NULL AND company_id = v_invoice.company_id)
        LIMIT 1), false)
    )
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: cannot issue invoices');
  END IF;
  IF v_invoice.status != 'DRAFT' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only DRAFT invoices can be issued');
  END IF;
  IF v_invoice.invoice_number IS NULL OR v_invoice.invoice_number = '' THEN
    SELECT * INTO v_org_settings FROM org_settings WHERE organization_id = v_invoice.organization_id FOR UPDATE;
    IF v_org_settings IS NULL THEN
      INSERT INTO org_settings (organization_id) VALUES (v_invoice.organization_id)
      RETURNING * INTO v_org_settings;
    END IF;
    v_invoice_number := COALESCE(v_org_settings.invoice_number_prefix, 'INV-') ||
      LPAD(COALESCE(v_org_settings.invoice_number_next, 1)::text, COALESCE(v_org_settings.invoice_number_padding, 6), '0');
    UPDATE org_settings SET invoice_number_next = COALESCE(invoice_number_next, 1) + 1
    WHERE organization_id = v_invoice.organization_id;
  ELSE
    v_invoice_number := v_invoice.invoice_number;
  END IF;
  UPDATE invoices SET
    invoice_number = v_invoice_number,
    issued_at = now(),
    issued_by = v_user_id,
    locked_fields = '["total_net","total_vat","total_gross","lines"]'::jsonb,
    updated_at = now()
  WHERE id = p_invoice_id;
  v_post := public.approve_invoice(p_invoice_id, v_user_id);
  IF NOT COALESCE((v_post->>'success')::boolean, false) THEN
    RAISE EXCEPTION 'Could not post invoice to the ledger: %',
      COALESCE(v_post->>'error_message', 'posting error')
      USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO audit_log (organization_id, user_id, entity_type, entity_id, action, before_state, after_state)
  VALUES (v_invoice.organization_id, v_user_id, 'invoice', p_invoice_id, 'issued',
    jsonb_build_object('status', 'DRAFT'),
    jsonb_build_object('status', 'AWAITING_PAYMENT', 'invoice_number', v_invoice_number));
  RETURN jsonb_build_object('success', true, 'invoice_id', p_invoice_id,
                            'invoice_number', v_invoice_number,
                            'journal_id', v_post->>'journal_id');
END;
$function$;

-- public.lifecycle_accept_portal_invitation(p_token text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=b770de4a5d19c76bf0df6d3a237dc926 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_accept_portal_invitation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current_user_id uuid;
  v_portal_access record;
  v_entity_type text;
  v_entity_id uuid;
BEGIN
  -- Validate authentication
  v_current_user_id := auth.uid();
  
  IF v_current_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'unauthenticated');
  END IF;

  -- Look up portal_access by token
  SELECT * INTO v_portal_access
  FROM portal_access
  WHERE invite_token = p_token
    AND status = 'invited'
    AND (invite_expires_at IS NULL OR invite_expires_at > now());

  -- If not found or expired
  IF v_portal_access.id IS NULL THEN
    -- Check if expired
    IF EXISTS (
      SELECT 1 FROM portal_access
      WHERE invite_token = p_token
        AND status = 'invited'
        AND invite_expires_at IS NOT NULL
        AND invite_expires_at <= now()
    ) THEN
      RETURN jsonb_build_object('success', false, 'reason', 'expired');
    ELSE
      RETURN jsonb_build_object('success', false, 'reason', 'not_found');
    END IF;
  END IF;

  -- Validate no user_id conflict (prevent invite hijacking)
  IF v_portal_access.user_id IS NOT NULL AND v_portal_access.user_id != v_current_user_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'user_mismatch');
  END IF;

  -- Determine entity type and ID
  IF v_portal_access.client_id IS NOT NULL THEN
    v_entity_type := 'client';
    v_entity_id := v_portal_access.client_id;
  ELSIF v_portal_access.company_id IS NOT NULL THEN
    v_entity_type := 'company';
    v_entity_id := v_portal_access.company_id;
  END IF;

  -- Deactivate any duplicate active invites for this user + entity
  UPDATE portal_access
  SET 
    status = 'revoked_by_system',
    is_active = false,
    updated_at = now()
  WHERE user_id = v_current_user_id
    AND (
      (client_id = v_portal_access.client_id AND client_id IS NOT NULL) OR
      (company_id = v_portal_access.company_id AND company_id IS NOT NULL)
    )
    AND id != v_portal_access.id
    AND is_active = true;

  -- Update portal_access to active
  UPDATE portal_access
  SET
    user_id = v_current_user_id,
    status = 'active',
    is_active = true,
    accepted_at = now(),
    invite_token = NULL,
    invite_expires_at = NULL,
    updated_at = now()
  WHERE id = v_portal_access.id;

  -- Write to audit_log
  INSERT INTO audit_log (
    organization_id,
    entity_type,
    entity_id,
    action,
    user_id,
    metadata
  ) VALUES (
    v_portal_access.organization_id,
    'portal_access',
    v_portal_access.id,
    'accepted',
    v_current_user_id,
    jsonb_build_object(
      'entity_type', v_entity_type,
      'entity_id', v_entity_id,
      'role', v_portal_access.role
    )
  );

  -- Return success
  RETURN jsonb_build_object(
    'success', true,
    'portal_access_id', v_portal_access.id,
    'entity_type', v_entity_type,
    'entity_id', v_entity_id,
    'organization_id', v_portal_access.organization_id,
    'status', 'active'
  );
END;
$function$;

-- public.lifecycle_accept_quote(p_quote_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=fd977487d4f14160aa0823f66a6ef5af (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_accept_quote(p_quote_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_quote record;
  v_lead record;
  v_onboarding_id uuid;
  v_onboarding_status text;
  v_created_new_onboarding boolean := false;
  v_old_quote_status text;
BEGIN
  -- Fetch quote
  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id;
  
  IF v_quote.id IS NULL THEN
    RAISE EXCEPTION 'Quote not found: %', p_quote_id;
  END IF;

  -- Verify caller has access to organization
  IF NOT user_has_organization_access(v_quote.organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  -- Validate quote status (accept from draft or sent)
  IF v_quote.status NOT IN ('draft', 'sent') THEN
    RAISE EXCEPTION 'Quote cannot be accepted. Current status: %', v_quote.status;
  END IF;

  v_old_quote_status := v_quote.status;

  -- Update quote
  UPDATE quotes 
  SET 
    status = 'accepted',
    accepted_at = now(),
    sent_at = COALESCE(sent_at, now())
  WHERE id = p_quote_id;

  -- Write audit log for quote
  INSERT INTO audit_log (
    organization_id,
    entity_type,
    entity_id,
    action,
    old_value,
    new_value,
    user_id
  )
  VALUES (
    v_quote.organization_id,
    'quote',
    p_quote_id,
    'status_change',
    v_old_quote_status,
    'accepted',
    auth.uid()
  );

  -- Update linked lead if present
  IF v_quote.lead_id IS NOT NULL THEN
    SELECT * INTO v_lead FROM leads WHERE id = v_quote.lead_id;
    
    UPDATE leads 
    SET 
      pipeline_stage = 'won',
      converted_at = now()
    WHERE id = v_quote.lead_id;

    -- Write audit log for lead
    INSERT INTO audit_log (
      organization_id,
      entity_type,
      entity_id,
      action,
      old_value,
      new_value,
      user_id
    )
    VALUES (
      v_quote.organization_id,
      'lead',
      v_quote.lead_id,
      'status_change',
      v_lead.pipeline_stage,
      'won',
      auth.uid()
    );
  END IF;

  -- Check for existing onboarding application
  SELECT id, status INTO v_onboarding_id, v_onboarding_status
  FROM onboarding_applications 
  WHERE quote_id = p_quote_id
  LIMIT 1;

  -- Create onboarding application if none exists
  IF v_onboarding_id IS NULL THEN
    INSERT INTO onboarding_applications (
      organization_id,
      lead_id,
      quote_id,
      application_type,
      status,
      aml_status,
      first_name,
      last_name,
      email,
      phone
    )
    SELECT
      v_quote.organization_id,
      v_quote.lead_id,
      p_quote_id,
      CASE 
        WHEN v_lead.company_name IS NOT NULL THEN 'company'
        ELSE 'individual'
      END,
      'pending',
      'pending',
      COALESCE(v_lead.first_name, ''),
      COALESCE(v_lead.last_name, ''),
      COALESCE(v_lead.email, v_quote.client_email),
      v_lead.phone
    FROM (SELECT v_lead.*) AS lead_data
    RETURNING id, status INTO v_onboarding_id, v_onboarding_status;

    v_created_new_onboarding := true;

    -- Write audit log for onboarding creation
    INSERT INTO audit_log (
      organization_id,
      entity_type,
      entity_id,
      action,
      user_id,
      metadata
    )
    VALUES (
      v_quote.organization_id,
      'onboarding',
      v_onboarding_id,
      'created',
      auth.uid(),
      jsonb_build_object('quote_id', p_quote_id, 'lead_id', v_quote.lead_id)
    );
  END IF;

  -- Return result
  RETURN jsonb_build_object(
    'quote_id', p_quote_id,
    'quote_status', 'accepted',
    'lead_id', v_quote.lead_id,
    'lead_stage', CASE WHEN v_quote.lead_id IS NOT NULL THEN 'won' ELSE NULL END,
    'onboarding_application_id', v_onboarding_id,
    'onboarding_status', v_onboarding_status,
    'created_new_onboarding', v_created_new_onboarding
  );
END;
$function$;

-- public.lifecycle_activate_client_services(p_quote_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=23b3d925a7658a8863815af05878bf5f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_activate_client_services(p_quote_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_quote        RECORD;
  v_client_id    uuid;
  v_company_id   uuid;
  v_lead         RECORD;
  v_line         RECORD;
  v_eng_id       uuid;
  v_created      int := 0;
  v_skipped      int := 0;
  v_results      jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_quote FROM public.quotes WHERE id = p_quote_id;
  IF v_quote IS NULL THEN
    RAISE EXCEPTION 'Quote % not found', p_quote_id;
  END IF;

  IF NOT public._canonical_caller_in_org(v_quote.organization_id) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF NOT public._canonical_spine_enabled(v_quote.organization_id) THEN
    RETURN jsonb_build_object(
      'status', 'skipped',
      'reason', 'canonical_spine_v1 flag disabled',
      'quote_id', p_quote_id
    );
  END IF;

  IF v_quote.status <> 'accepted' THEN
    RAISE EXCEPTION 'Quote % not accepted (status=%)', p_quote_id, v_quote.status;
  END IF;

  -- Resolve target client/company via lead -> conversion
  SELECT * INTO v_lead FROM public.leads WHERE id = v_quote.lead_id;
  IF v_lead IS NULL THEN
    RAISE EXCEPTION 'Quote % has no lead', p_quote_id;
  END IF;

  v_client_id  := v_lead.converted_client_id;
  v_company_id := v_lead.converted_company_id;

  IF v_client_id IS NULL AND v_company_id IS NULL THEN
    RAISE EXCEPTION 'Lead % has not been converted to a client/company yet', v_lead.id;
  END IF;

  FOR v_line IN
    SELECT ql.*, sc.id AS svc_id
      FROM public.quote_lines ql
      JOIN public.services_catalog sc ON sc.id = ql.service_id
     WHERE ql.quote_id = p_quote_id
       AND ql.canonical_service_code IS NOT NULL
  LOOP
    -- Idempotent: find existing engagement keyed on (org, client/company, canonical_service_code)
    SELECT id INTO v_eng_id
      FROM public.engagements
     WHERE organization_id = v_quote.organization_id
       AND canonical_service_code = v_line.canonical_service_code
       AND COALESCE(client_id::text, '') = COALESCE(v_client_id::text, '')
       AND COALESCE(company_id::text, '') = COALESCE(v_company_id::text, '')
     LIMIT 1;

    IF v_eng_id IS NULL THEN
      INSERT INTO public.engagements (
        organization_id, client_id, company_id, service_id, quote_id,
        canonical_service_code, frequency, start_date, status, active, activated_at
      ) VALUES (
        v_quote.organization_id, v_client_id, v_company_id, v_line.service_id, p_quote_id,
        v_line.canonical_service_code,
        COALESCE(v_line.billing_frequency, 'one_off'),
        CURRENT_DATE, 'active', true, now()
      )
      RETURNING id INTO v_eng_id;
      v_created := v_created + 1;
      v_results := v_results || jsonb_build_object(
        'canonical_service_code', v_line.canonical_service_code,
        'engagement_id', v_eng_id,
        'action', 'created'
      );
    ELSE
      -- Re-activate if previously suspended/terminated
      UPDATE public.engagements
         SET status = 'active', active = true, activated_at = COALESCE(activated_at, now())
       WHERE id = v_eng_id AND status <> 'active';
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_object(
        'canonical_service_code', v_line.canonical_service_code,
        'engagement_id', v_eng_id,
        'action', 'reused'
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status', 'ok',
    'quote_id', p_quote_id,
    'engagements_created', v_created,
    'engagements_reused', v_skipped,
    'results', v_results
  );
END;
$function$;

-- public.lifecycle_approve_onboarding(p_onboarding_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public, extensions
--   definition_hash=1a12e3d38fe5e4f6e7bb5f208a799f4d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_approve_onboarding(p_onboarding_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_onboarding record;
  v_questionnaire_instance record;
  v_questionnaire_responses jsonb;
  v_client_id uuid;
  v_company_id uuid;
  v_engagement_ids uuid[] := ARRAY[]::uuid[];
  v_job_ids uuid[] := ARRAY[]::uuid[];
  v_engagement_id uuid;
  v_job_id uuid;
  v_portal_access_result jsonb;
  v_entity_type text;
  v_entity_id uuid;
  v_primary_email text;
  v_quote_line record;
  v_trigger_date date;
  v_aml_expiry_date date;
  v_period_label text;
BEGIN
  SELECT * INTO v_onboarding FROM onboarding_applications WHERE id = p_onboarding_id;

  IF v_onboarding.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found: %', p_onboarding_id;
  END IF;

  IF NOT user_has_organization_access(v_onboarding.organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  IF v_onboarding.status = 'approved' THEN
    RAISE EXCEPTION 'Onboarding application already approved';
  END IF;

  IF v_onboarding.status = 'rejected' THEN
    RAISE EXCEPTION 'Cannot approve rejected application';
  END IF;

  IF public.is_canonical_lifecycle_enabled(v_onboarding.organization_id) THEN
    DECLARE
      v_gates jsonb := public.lifecycle_onboarding_gates(p_onboarding_id);
    BEGIN
      -- T2b: gate on activation_ready (signatures/AML/submission) — billing no longer blocks.
      IF NOT COALESCE((v_gates->>'activation_ready')::boolean, false) THEN
        RAISE EXCEPTION 'Cannot approve onboarding %: outstanding activation gates %',
          p_onboarding_id, (v_gates->>'outstanding');
      END IF;
    END;
  END IF;

  v_aml_expiry_date := CURRENT_DATE + INTERVAL '5 years';

  IF v_onboarding.onboarding_questionnaire_instance_id IS NOT NULL THEN
    SELECT * INTO v_questionnaire_instance
    FROM questionnaire_instances
    WHERE id = v_onboarding.onboarding_questionnaire_instance_id;

    SELECT jsonb_object_agg(qr.question_id, qr.response_value)
    INTO v_questionnaire_responses
    FROM questionnaire_responses qr
    WHERE qr.questionnaire_instance_id = v_onboarding.onboarding_questionnaire_instance_id;
  END IF;

  IF v_onboarding.application_type = 'individual' THEN
    IF v_onboarding.client_id IS NOT NULL THEN
      v_client_id := v_onboarding.client_id;
      UPDATE clients
      SET
        status = 'active',
        activated_at = now(),
        aml_verified_at = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        aml_expiry_date = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        aml_verified_by = CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END,
        first_name = COALESCE(v_questionnaire_responses->>'first_name', first_name),
        last_name = COALESCE(v_questionnaire_responses->>'last_name', last_name),
        date_of_birth = COALESCE((v_questionnaire_responses->>'date_of_birth')::date, date_of_birth),
        address_line_1 = COALESCE(v_questionnaire_responses->>'address_line_1', address_line_1),
        address_line_2 = COALESCE(v_questionnaire_responses->>'address_line_2', address_line_2),
        city = COALESCE(v_questionnaire_responses->>'city', city),
        postcode = COALESCE(v_questionnaire_responses->>'postcode', postcode),
        country = COALESCE(v_questionnaire_responses->>'country', country),
        phone = COALESCE(v_questionnaire_responses->>'phone', phone),
        national_insurance_number = COALESCE(v_questionnaire_responses->>'national_insurance_number', national_insurance_number),
        utr = COALESCE(v_questionnaire_responses->>'utr', utr)
      WHERE id = v_client_id;
    ELSE
      INSERT INTO clients (
        organization_id, first_name, last_name, email, phone, date_of_birth,
        address_line_1, address_line_2, city, postcode, country,
        national_insurance_number, utr, status, activated_at,
        aml_verified_at, aml_expiry_date, aml_verified_by
      )
      VALUES (
        v_onboarding.organization_id,
        COALESCE(v_questionnaire_responses->>'first_name', v_onboarding.first_name),
        COALESCE(v_questionnaire_responses->>'last_name', v_onboarding.last_name),
        v_onboarding.email,
        COALESCE(v_questionnaire_responses->>'phone', v_onboarding.phone),
        COALESCE((v_questionnaire_responses->>'date_of_birth')::date, v_onboarding.date_of_birth),
        COALESCE(v_questionnaire_responses->>'address_line_1', v_onboarding.address_line_1),
        COALESCE(v_questionnaire_responses->>'address_line_2', v_onboarding.address_line_2),
        COALESCE(v_questionnaire_responses->>'city', v_onboarding.city),
        COALESCE(v_questionnaire_responses->>'postcode', v_onboarding.postcode),
        COALESCE(v_questionnaire_responses->>'country', v_onboarding.country),
        COALESCE(v_questionnaire_responses->>'national_insurance_number', v_onboarding.national_insurance_number),
        COALESCE(v_questionnaire_responses->>'utr', v_onboarding.utr),
        'active', now(),
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END
      )
      RETURNING id INTO v_client_id;

      UPDATE onboarding_applications SET client_id = v_client_id WHERE id = p_onboarding_id;

      INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
      VALUES (v_onboarding.organization_id, 'client', v_client_id, 'created', auth.uid(),
        jsonb_build_object('onboarding_id', p_onboarding_id, 'status', 'active', 'source', 'onboarding_approval'));
    END IF;

    v_entity_type := 'client';
    v_entity_id := v_client_id;

  ELSIF v_onboarding.application_type = 'company' THEN
    IF v_onboarding.company_id IS NOT NULL THEN
      v_company_id := v_onboarding.company_id;
      UPDATE companies
      SET
        status = 'active',
        activated_at = now(),
        aml_verified_at = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        aml_expiry_date = CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        aml_verified_by = CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END,
        company_name = COALESCE(v_questionnaire_responses->>'company_name', company_name),
        company_number = COALESCE(v_questionnaire_responses->>'company_number', company_number),
        address_line_1 = COALESCE(v_questionnaire_responses->>'address_line_1', address_line_1),
        address_line_2 = COALESCE(v_questionnaire_responses->>'address_line_2', address_line_2),
        city = COALESCE(v_questionnaire_responses->>'city', city),
        postcode = COALESCE(v_questionnaire_responses->>'postcode', postcode),
        country = COALESCE(v_questionnaire_responses->>'country', country),
        phone = COALESCE(v_questionnaire_responses->>'phone', phone),
        vat_number = COALESCE(v_questionnaire_responses->>'vat_number', vat_number),
        incorporation_date = COALESCE((v_questionnaire_responses->>'incorporation_date')::date, incorporation_date),
        year_end_month = COALESCE((v_questionnaire_responses->>'year_end_month')::integer, year_end_month),
        year_end_day = COALESCE((v_questionnaire_responses->>'year_end_day')::integer, year_end_day)
      WHERE id = v_company_id;
    ELSE
      INSERT INTO companies (
        organization_id, company_name, company_number, email, phone,
        address_line_1, address_line_2, city, postcode, country,
        vat_number, incorporation_date, year_end_month, year_end_day,
        status, activated_at, aml_verified_at, aml_expiry_date, aml_verified_by
      )
      VALUES (
        v_onboarding.organization_id,
        COALESCE(v_questionnaire_responses->>'company_name', v_onboarding.company_name),
        COALESCE(v_questionnaire_responses->>'company_number', v_onboarding.company_number),
        v_onboarding.email,
        COALESCE(v_questionnaire_responses->>'phone', v_onboarding.phone),
        COALESCE(v_questionnaire_responses->>'address_line_1', v_onboarding.address_line_1),
        COALESCE(v_questionnaire_responses->>'address_line_2', v_onboarding.address_line_2),
        COALESCE(v_questionnaire_responses->>'city', v_onboarding.city),
        COALESCE(v_questionnaire_responses->>'postcode', v_onboarding.postcode),
        COALESCE(v_questionnaire_responses->>'country', v_onboarding.country),
        COALESCE(v_questionnaire_responses->>'vat_number', v_onboarding.vat_number),
        COALESCE((v_questionnaire_responses->>'incorporation_date')::date, v_onboarding.incorporation_date),
        COALESCE((v_questionnaire_responses->>'year_end_month')::integer, v_onboarding.year_end_month),
        COALESCE((v_questionnaire_responses->>'year_end_day')::integer, v_onboarding.year_end_day),
        'active', now(),
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_onboarding.aml_verified_at ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN v_aml_expiry_date ELSE NULL END,
        CASE WHEN v_onboarding.aml_status = 'verified' THEN auth.uid() ELSE NULL END
      )
      RETURNING id INTO v_company_id;

      UPDATE onboarding_applications SET company_id = v_company_id WHERE id = p_onboarding_id;

      INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
      VALUES (v_onboarding.organization_id, 'company', v_company_id, 'created', auth.uid(),
        jsonb_build_object('onboarding_id', p_onboarding_id, 'status', 'active', 'source', 'onboarding_approval'));
    END IF;

    v_entity_type := 'company';
    v_entity_id := v_company_id;
  END IF;

  IF v_onboarding.quote_id IS NOT NULL THEN
    -- Canonical engine: the SINGLE idempotent source for engagements + jobs + deadlines.
    PERFORM public.lifecycle_materialize_jobs(
      v_onboarding.organization_id, v_client_id, v_company_id, NULL,
      v_onboarding.quote_id, 'onboarding_approval:' || p_onboarding_id::text);

    FOR v_quote_line IN
      SELECT ql.*, sc.code AS service_code, sc.name AS service_name,
             sc.trigger_date_type, sc.trigger_date_offset_days, sc.information_request_template_id
      FROM quote_lines ql
      LEFT JOIN services_catalog sc ON sc.id = ql.service_id
      WHERE ql.quote_id = v_onboarding.quote_id
    LOOP
      SELECT id INTO v_engagement_id
      FROM engagements
      WHERE quote_id = v_onboarding.quote_id AND service_id = v_quote_line.service_id
      LIMIT 1;
      IF v_engagement_id IS NOT NULL THEN
        v_engagement_ids := array_append(v_engagement_ids, v_engagement_id);
      END IF;

      SELECT id INTO v_job_id
      FROM jobs
      WHERE organization_id = v_onboarding.organization_id
        AND service_type = COALESCE(v_quote_line.service_code, v_quote_line.service_id::text)
        AND COALESCE(client_id::text, '') = COALESCE(v_client_id::text, '')
        AND COALESCE(company_id::text, '') = COALESCE(v_company_id::text, '')
      ORDER BY created_at DESC
      LIMIT 1;
      IF v_job_id IS NOT NULL THEN
        v_job_ids := array_append(v_job_ids, v_job_id);
      END IF;

      IF v_quote_line.trigger_date_type IS NOT NULL AND v_quote_line.information_request_template_id IS NOT NULL THEN
        v_trigger_date := CASE v_quote_line.trigger_date_type
          WHEN 'tax_year_end' THEN
            CASE WHEN CURRENT_DATE > make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, 4, 5)
              THEN make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, 4, 5)
              ELSE make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int - 1, 4, 5)
            END
          WHEN 'financial_year_end' THEN
            CASE WHEN v_company_id IS NOT NULL THEN
              (SELECT make_date(
                CASE WHEN CURRENT_DATE > make_date(EXTRACT(YEAR FROM CURRENT_DATE)::int, COALESCE(c.year_end_month, 3), COALESCE(c.year_end_day, 31))
                  THEN EXTRACT(YEAR FROM CURRENT_DATE)::int
                  ELSE EXTRACT(YEAR FROM CURRENT_DATE)::int - 1
                END,
                COALESCE(c.year_end_month, 3),
                COALESCE(c.year_end_day, 31)
              ) FROM companies c WHERE c.id = v_company_id)
            ELSE CURRENT_DATE - INTERVAL '1 day'
            END
          ELSE CURRENT_DATE - INTERVAL '1 day'
        END;

        IF CURRENT_DATE > v_trigger_date + (COALESCE(v_quote_line.trigger_date_offset_days,0) || ' days')::interval THEN
          INSERT INTO email_queue (
            organization_id, to_email, to_name, subject, body_html,
            template_id, client_id, company_id, job_id, entity_type, entity_id,
            merge_data, status
          )
          SELECT
            v_onboarding.organization_id,
            v_onboarding.email,
            COALESCE(v_onboarding.first_name || ' ' || v_onboarding.last_name, v_onboarding.company_name),
            COALESCE(t.name, 'Information Request') || ' - ' || COALESCE(v_quote_line.service_name,'Service'),
            COALESCE(t.content->>'body_html', '<p>We need some information to complete your ' || COALESCE(v_quote_line.service_name,'service') || '.</p>'),
            v_quote_line.information_request_template_id,
            v_client_id,
            v_company_id,
            v_job_id,
            'job',
            v_job_id,
            jsonb_build_object(
              'client_name', COALESCE(v_onboarding.first_name || ' ' || v_onboarding.last_name, v_onboarding.company_name),
              'service_name', v_quote_line.service_name,
              'trigger_date', v_trigger_date::text
            ),
            'pending'
          FROM templates t WHERE t.id = v_quote_line.information_request_template_id;

          INSERT INTO client_tasks (
            organization_id, client_id, company_id, title, description,
            status, visibility, due_date
          )
          VALUES (
            v_onboarding.organization_id, v_client_id, v_company_id,
            'Provide information for ' || COALESCE(v_quote_line.service_name,'service'),
            'Please provide the required information to complete your ' || COALESCE(v_quote_line.service_name,'service'),
            'not_started', 'client_visible',
            CURRENT_DATE + INTERVAL '14 days'
          );
        END IF;
      END IF;

      IF v_engagement_id IS NOT NULL THEN
        INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
        VALUES (v_onboarding.organization_id, 'engagement', v_engagement_id, 'created', auth.uid(),
          jsonb_build_object('onboarding_id', p_onboarding_id, 'service_id', v_quote_line.service_id));
      END IF;
    END LOOP;
  END IF;

  IF public.is_canonical_lifecycle_enabled(v_onboarding.organization_id) THEN
    IF v_company_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public.accountant_client_links
                     WHERE practice_id = v_onboarding.organization_id
                       AND company_id = v_company_id AND status = 'active') THEN
        INSERT INTO public.accountant_client_links (practice_id, company_id, status, initiated_by, activated_at)
        VALUES (v_onboarding.organization_id, v_company_id, 'active', 'practice', now());
      END IF;
    ELSIF v_client_id IS NOT NULL THEN
      IF NOT EXISTS (SELECT 1 FROM public.accountant_client_links
                     WHERE practice_id = v_onboarding.organization_id
                       AND client_id = v_client_id AND status = 'active') THEN
        INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
        VALUES (v_onboarding.organization_id, v_client_id, 'active', 'practice', now());
      END IF;
    END IF;
  END IF;

  UPDATE onboarding_applications
  SET
    status = 'approved',
    approved_at = now(),
    approved_by = auth.uid(),
    aml_expiry_date = v_aml_expiry_date,
    aml_documents_migrated = true
  WHERE id = p_onboarding_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, old_value, new_value, user_id)
  VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'approved', v_onboarding.status, 'approved', auth.uid());

  v_primary_email := v_onboarding.email;
  IF v_primary_email IS NOT NULL AND v_primary_email != '' AND v_entity_type IS NOT NULL AND v_entity_id IS NOT NULL THEN
    BEGIN
      v_portal_access_result := lifecycle_grant_portal_access(v_entity_type, v_entity_id, v_primary_email, 'primary_contact');
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
      VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'portal_access_failed', auth.uid(),
        jsonb_build_object('error', SQLERRM, 'sqlstate', SQLSTATE, 'email', v_primary_email));
      v_portal_access_result := jsonb_build_object('ok', false, 'error', SQLERRM, 'sqlstate', SQLSTATE);
    END;
  ELSE
    v_portal_access_result := jsonb_build_object('ok', false, 'skipped', true, 'reason',
      CASE WHEN v_primary_email IS NULL OR v_primary_email = '' THEN 'no_email' ELSE 'no_entity' END);
  END IF;

  RETURN jsonb_build_object(
    'onboarding_id', p_onboarding_id,
    'status', 'approved',
    'client_id', v_client_id,
    'company_id', v_company_id,
    'engagement_ids', v_engagement_ids,
    'job_ids', v_job_ids,
    'portal_access', v_portal_access_result,
    'aml_expiry_date', v_aml_expiry_date,
    'questionnaire_data_populated', v_questionnaire_responses IS NOT NULL
  );
END;
$function$;

-- public.lifecycle_create_manual_job(p_client_id uuid, p_company_id uuid, p_service_code text, p_tax_year_start integer) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=e4b07119add92d579899f43fc5da06ff (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_create_manual_job(p_client_id uuid, p_company_id uuid, p_service_code text, p_tax_year_start integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_svc record;
  v_today date := CURRENT_DATE;
  v_company record;
  v_period_start date; v_period_end date; v_period_label text;
  v_job_id uuid;
BEGIN
  IF p_client_id IS NULL AND p_company_id IS NULL THEN
    RAISE EXCEPTION 'A client or company is required';
  END IF;

  IF p_client_id IS NOT NULL THEN
    SELECT organization_id INTO v_org FROM public.clients WHERE id = p_client_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.companies WHERE id = p_company_id;
  END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Entity not found'; END IF;
  IF NOT public.user_has_organization_access(v_org) THEN
    RAISE EXCEPTION 'Access denied to organization' USING ERRCODE='42501';
  END IF;

  SELECT code, name INTO v_svc FROM public.services_catalog WHERE code = p_service_code AND organization_id = v_org LIMIT 1;
  IF v_svc.code IS NULL THEN
    SELECT code, name INTO v_svc FROM public.services_catalog WHERE code = p_service_code LIMIT 1;
  END IF;
  IF v_svc.code IS NULL THEN RAISE EXCEPTION 'Unknown service %', p_service_code; END IF;

  IF p_service_code IN ('sa_mtd','sa_non_mtd') THEN
    IF p_tax_year_start IS NULL THEN
      IF EXTRACT(MONTH FROM v_today) > 4 OR (EXTRACT(MONTH FROM v_today) = 4 AND EXTRACT(DAY FROM v_today) >= 6) THEN
        p_tax_year_start := EXTRACT(YEAR FROM v_today)::int;
      ELSE
        p_tax_year_start := EXTRACT(YEAR FROM v_today)::int - 1;
      END IF;
    END IF;
    v_period_start := make_date(p_tax_year_start, 4, 6);
    v_period_end := make_date(p_tax_year_start + 1, 4, 5);
    v_period_label := p_tax_year_start::text || '/' || substr((p_tax_year_start + 1)::text, 3, 2);
  ELSIF p_company_id IS NOT NULL THEN
    SELECT * INTO v_company FROM public.companies WHERE id = p_company_id;
    IF v_company.year_end_month IS NOT NULL AND v_company.year_end_day IS NOT NULL THEN
      v_period_end := make_date(EXTRACT(YEAR FROM v_today)::int, v_company.year_end_month, v_company.year_end_day);
      IF v_period_end > v_today THEN v_period_end := v_period_end - INTERVAL '1 year'; END IF;
      v_period_start := v_period_end - INTERVAL '1 year' + INTERVAL '1 day';
      v_period_label := to_char(v_period_end, 'YYYY') || ' Year-End';
    ELSE
      v_period_start := v_today; v_period_end := v_today + INTERVAL '30 days'; v_period_label := 'Setup Pending';
    END IF;
  ELSE
    v_period_start := v_today; v_period_end := v_today + INTERVAL '30 days'; v_period_label := 'Setup Pending';
  END IF;

  v_job_id := public.lifecycle_upsert_job_with_deadlines(
    v_org, p_client_id, p_company_id, NULL, v_svc.code, v_svc.name,
    v_period_start, v_period_end, v_period_label, 'manual');

  RETURN jsonb_build_object('job_id', v_job_id, 'period_label', v_period_label);
END;
$function$;

-- public.lifecycle_evaluate_onboarding_activation(p_application_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public, extensions
--   definition_hash=48b36afe230d099f4be8a70887e17ae3 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_evaluate_onboarding_activation(p_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  a          public.onboarding_applications%ROWTYPE;
  v_flag     boolean;
  v_gates    jsonb;
  v_all_pass boolean;
  v_approve  jsonb;
BEGIN
  SELECT * INTO a FROM public.onboarding_applications WHERE id = p_application_id;
  IF a.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found: %', p_application_id;
  END IF;

  IF NOT public.user_has_organization_access(a.organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization' USING ERRCODE='42501';
  END IF;

  v_flag     := public.is_canonical_lifecycle_enabled(a.organization_id);
  v_gates    := public.lifecycle_onboarding_gates(p_application_id);
  -- T2b: activation is driven by signatures/AML/submission (activation_ready), NOT billing.
  v_all_pass := COALESCE((v_gates->>'activation_ready')::boolean, false);

  IF NOT v_flag THEN
    RETURN jsonb_build_object('mode', 'dry_run', 'flag', false,
                              'would_activate', v_all_pass, 'gates', v_gates);
  END IF;

  IF a.status IN ('approved','rejected','cancelled') THEN
    RETURN jsonb_build_object('mode', 'noop_closed', 'status', a.status, 'gates', v_gates);
  END IF;

  IF NOT v_all_pass THEN
    UPDATE public.onboarding_applications
       SET status = 'for_review',
           review_feedback = COALESCE(review_feedback, '') ||
             CASE WHEN COALESCE(review_feedback,'') = '' THEN '' ELSE E'\n' END ||
             'Auto-evaluation outstanding gates: ' || (v_gates->>'outstanding'),
           updated_at = now()
     WHERE id = p_application_id;
    RETURN jsonb_build_object('mode', 'routed_to_review', 'gates', v_gates);
  END IF;

  IF a.application_type = 'company' AND a.company_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.accountant_client_links
      WHERE practice_id = a.organization_id AND company_id = a.company_id AND status = 'active'
    ) THEN
      INSERT INTO public.accountant_client_links (practice_id, company_id, status, initiated_by, activated_at)
      VALUES (a.organization_id, a.company_id, 'active', 'practice', now());
    END IF;
  ELSIF a.client_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.accountant_client_links
      WHERE practice_id = a.organization_id AND client_id = a.client_id AND status = 'active'
    ) THEN
      INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
      VALUES (a.organization_id, a.client_id, 'active', 'practice', now());
    END IF;
  END IF;

  v_approve := public.lifecycle_approve_onboarding(p_application_id);

  RETURN jsonb_build_object('mode', 'activated', 'gates', v_gates, 'approve', v_approve);
END;
$function$;

-- public.lifecycle_generate_deadlines_for_job(p_job_id uuid, p_facts jsonb) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=a033147d3c367a2ba4b7745000468b2e (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_generate_deadlines_for_job(p_job_id uuid, p_facts jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job       RECORD;
  v_rule      RECORD;
  v_calc      jsonb;
  v_due       date;
  v_missing   text[];
  v_fact      text;
  v_created   int := 0;
  v_skipped   int := 0;
  v_missing_facts_logged int := 0;
  v_existing  uuid;
  v_results   jsonb := '[]'::jsonb;
  v_tax_year_end date;
  v_after_tax  boolean;
  v_fixed_txt  text;
  v_existing_dl record;
BEGIN
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF v_job IS NULL THEN
    RAISE EXCEPTION 'Job % not found', p_job_id;
  END IF;

  IF NOT public._canonical_caller_in_org(v_job.organization_id) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF NOT public._canonical_spine_enabled(v_job.organization_id) THEN
    RETURN jsonb_build_object('status','skipped','reason','canonical_spine_v1 flag disabled');
  END IF;

  IF v_job.job_template_code IS NULL OR v_job.canonical_service_code IS NULL THEN
    RAISE EXCEPTION 'Job % is not mapped to a canonical job template', p_job_id;
  END IF;

  FOR v_rule IN
    SELECT * FROM public.canonical_deadline_rules
     WHERE active = true
       AND (job_template_code = v_job.job_template_code
            OR (job_template_code IS NULL AND canonical_service_code = v_job.canonical_service_code))
  LOOP
    v_calc := v_rule.calculation_method;
    v_due := NULL;
    v_missing := ARRAY[]::text[];

    -- Check required_facts presence in p_facts JSON
    IF v_rule.required_facts IS NOT NULL THEN
      FOREACH v_fact IN ARRAY v_rule.required_facts
      LOOP
        -- skip "fact" entries that actually reference another deadline_code we may have just made
        IF p_facts ? v_fact THEN
          CONTINUE;
        END IF;
        -- internal cross-deadline references are resolved later; not blocking
        IF v_fact IN ('companies_house_accounts_filing','ct600_filing','partnership_tax_return_filing') THEN
          CONTINUE;
        END IF;
        v_missing := v_missing || v_fact;
      END LOOP;
    END IF;

    IF array_length(v_missing, 1) > 0 THEN
      -- create a client_task as a missing-fact placeholder (idempotent on title+job)
      IF NOT EXISTS (
        SELECT 1 FROM public.client_tasks
         WHERE job_id = p_job_id
           AND title = 'Missing data: ' || v_rule.deadline_name
      ) THEN
        INSERT INTO public.client_tasks (
          organization_id, client_id, company_id, job_id,
          title, description, status, visibility
        ) VALUES (
          v_job.organization_id, v_job.client_id, v_job.company_id, p_job_id,
          'Missing data: ' || v_rule.deadline_name,
          'Cannot compute "' || v_rule.deadline_name || '" — missing fact(s): '
            || array_to_string(v_missing, ', '),
          'pending', 'internal'
        );
        v_missing_facts_logged := v_missing_facts_logged + 1;
      END IF;
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code,
        'action', 'missing_facts',
        'missing', v_missing
      );
      CONTINUE;
    END IF;

    -- Compute due_date from calculation_method (covers the common shapes)
    IF v_calc ? 'add_months_to' THEN
      v_due := ((p_facts->>(v_calc->>'add_months_to'))::date
                + ((v_calc->>'months')::int || ' months')::interval)::date;
    ELSIF v_calc ? 'add_to' THEN
      v_due := ((p_facts->>(v_calc->>'add_to'))::date
                + ((COALESCE(v_calc->>'months','0'))::int || ' months')::interval
                + ((COALESCE(v_calc->>'days','0'))::int || ' days')::interval)::date;
    ELSIF v_calc ? 'fixed_date' AND COALESCE((v_calc->>'after_tax_year')::boolean, false) THEN
      -- tax year of form '2024/25' → year-end 5 April 2025 → due = fixed_date in calendar year after tax_year_end
      v_tax_year_end := (
        SELECT (split_part(p_facts->>'tax_year','/',1)::int + 1)::text || '-04-05'
      )::date;
      v_fixed_txt := v_calc->>'fixed_date';
      v_due := to_date(v_fixed_txt || ' ' || (extract(year FROM v_tax_year_end)::int + 1)::text, 'DD Month YYYY');
    ELSIF v_calc ? 'offset_days_before' THEN
      -- Resolve against a previously created deadline by deadline_code on this job
      SELECT due_date INTO v_due FROM public.deadlines
       WHERE job_id = p_job_id AND deadline_code = (v_calc->>'offset_days_before')
       ORDER BY created_at DESC LIMIT 1;
      IF v_due IS NOT NULL THEN
        v_due := v_due - ((v_calc->>'default_days')::int);
      END IF;
    END IF;

    IF v_due IS NULL THEN
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code,
        'action', 'unsupported_calculation'
      );
      CONTINUE;
    END IF;

    -- Idempotent upsert keyed on (job_id, deadline_code)
    SELECT id INTO v_existing FROM public.deadlines
     WHERE job_id = p_job_id AND deadline_code = v_rule.deadline_code
     LIMIT 1;

    IF v_existing IS NULL THEN
      INSERT INTO public.deadlines (
        organization_id, client_id, company_id, engagement_id, job_id,
        name, deadline_type, service_code, canonical_service_code, deadline_code,
        due_date, status
      ) VALUES (
        v_job.organization_id, v_job.client_id, v_job.company_id, NULL, p_job_id,
        v_rule.deadline_name, v_rule.deadline_type, v_job.canonical_service_code,
        v_job.canonical_service_code, v_rule.deadline_code,
        v_due, 'open'
      );
      v_created := v_created + 1;
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code, 'due_date', v_due, 'action', 'created'
      );
    ELSE
      UPDATE public.deadlines
         SET due_date = v_due, updated_at = now()
       WHERE id = v_existing AND status NOT IN ('completed','filed');
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_object(
        'deadline_code', v_rule.deadline_code, 'due_date', v_due, 'action', 'updated'
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status','ok',
    'job_id', p_job_id,
    'deadlines_created', v_created,
    'deadlines_updated', v_skipped,
    'missing_fact_tasks', v_missing_facts_logged,
    'results', v_results
  );
END;
$function$;

-- public.lifecycle_generate_jobs_for_service(p_engagement_id uuid, p_period_start date, p_period_end date) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6205ed61be5e8fbe954043d37be9b1b0 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_generate_jobs_for_service(p_engagement_id uuid, p_period_start date DEFAULT NULL::date, p_period_end date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_eng       RECORD;
  v_svc       RECORD;
  v_tpl       RECORD;
  v_job_id    uuid;
  v_existing  uuid;
  v_created   int := 0;
  v_skipped   int := 0;
  v_results   jsonb := '[]'::jsonb;
  v_period_label text;
BEGIN
  SELECT * INTO v_eng FROM public.engagements WHERE id = p_engagement_id;
  IF v_eng IS NULL THEN
    RAISE EXCEPTION 'Engagement % not found', p_engagement_id;
  END IF;

  IF NOT public._canonical_caller_in_org(v_eng.organization_id) THEN
    RAISE EXCEPTION 'Not authorised';
  END IF;

  IF NOT public._canonical_spine_enabled(v_eng.organization_id) THEN
    RETURN jsonb_build_object('status','skipped','reason','canonical_spine_v1 flag disabled');
  END IF;

  IF v_eng.canonical_service_code IS NULL THEN
    RAISE EXCEPTION 'Engagement % is not mapped to a canonical service', p_engagement_id;
  END IF;

  IF v_eng.status <> 'active' THEN
    RETURN jsonb_build_object('status','skipped','reason','engagement not active');
  END IF;

  SELECT * INTO v_svc FROM public.canonical_services WHERE code = v_eng.canonical_service_code;
  IF v_svc IS NULL OR NOT v_svc.creates_jobs THEN
    RETURN jsonb_build_object('status','skipped','reason','canonical service does not create jobs');
  END IF;

  v_period_label := CASE
    WHEN p_period_start IS NOT NULL AND p_period_end IS NOT NULL
      THEN to_char(p_period_start,'YYYY-MM-DD') || ' to ' || to_char(p_period_end,'YYYY-MM-DD')
    ELSE NULL
  END;

  FOR v_tpl IN
    SELECT * FROM public.canonical_job_templates
     WHERE canonical_service_code = v_eng.canonical_service_code AND active = true
  LOOP
    -- Idempotency key: org + entity + job_template_code + period
    SELECT id INTO v_existing
      FROM public.jobs
     WHERE organization_id = v_eng.organization_id
       AND job_template_code = v_tpl.job_template_code
       AND COALESCE(client_id::text,'') = COALESCE(v_eng.client_id::text,'')
       AND COALESCE(company_id::text,'') = COALESCE(v_eng.company_id::text,'')
       AND COALESCE(period_start::text,'') = COALESCE(p_period_start::text,'')
       AND COALESCE(period_end::text,'')   = COALESCE(p_period_end::text,'')
     LIMIT 1;

    IF v_existing IS NULL THEN
      INSERT INTO public.jobs (
        organization_id, client_id, company_id, job_name, service_type,
        canonical_service_code, job_template_code,
        period_start, period_end, period_label,
        status, priority, is_auto_generated, auto_generated_at, generation_reason,
        automation_source
      ) VALUES (
        v_eng.organization_id, v_eng.client_id, v_eng.company_id,
        v_tpl.display_name || COALESCE(' — ' || v_period_label, ''),
        v_eng.canonical_service_code, -- service_type kept human readable; canonical codes carry truth
        v_eng.canonical_service_code, v_tpl.job_template_code,
        p_period_start, p_period_end, v_period_label,
        COALESCE(v_tpl.default_status, 'blank'), 'normal', true, now(),
        'canonical_lifecycle',
        'canonical_spine_v1'
      )
      RETURNING id INTO v_job_id;
      v_created := v_created + 1;
      v_results := v_results || jsonb_build_object(
        'job_template_code', v_tpl.job_template_code,
        'job_id', v_job_id,
        'action', 'created'
      );
    ELSE
      v_skipped := v_skipped + 1;
      v_results := v_results || jsonb_build_object(
        'job_template_code', v_tpl.job_template_code,
        'job_id', v_existing,
        'action', 'reused'
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status','ok',
    'engagement_id', p_engagement_id,
    'jobs_created', v_created,
    'jobs_reused', v_skipped,
    'results', v_results
  );
END;
$function$;

-- public.lifecycle_grant_portal_access(p_entity_type text, p_entity_id uuid, p_email text, p_role text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public, extensions
--   definition_hash=064bb868db3286290223eb193c1fccd9 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_grant_portal_access(p_entity_type text, p_entity_id uuid, p_email text, p_role text DEFAULT 'primary_contact'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_organization_id uuid;
  v_user_id uuid;
  v_portal_access_id uuid;
  v_invite_token text;
  v_invite_expires_at timestamptz;
  v_entity_name text;
  v_firm_name text;
  v_portal_url text;
BEGIN
  IF p_entity_type = 'client' THEN
    SELECT organization_id, (first_name || ' ' || last_name)
    INTO v_organization_id, v_entity_name
    FROM clients WHERE id = p_entity_id;
    IF v_organization_id IS NULL THEN
      RAISE EXCEPTION 'Client not found: %', p_entity_id;
    END IF;
  ELSIF p_entity_type = 'company' THEN
    SELECT organization_id, company_name
    INTO v_organization_id, v_entity_name
    FROM companies WHERE id = p_entity_id;
    IF v_organization_id IS NULL THEN
      RAISE EXCEPTION 'Company not found: %', p_entity_id;
    END IF;
  ELSE
    RAISE EXCEPTION 'Invalid entity_type: %. Must be "client" or "company"', p_entity_type;
  END IF;

  IF NOT user_has_organization_access(v_organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT name INTO v_firm_name FROM organizations WHERE id = v_organization_id;
  SELECT id INTO v_user_id FROM auth.users WHERE email = p_email LIMIT 1;

  v_invite_token := generate_invite_token();
  v_invite_expires_at := now() + interval '14 days';

  INSERT INTO portal_access (
    organization_id, user_id, client_id, company_id, role, status, is_active,
    invite_token, invite_expires_at, invited_at, created_by
  )
  VALUES (
    v_organization_id, v_user_id,
    CASE WHEN p_entity_type = 'client' THEN p_entity_id ELSE NULL END,
    CASE WHEN p_entity_type = 'company' THEN p_entity_id ELSE NULL END,
    p_role, 'invited', true, v_invite_token, v_invite_expires_at, now(), auth.uid()
  )
  RETURNING id INTO v_portal_access_id;

  v_portal_url := 'https://client.accountancyos.com/auth/portal-invite?token=' || v_invite_token;

  INSERT INTO email_queue (
    organization_id, to_email, subject, body_html, entity_type, entity_id, merge_data, status, context
  )
  VALUES (
    v_organization_id,
    p_email,
    'You have passed AML verification - set up your ' || v_firm_name || ' client portal',
    '<p>Hello ' || v_entity_name || ',</p>' ||
    '<p>Good news - you have successfully passed our AML (Anti-Money Laundering) verification checks with ' || v_firm_name || '.</p>' ||
    '<p>The final step is to set up your secure client portal login. From the portal you can view your jobs, share documents, approve work, and message us directly.</p>' ||
    '<p><a href="' || v_portal_url || '" style="display:inline-block;padding:10px 18px;background:#0f766e;color:#ffffff;text-decoration:none;border-radius:6px;">Set up your client portal</a></p>' ||
    '<p>This link is valid for 14 days. If it expires, just let us know and we will reissue it.</p>' ||
    '<p>Kind regards,<br/>' || v_firm_name || '</p>',
    'portal_access',
    v_portal_access_id,
    jsonb_build_object(
      'client_name', v_entity_name,
      'firm_name', v_firm_name,
      'portal_url', v_portal_url
    ),
    'pending',
    'onboarding'
  );

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (
    v_organization_id, 'portal_access', v_portal_access_id, 'invited', auth.uid(),
    jsonb_build_object('email', p_email, 'target_entity_type', p_entity_type, 'target_entity_id', p_entity_id, 'role', p_role)
  );

  RETURN jsonb_build_object(
    'portal_access_id', v_portal_access_id,
    'invite_token', v_invite_token,
    'invite_expires_at', v_invite_expires_at,
    'email_queued', true,
    'user_exists', v_user_id IS NOT NULL,
    'ok', true
  );
END;
$function$;

-- public.lifecycle_materialize_jobs(p_org uuid, p_client_id uuid, p_company_id uuid, p_partnership_id uuid, p_quote_id uuid, p_source text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=c22e5a254856b3204fd16ca0683dbd8d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_materialize_jobs(p_org uuid, p_client_id uuid, p_company_id uuid, p_partnership_id uuid, p_quote_id uuid, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today date := CURRENT_DATE;
  v_company record;
  v_tax_year_start date; v_tax_year_end date;
  v_line record; v_frequency text;
  v_target_client uuid; v_target_company uuid; v_engagement_id uuid;
  v_period_start date; v_period_end date; v_period_label text;
  v_jobs int := 0;
BEGIN
  IF p_company_id IS NOT NULL THEN
    SELECT * INTO v_company FROM public.companies WHERE id = p_company_id;
  ELSE
    SELECT NULL::uuid AS id, NULL::int AS year_end_month, NULL::int AS year_end_day INTO v_company;
  END IF;

  IF EXTRACT(MONTH FROM v_today) > 4
     OR (EXTRACT(MONTH FROM v_today) = 4 AND EXTRACT(DAY FROM v_today) >= 6) THEN
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int, 4, 6);
  ELSE
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int - 1, 4, 6);
  END IF;
  v_tax_year_end := v_tax_year_start + INTERVAL '1 year' - INTERVAL '1 day';

  FOR v_line IN
    SELECT ql.*, sc.entity_scope, sc.code, sc.name AS service_name
    FROM public.quote_lines ql
    JOIN public.services_catalog sc ON sc.id = ql.service_id
    WHERE ql.quote_id = p_quote_id
  LOOP
    v_frequency := CASE WHEN v_line.billing_frequency = 'monthly' THEN 'monthly' ELSE 'one_off' END;

    IF v_line.entity_scope = 'company'
       OR (v_line.entity_scope = 'either' AND p_company_id IS NOT NULL
           AND v_line.code NOT IN ('sa_mtd','sa_non_mtd','cgt_60_day')) THEN
      v_target_company := p_company_id; v_target_client := NULL;
    ELSIF v_line.entity_scope = 'partnership' THEN
      v_target_client := COALESCE(p_partnership_id, p_client_id); v_target_company := NULL;
    ELSE
      v_target_client := p_client_id; v_target_company := NULL;
    END IF;
    IF v_target_client IS NULL AND v_target_company IS NULL THEN CONTINUE; END IF;

    SELECT id INTO v_engagement_id FROM public.engagements
      WHERE quote_id = p_quote_id AND service_id = v_line.service_id LIMIT 1;
    IF v_engagement_id IS NULL THEN
      INSERT INTO public.engagements
        (organization_id, client_id, company_id, service_id, quote_id, frequency, start_date, status, activated_at)
      VALUES
        (p_org, v_target_client, v_target_company, v_line.service_id, p_quote_id, v_frequency, v_today, 'active', now())
      RETURNING id INTO v_engagement_id;
    END IF;

    v_period_start := NULL; v_period_end := NULL; v_period_label := NULL;
    IF v_target_company IS NOT NULL AND v_company.year_end_month IS NOT NULL AND v_company.year_end_day IS NOT NULL THEN
      v_period_end := make_date(EXTRACT(YEAR FROM v_today)::int, v_company.year_end_month, v_company.year_end_day);
      IF v_period_end > v_today THEN v_period_end := v_period_end - INTERVAL '1 year'; END IF;
      v_period_start := v_period_end - INTERVAL '1 year' + INTERVAL '1 day';
      v_period_label := to_char(v_period_end, 'YYYY') || ' Year-End';
    ELSIF v_line.code IN ('sa_mtd','sa_non_mtd') THEN
      v_period_start := v_tax_year_start; v_period_end := v_tax_year_end;
      v_period_label := EXTRACT(YEAR FROM v_tax_year_start)::text || '/' || substr(EXTRACT(YEAR FROM v_tax_year_end)::text, 3, 2);
    ELSIF v_line.code = 'payroll' THEN
      v_period_start := date_trunc('month', v_today)::date;
      v_period_end := (date_trunc('month', v_today) + INTERVAL '1 month - 1 day')::date;
      v_period_label := to_char(v_today, 'Mon YYYY');
    ELSE
      v_period_start := v_today; v_period_end := v_today + INTERVAL '30 days'; v_period_label := 'Setup Pending';
    END IF;

    -- Proposal Phase 1 T1 (the ONLY behavioural change): an explicit per-line period set on
    -- the quote_line wins over the computed fallback above. Fully backward-compatible — a NULL
    -- line period (every pre-existing line) falls straight through to the computed value.
    v_period_start := COALESCE(v_line.period_start, v_period_start);
    v_period_end   := COALESCE(v_line.period_end,   v_period_end);
    v_period_label := COALESCE(NULLIF(v_line.period_label, ''), v_period_label);

    PERFORM public.lifecycle_upsert_job_with_deadlines(
      p_org, v_target_client, v_target_company, v_engagement_id,
      v_line.code, v_line.service_name, v_period_start, v_period_end, v_period_label, p_source);
    v_jobs := v_jobs + 1;
  END LOOP;

  -- Proposal Phase 1 T6b-2 (the ONLY addition in this migration): a CT600 job depends on
  -- the finalised Accounts for the SAME company + SAME accounts year-end. Idempotent —
  -- only writes when the link differs, and only when we are materializing for a company.
  -- The ct.period_end IS NOT NULL guard prevents a NULL period_end from cross-linking a
  -- CT600 to an Accounts job of a different (or unknown) accounts year.
  IF p_company_id IS NOT NULL THEN
    UPDATE public.jobs ct
       SET prerequisite_job_id = acc.id
      FROM public.jobs acc
     WHERE ct.organization_id = p_org
       AND ct.company_id      = p_company_id
       AND ct.service_type    = 'corporation_tax'
       AND ct.period_end      IS NOT NULL
       AND acc.organization_id = p_org
       AND acc.company_id      = p_company_id
       AND acc.service_type    = 'company_accounts'
       AND acc.period_end      = ct.period_end          -- same accounts year-end
       AND ct.prerequisite_job_id IS DISTINCT FROM acc.id;
  END IF;

  RETURN jsonb_build_object('status','ok','services', v_jobs);
END;
$function$;

-- public.lifecycle_onboarding_gates(p_application_id uuid) -> jsonb
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=c63e7e14444091cb878be291da1b93ed (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_onboarding_gates(p_application_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  a                  public.onboarding_applications%ROWTYPE;
  v_el_signed        boolean := false;
  v_aml              boolean := false;
  v_billing          boolean := false;
  v_submitted        boolean := false;
  v_open             boolean := false;
  v_context          boolean := false;
  v_has_lines        boolean := false;
  v_activation_ready boolean := false;
  v_letter_id        uuid;
  v_sig              jsonb;
  v_outstanding      text[] := ARRAY[]::text[];
BEGIN
  SELECT * INTO a FROM public.onboarding_applications WHERE id = p_application_id;
  IF a.id IS NULL THEN
    RETURN jsonb_build_object('error', 'application_not_found', 'all_pass', false,
                              'activation_ready', false,
                              'outstanding', to_jsonb(ARRAY['application_not_found']));
  END IF;

  -- T2b: engagement-letter signature via the signature RULE over engagement_letter_signatories,
  -- with the legacy single-signer check as fallback when no signatory rows exist.
  -- T2d-1: the rule itself now lives in public.el_signature_progress (one implementation).
  -- Equivalence with the T2b inline block: has_signatories mirrors the previous
  -- EXISTS(required rows) branch test, and `satisfied` computes the same
  -- 'any' => signed >= 1 / 'all' => total > 0 AND signed = total over the same rows.
  SELECT el.id INTO v_letter_id
    FROM public.engagement_letters el
   WHERE el.onboarding_application_id = p_application_id
   ORDER BY el.created_at DESC
   LIMIT 1;

  v_sig := public.el_signature_progress(v_letter_id);

  IF COALESCE((v_sig->>'has_signatories')::boolean, false) THEN
    v_el_signed := COALESCE((v_sig->>'satisfied')::boolean, false);
  ELSE
    -- Legacy fallback: unchanged from the live body (signed letter + contracts_signed_at).
    v_el_signed := (
      EXISTS (
        SELECT 1 FROM public.engagement_letters el
        WHERE el.onboarding_application_id = p_application_id AND el.signed_at IS NOT NULL
      )
      AND a.contracts_signed_at IS NOT NULL
    );
  END IF;

  v_aml       := (a.aml_status = 'verified');
  v_billing   := (a.billing_status IN ('completed','skipped','not_required'));
  v_submitted := (a.submitted_for_review_at IS NOT NULL OR a.status IN ('portal_pending','for_review'));
  v_open      := (a.status NOT IN ('approved','rejected','cancelled'));

  SELECT EXISTS (SELECT 1 FROM public.quote_lines ql WHERE ql.quote_id = a.quote_id) INTO v_has_lines;
  v_context := (
    a.organization_id IS NOT NULL
    AND a.quote_id IS NOT NULL
    AND v_has_lines
    AND (a.client_id IS NOT NULL OR a.company_id IS NOT NULL
         OR a.application_type IN ('individual','company'))
  );

  IF NOT v_el_signed THEN v_outstanding := v_outstanding || 'engagement_letter_signed'; END IF;
  IF NOT v_aml       THEN v_outstanding := v_outstanding || 'aml_passed'; END IF;
  IF NOT v_billing   THEN v_outstanding := v_outstanding || 'billing_settled'; END IF;
  IF NOT v_submitted THEN v_outstanding := v_outstanding || 'onboarding_submitted'; END IF;
  IF NOT v_open      THEN v_outstanding := v_outstanding || 'not_already_closed'; END IF;
  IF NOT v_context   THEN v_outstanding := v_outstanding || 'missing_activation_context'; END IF;

  -- T2b: activation gates on signatures/AML/submission/open/context — NOT billing.
  v_activation_ready := (v_el_signed AND v_aml AND v_submitted AND v_open AND v_context);

  RETURN jsonb_build_object(
    'gates', jsonb_build_object(
      'engagement_letter_signed', v_el_signed,
      'aml_passed', v_aml,
      'billing_settled', v_billing,
      'onboarding_submitted', v_submitted,
      'not_already_closed', v_open,
      'activation_context_present', v_context
    ),
    'all_pass', (array_length(v_outstanding, 1) IS NULL),
    'activation_ready', v_activation_ready,
    'billing_settled', v_billing,
    'outstanding', to_jsonb(v_outstanding)
  );
END;
$function$;

-- public.lifecycle_reconciliation_report(p_organization_id uuid) -> jsonb
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=d4634378cc5a22928f4257ca8da54172 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_reconciliation_report(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_jobs_total       int;
  v_setup_pending    int;
  v_null_label       int;
  v_both_entity      int;
  v_dup_groups       int;
  v_dup_excess       int;
  v_null_dup_groups  int;
  v_active_links     int;
  v_accepted_no_onb  int;
  v_onb_unlinked     int;
  v_dup_onb_groups   int;
  v_present          text[];
  v_expected         text[] := ARRAY['jobs_client_period_uq','jobs_company_period_uq',
                                     'engagements_quote_service_uq','acl_active_client_uq',
                                     'acl_active_company_uq'];
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
     WHERE organization_id = p_organization_id AND user_id = auth.uid()
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  SELECT count(*) INTO v_jobs_total
    FROM public.jobs WHERE organization_id = p_organization_id;

  SELECT count(*) INTO v_setup_pending
    FROM public.jobs
   WHERE organization_id = p_organization_id AND period_label ILIKE 'Setup Pending';

  SELECT count(*) INTO v_null_label
    FROM public.jobs
   WHERE organization_id = p_organization_id AND period_label IS NULL AND status <> 'cancelled';

  SELECT count(*) INTO v_both_entity
    FROM public.jobs
   WHERE organization_id = p_organization_id
     AND client_id IS NOT NULL AND company_id IS NOT NULL;

  WITH grp AS (
    SELECT count(*) AS n FROM public.jobs
     WHERE organization_id = p_organization_id AND status <> 'cancelled'
     GROUP BY service_type, client_id, company_id, period_label HAVING count(*) > 1
  )
  SELECT COALESCE(count(*),0), COALESCE(sum(n - 1),0) INTO v_dup_groups, v_dup_excess FROM grp;

  WITH ngrp AS (
    SELECT 1 FROM public.jobs
     WHERE organization_id = p_organization_id AND status <> 'cancelled' AND period_label IS NULL
     GROUP BY service_type, client_id, company_id HAVING count(*) > 1
  )
  SELECT COALESCE(count(*),0) INTO v_null_dup_groups FROM ngrp;

  SELECT count(*) INTO v_active_links
    FROM public.accountant_client_links
   WHERE practice_id = p_organization_id AND status = 'active';

  SELECT count(*) INTO v_accepted_no_onb
    FROM public.quotes q
   WHERE q.organization_id = p_organization_id
     AND q.status = 'accepted'
     AND NOT EXISTS (
       SELECT 1 FROM public.onboarding_applications o
        WHERE o.quote_id = q.id AND o.status <> 'rejected');

  SELECT count(*) INTO v_onb_unlinked
    FROM public.onboarding_applications o
   WHERE o.organization_id = p_organization_id
     AND o.status NOT IN ('approved','rejected')
     AND o.client_id IS NULL AND o.company_id IS NULL;

  WITH og AS (
    SELECT quote_id FROM public.onboarding_applications
     WHERE organization_id = p_organization_id AND quote_id IS NOT NULL AND status <> 'rejected'
     GROUP BY quote_id HAVING count(*) > 1
  )
  SELECT COALESCE(count(*),0) INTO v_dup_onb_groups FROM og;

  SELECT COALESCE(array_agg(indexname), ARRAY[]::text[]) INTO v_present
    FROM pg_indexes
   WHERE schemaname = 'public' AND indexname = ANY(v_expected);

  RETURN jsonb_build_object(
    'success', true,
    'organization_id', p_organization_id,
    'jobs_total', v_jobs_total,
    'setup_pending_jobs', v_setup_pending,
    'null_period_label_jobs', v_null_label,
    'both_entity_jobs', v_both_entity,
    'duplicate_job_groups', v_dup_groups,
    'duplicate_job_excess_rows', v_dup_excess,
    'null_label_duplicate_groups', v_null_dup_groups,
    'active_client_links', v_active_links,
    'accepted_quotes_without_onboarding', v_accepted_no_onb,
    'onboarding_apps_unlinked', v_onb_unlinked,
    'duplicate_onboarding_app_groups', v_dup_onb_groups,
    'backstop_indexes_present', to_jsonb(v_present),
    'backstop_indexes_missing', to_jsonb(ARRAY(SELECT unnest(v_expected) EXCEPT SELECT unnest(v_present)))
  );
END;
$function$;

-- public.lifecycle_require_onboarding_token(p_application_id uuid, p_access_token text) -> void
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=1d1f13163f807bb4397892d8159bb42e (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_require_onboarding_token(p_application_id uuid, p_access_token text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_access_token IS NULL
     OR NOT public.validate_onboarding_access_token(p_application_id, p_access_token) THEN
    RAISE EXCEPTION 'Invalid or missing onboarding access token' USING ERRCODE='42501';
  END IF;
END;
$function$;

-- public.lifecycle_send_back_onboarding(p_application_id uuid, p_step text, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=e6dc695ce6c40cc67b80ff9b44cd8ffe (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_send_back_onboarding(p_application_id uuid, p_step text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app RECORD;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Onboarding application % not found', p_application_id;
  END IF;

  UPDATE public.onboarding_applications
     SET status = 'needs_client_action',
         updated_at = now()
   WHERE id = p_application_id;

  IF v_app.email IS NOT NULL AND v_app.email <> '' THEN
    INSERT INTO public.email_queue (
      organization_id, to_email, to_name, subject, body_html,
      entity_type, entity_id, context, status
    ) VALUES (
      v_app.organization_id,
      v_app.email,
      COALESCE(v_app.company_name, TRIM(COALESCE(v_app.first_name,'') || ' ' || COALESCE(v_app.last_name,''))),
      'Action required to complete your onboarding',
      '<p>Hello,</p><p>Your accountant has reviewed your onboarding and needs you to revisit the <strong>' || p_step || '</strong> step.</p>' ||
      CASE WHEN p_reason IS NOT NULL AND p_reason <> '' THEN '<p><em>' || p_reason || '</em></p>' ELSE '' END ||
      '<p>Please continue here: <a href="' || COALESCE(current_setting('app.public_url', true), '') || '/onboard/' || p_application_id || '">Resume onboarding</a></p>',
      'onboarding_application',
      p_application_id,
      'onboarding',
      'pending'
    );
  END IF;

  RETURN jsonb_build_object('status', 'needs_client_action');
END;
$function$;

-- public.lifecycle_send_quote(p_quote_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=fefe19452b09623662b7dcd318e3fce1 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_send_quote(p_quote_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_quote               record;
  v_line_count          integer;
  v_recipient_email     text;
  v_recipient_name      text;
  v_recipient_first     text;
  v_preferred           text;
  v_first               text;
  v_last                text;
  v_email_queued        boolean := false;
  v_practice_name       text;
  v_template_id         uuid;
  v_template_content    jsonb;
  v_token               uuid;
  v_valid_until         date;
  v_lines_html          text := '';
  v_line                record;
  v_freq_label          text;
  v_unit_display        numeric;
  v_subtotal_display    numeric;
  v_unit_suffix         text;
  v_subtotal_suffix     text;
  v_total_now           numeric := 0;
  v_total_monthly       numeric := 0;
  v_base_url            text := 'https://app.accountancyos.com';
  v_subject             text;
  v_body_html           text;
  v_merge               jsonb;
  v_key                 text;
  v_val                 text;
  v_currency            text;
  v_accept_url          text;
  v_mailbox_id          uuid;
  v_mailbox_provider    text;
  v_mailbox_from        text;
  v_creator             uuid;
BEGIN
  SELECT * INTO v_quote FROM quotes WHERE id = p_quote_id;
  IF v_quote.id IS NULL THEN RAISE EXCEPTION 'Quote not found: %', p_quote_id; END IF;
  IF NOT user_has_organization_access(v_quote.organization_id) THEN RAISE EXCEPTION 'Access denied to organization'; END IF;
  IF v_quote.status != 'draft' THEN RAISE EXCEPTION 'Quote cannot be sent. Current status: %. Only draft quotes can be sent.', v_quote.status; END IF;

  SELECT COUNT(*) INTO v_line_count FROM quote_lines WHERE quote_id = p_quote_id;
  IF v_line_count = 0 THEN RAISE EXCEPTION 'Quote has no line items. Add services before sending.'; END IF;

  v_valid_until := COALESCE(v_quote.valid_until, (now() + interval '30 days')::date);
  v_currency := COALESCE(v_quote.currency, 'GBP');
  v_creator := COALESCE(v_quote.created_by, auth.uid());

  IF v_quote.lead_id IS NOT NULL THEN
    SELECT email, first_name, last_name
      INTO v_recipient_email, v_first, v_last
    FROM leads WHERE id = v_quote.lead_id;
  ELSIF v_quote.client_id IS NOT NULL THEN
    SELECT email, preferred_name, first_name, last_name
      INTO v_recipient_email, v_preferred, v_first, v_last
    FROM clients WHERE id = v_quote.client_id;
  END IF;

  IF v_recipient_email IS NULL AND v_quote.company_id IS NOT NULL THEN
    SELECT c.email, c.preferred_name, c.first_name, c.last_name
      INTO v_recipient_email, v_preferred, v_first, v_last
    FROM clients c
    WHERE c.company_id = v_quote.company_id
      AND c.email IS NOT NULL
    ORDER BY c.created_at ASC
    LIMIT 1;

    IF v_recipient_email IS NULL THEN
      SELECT email INTO v_recipient_email FROM companies WHERE id = v_quote.company_id;
    END IF;
  END IF;

  v_recipient_first := COALESCE(NULLIF(trim(v_preferred), ''), NULLIF(trim(v_first), ''));
  v_recipient_name  := COALESCE(
    NULLIF(trim(v_preferred), ''),
    NULLIF(trim(coalesce(v_first,'') || ' ' || coalesce(v_last,'')), '')
  );

  IF v_recipient_name IS NULL AND v_quote.company_id IS NOT NULL THEN
    SELECT company_name INTO v_recipient_name FROM companies WHERE id = v_quote.company_id;
    v_recipient_first := COALESCE(v_recipient_first, v_recipient_name);
  END IF;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_practice_name
  FROM organizations o
  LEFT JOIN organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_quote.organization_id;

  IF v_creator IS NOT NULL THEN
    SELECT id, provider, email_address
      INTO v_mailbox_id, v_mailbox_provider, v_mailbox_from
    FROM connected_mailboxes
    WHERE organization_id = v_quote.organization_id
      AND user_id = v_creator
      AND status = 'active'
      AND COALESCE(sync_enabled, true) = true
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  IF v_mailbox_id IS NULL THEN
    SELECT id, provider, email_address
      INTO v_mailbox_id, v_mailbox_provider, v_mailbox_from
    FROM connected_mailboxes
    WHERE organization_id = v_quote.organization_id
      AND status = 'active'
      AND COALESCE(sync_enabled, true) = true
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  SELECT id, content INTO v_template_id, v_template_content
  FROM templates
  WHERE organization_id = v_quote.organization_id
    AND type = 'email'
    AND (
          COALESCE(tags, '[]'::jsonb) ? 'quote'
       OR name ILIKE '%quote%'
       OR name ILIKE '%proposal%'
        )
    AND COALESCE(status, 'active') = 'active'
  ORDER BY updated_at DESC NULLS LAST
  LIMIT 1;

  FOR v_line IN
    SELECT ql.*, sc.name AS service_name
    FROM quote_lines ql
    LEFT JOIN services_catalog sc ON sc.id = ql.service_id
    WHERE ql.quote_id = p_quote_id
    ORDER BY ql.line_order
  LOOP
    IF v_line.billing_frequency = 'monthly' THEN
      v_freq_label := 'Monthly';
      v_unit_display := ROUND(COALESCE(v_line.unit_price,0) / 12.0, 2);
      v_subtotal_display := ROUND(v_unit_display * COALESCE(v_line.quantity,1), 2);
      v_unit_suffix := '/mo';
      v_subtotal_suffix := '/mo';
      v_total_monthly := v_total_monthly + v_subtotal_display;
    ELSE
      v_freq_label := 'Bill Now';
      v_unit_display := COALESCE(v_line.unit_price, 0);
      v_subtotal_display := COALESCE(v_line.subtotal, v_unit_display * COALESCE(v_line.quantity,1));
      v_unit_suffix := '';
      v_subtotal_suffix := '';
      v_total_now := v_total_now + v_subtotal_display;
    END IF;

    v_lines_html := v_lines_html ||
      '<tr><td style="padding:6px 8px;border-bottom:1px solid #eee">' || COALESCE(v_line.service_name, 'Service') ||
      '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">' || COALESCE(v_line.quantity,1) ||
      '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">' || v_currency || ' ' || to_char(v_unit_display, 'FM999,999,990.00') || v_unit_suffix ||
      '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">' || v_currency || ' ' || to_char(v_subtotal_display, 'FM999,999,990.00') || v_subtotal_suffix ||
      '</td></tr>';
  END LOOP;

  v_lines_html :=
    '<table style="border-collapse:collapse;width:100%;margin:12px 0">' ||
    '<thead><tr>' ||
    '<th style="text-align:left;padding:6px 8px;border-bottom:2px solid #ccc">Service</th>' ||
    '<th style="text-align:right;padding:6px 8px;border-bottom:2px solid #ccc">Qty</th>' ||
    '<th style="text-align:right;padding:6px 8px;border-bottom:2px solid #ccc">Unit</th>' ||
    '<th style="text-align:right;padding:6px 8px;border-bottom:2px solid #ccc">Subtotal</th>' ||
    '</tr></thead><tbody>' || v_lines_html || '</tbody></table>';

  v_token := gen_random_uuid();
  INSERT INTO quote_acceptance_tokens(token, quote_id, organization_id, expires_at)
  VALUES (v_token, p_quote_id, v_quote.organization_id, now() + interval '30 days');

  v_accept_url := v_base_url || '/q/' || v_token::text;

  v_merge := jsonb_build_object(
    'recipient_name', v_recipient_name,
    'recipient_first_name', v_recipient_first,
    'practice_name', v_practice_name,
    'quote_number', v_quote.quote_number,
    'currency', v_currency,
    'total_now', to_char(v_total_now, 'FM999,999,990.00'),
    'total_monthly', to_char(v_total_monthly, 'FM999,999,990.00'),
    'total_amount', to_char(COALESCE(v_quote.total_amount, 0), 'FM999,999,990.00'),
    'valid_until', to_char(v_valid_until, 'DD Mon YYYY'),
    'accept_url', v_accept_url,
    'lines_html', v_lines_html,
    'quote_total_now', to_char(v_total_now, 'FM999,999,990.00'),
    'quote_total_monthly', to_char(v_total_monthly, 'FM999,999,990.00'),
    'quote_total', to_char(COALESCE(v_quote.total_amount, 0), 'FM999,999,990.00'),
    'accept_link', v_accept_url,
    'quote_lines_table', v_lines_html
  );

  IF v_template_content IS NOT NULL THEN
    v_subject   := COALESCE(v_template_content->>'subject', 'Proposal from ' || v_practice_name);
    v_body_html := COALESCE(
      NULLIF(v_template_content->>'htmlBody', ''),
      NULLIF(v_template_content->>'body_html', ''),
      NULLIF(v_template_content->>'body', ''),
      ''
    );
    FOR v_key, v_val IN SELECT * FROM jsonb_each_text(v_merge) LOOP
      v_subject   := replace(v_subject, '{{' || v_key || '}}', COALESCE(v_val,''));
      v_body_html := replace(v_body_html, '{{' || v_key || '}}', COALESCE(v_val,''));
    END LOOP;
  ELSE
    v_subject := 'Proposal ' || v_quote.quote_number || ' from ' || v_practice_name;
    v_body_html :=
      '<p>Dear ' || COALESCE(v_recipient_first, v_recipient_name, 'Client') || ',</p>' ||
      '<p>Please find your proposal below.</p>' ||
      v_lines_html ||
      '<p><strong>Payable Now:</strong> ' || v_currency || ' ' || to_char(v_total_now, 'FM999,999,990.00') || '<br/>' ||
      '<strong>Payable Monthly:</strong> ' || v_currency || ' ' || to_char(v_total_monthly, 'FM999,999,990.00') || '</p>' ||
      '<p><a href="' || v_accept_url || '">Review and accept your proposal</a></p>' ||
      '<p>Kind regards,<br/>' || v_practice_name || '</p>';
  END IF;

  IF v_body_html !~ '<[a-zA-Z]' THEN
    v_body_html := replace(v_body_html, E'\n', '<br/>');
  END IF;

  IF v_recipient_email IS NOT NULL THEN
    INSERT INTO email_queue (
      organization_id, client_id, company_id,
      entity_type, entity_id, context,
      to_email, to_name, subject, body_html,
      mailbox_id, provider, created_by, queued_by,
      status, scheduled_at, created_at
    ) VALUES (
      v_quote.organization_id, v_quote.client_id, v_quote.company_id,
      'quote', v_quote.id, 'quote',
      v_recipient_email, v_recipient_name, v_subject, v_body_html,
      v_mailbox_id, v_mailbox_provider, v_creator, auth.uid(),
      'pending', now() + interval '15 minutes', now()
    );
    v_email_queued := true;
  END IF;

  UPDATE quotes
     SET status = 'sent',
         sent_at = COALESCE(sent_at, now()),
         valid_until = v_valid_until,
         updated_at = now()
   WHERE id = p_quote_id;

  RETURN jsonb_build_object(
    'quote_id', p_quote_id,
    'status', 'sent',
    'email_queued', v_email_queued,
    'recipient_email', v_recipient_email,
    'recipient_name', v_recipient_name,
    'sender_mailbox', v_mailbox_from,
    'sender_provider', v_mailbox_provider
  );
END;
$function$;

-- public.lifecycle_upsert_job_with_deadlines(p_org uuid, p_client_id uuid, p_company_id uuid, p_engagement_id uuid, p_service_code text, p_service_name text, p_period_start date, p_period_end date, p_period_label text, p_source text) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=4ae64b2266bef739f9180589ed385a62 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lifecycle_upsert_job_with_deadlines(p_org uuid, p_client_id uuid, p_company_id uuid, p_engagement_id uuid, p_service_code text, p_service_name text, p_period_start date, p_period_end date, p_period_label text, p_source text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filing_deadline date;
  v_job_id uuid;
BEGIN
  v_filing_deadline := CASE p_service_code
    WHEN 'company_accounts' THEN public.calculate_deadline('companies_house_accounts', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'confirmation_statement' THEN public.calculate_deadline('companies_house_confirmation', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'corporation_tax' THEN public.calculate_deadline('corporation_tax_filing', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'sa_mtd' THEN public.calculate_deadline('self_assessment', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'sa_non_mtd' THEN public.calculate_deadline('self_assessment', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'vat_return' THEN public.calculate_deadline('vat_return', p_period_start, p_period_end, '{}'::jsonb)
    WHEN 'payroll' THEN public.calculate_deadline('payroll_fps', p_period_start, p_period_end, '{}'::jsonb)
    ELSE NULL
  END;

  SELECT id INTO v_job_id FROM public.jobs
    WHERE organization_id = p_org
      AND service_type = p_service_code
      AND COALESCE(client_id::text,'') = COALESCE(p_client_id::text,'')
      AND COALESCE(company_id::text,'') = COALESCE(p_company_id::text,'')
      AND COALESCE(period_label,'') = COALESCE(p_period_label,'')
    LIMIT 1;

  IF v_job_id IS NULL THEN
    INSERT INTO public.jobs (organization_id, client_id, company_id, job_name, service_type,
                             period_start, period_end, period_label, status, priority,
                             filing_deadline, automation_source, is_auto_generated, auto_generated_at,
                             generation_reason)
    VALUES (p_org, p_client_id, p_company_id,
            p_service_name || ' - ' || COALESCE(p_period_label,'Setup Pending'),
            p_service_code, p_period_start, p_period_end, p_period_label,
            'blank', 'normal', v_filing_deadline, 'template', true, now(),
            p_source)
    RETURNING id INTO v_job_id;
  END IF;

  IF v_filing_deadline IS NOT NULL AND p_service_code IN ('company_accounts','confirmation_statement','corporation_tax','sa_mtd','sa_non_mtd','vat_return','payroll') THEN
    INSERT INTO public.deadlines (organization_id, client_id, company_id, engagement_id, job_id,
                                  name, deadline_type, filing_body, service_code,
                                  period_start, period_end, due_date, warning_date, status)
    SELECT p_org, p_client_id, p_company_id, p_engagement_id, v_job_id,
           p_service_name || ' - ' || COALESCE(p_period_label,''),
           'statutory',
           CASE p_service_code
             WHEN 'company_accounts' THEN 'COMPANIES_HOUSE'
             WHEN 'confirmation_statement' THEN 'COMPANIES_HOUSE'
             ELSE 'HMRC'
           END,
           p_service_code, p_period_start, p_period_end, v_filing_deadline,
           v_filing_deadline - INTERVAL '30 days', 'pending'
    WHERE NOT EXISTS (
      SELECT 1 FROM public.deadlines
      WHERE job_id = v_job_id AND service_code = p_service_code AND due_date = v_filing_deadline
    );

    IF p_service_code = 'corporation_tax' THEN
      INSERT INTO public.deadlines (organization_id, client_id, company_id, engagement_id, job_id,
                                    name, deadline_type, filing_body, service_code,
                                    period_start, period_end, due_date, warning_date, status)
      SELECT p_org, p_client_id, p_company_id, p_engagement_id, v_job_id,
             'Corporation Tax Payment - ' || COALESCE(p_period_label,''),
             'statutory', 'HMRC', 'corporation_tax_payment',
             p_period_start, p_period_end,
             public.calculate_deadline('corporation_tax_payment', p_period_start, p_period_end, '{}'::jsonb),
             public.calculate_deadline('corporation_tax_payment', p_period_start, p_period_end, '{}'::jsonb) - INTERVAL '30 days',
             'pending'
      WHERE NOT EXISTS (
        SELECT 1 FROM public.deadlines
        WHERE job_id = v_job_id AND service_code = 'corporation_tax_payment'
      );
    END IF;
  END IF;

  RETURN v_job_id;
END;
$function$;

-- public.link_onboarding_documents_on_approval() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6510a23dcae965cbcd230c852b855b9a (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.link_onboarding_documents_on_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'approved'
     AND (TG_OP = 'INSERT'
          OR OLD.status IS DISTINCT FROM NEW.status
          OR OLD.client_id  IS DISTINCT FROM NEW.client_id
          OR OLD.company_id IS DISTINCT FROM NEW.company_id) THEN
    UPDATE public.onboarding_documents
       SET client_id  = NEW.client_id,
           company_id = NEW.company_id
     WHERE application_id = NEW.id
       AND (client_id  IS DISTINCT FROM NEW.client_id
         OR company_id IS DISTINCT FROM NEW.company_id);
  END IF;
  RETURN NEW;
END;
$function$;

-- public.link_person_to_sa_client(p_person_id uuid, p_client_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=55e562d62e96d0e197cf8cb5a8877560 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.link_person_to_sa_client(p_person_id uuid, p_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_organization_id uuid;
  v_client_org_id uuid;
BEGIN
  SELECT organization_id INTO v_organization_id
  FROM public.company_persons WHERE id = p_person_id;

  IF v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Person not found: %', p_person_id;
  END IF;

  IF NOT public.user_has_organization_access(v_organization_id) THEN
    RAISE EXCEPTION 'Access denied to organization';
  END IF;

  SELECT organization_id INTO v_client_org_id
  FROM public.clients WHERE id = p_client_id;

  IF v_client_org_id IS NULL THEN
    RAISE EXCEPTION 'Client not found: %', p_client_id;
  END IF;

  IF v_client_org_id <> v_organization_id THEN
    RAISE EXCEPTION 'Client % belongs to a different organization than person %', p_client_id, p_person_id;
  END IF;

  UPDATE public.company_persons
  SET linked_client_id = p_client_id
  WHERE id = p_person_id;

  RETURN jsonb_build_object(
    'ok', true,
    'person_id', p_person_id,
    'linked_client_id', p_client_id
  );
END;
$function$;

-- public.lock_period(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_lock_date date, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=229f9778d422b5556ad00efbba653c26 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.lock_period(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_lock_date date, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_existing_lock date;
  v_unposted_count int;
  v_lock_id uuid;
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  IF NOT (public.has_organization_role(p_organization_id, 'owner')
       OR public.has_organization_role(p_organization_id, 'admin')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only owners or admins may lock periods');
  END IF;
  IF p_entity_type NOT IN ('client','company') THEN
    RETURN jsonb_build_object('success', false, 'error', 'entity_type must be client or company');
  END IF;

  SELECT count(*) INTO v_unposted_count
  FROM public.journals j
  WHERE j.organization_id = p_organization_id
    AND ((p_entity_type = 'client'  AND j.client_id  = p_entity_id)
      OR (p_entity_type = 'company' AND j.company_id = p_entity_id))
    AND j.journal_date <= p_lock_date
    AND j.status = 'DRAFT';

  IF v_unposted_count > 0 THEN
    RETURN jsonb_build_object('success', false,
      'error', format('%s draft journal(s) on or before %s must be posted or voided first', v_unposted_count, p_lock_date));
  END IF;

  SELECT lock_date INTO v_existing_lock FROM public.period_locks
  WHERE organization_id = p_organization_id
    AND ((p_entity_type = 'client'  AND client_id  = p_entity_id)
      OR (p_entity_type = 'company' AND company_id = p_entity_id));

  IF v_existing_lock IS NOT NULL AND p_lock_date < v_existing_lock THEN
    RETURN jsonb_build_object('success', false,
      'error', format('Lock date cannot move backwards. Current lock: %s. Use unlock_period first.', v_existing_lock));
  END IF;

  INSERT INTO public.period_locks(organization_id, client_id, company_id, lock_date, locked_by, reason)
  VALUES (p_organization_id,
    CASE WHEN p_entity_type='client'  THEN p_entity_id END,
    CASE WHEN p_entity_type='company' THEN p_entity_id END,
    p_lock_date, v_user, p_reason)
  ON CONFLICT (organization_id, client_id, company_id)
  DO UPDATE SET lock_date = EXCLUDED.lock_date, locked_by = EXCLUDED.locked_by,
                locked_at = now(), reason = EXCLUDED.reason
  RETURNING id INTO v_lock_id;

  RETURN jsonb_build_object('success', true, 'lock_id', v_lock_id, 'lock_date', p_lock_date);
END; $function$;

-- public.log_onboarding_event(p_application_id uuid, p_event_type text, p_from_status text, p_to_status text, p_actor_kind text, p_metadata jsonb) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=719ff561ca2e591d6b5f994db896f61b (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.log_onboarding_event(p_application_id uuid, p_event_type text, p_from_status text DEFAULT NULL::text, p_to_status text DEFAULT NULL::text, p_actor_kind text DEFAULT 'system'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid;
  v_event_id uuid;
BEGIN
  SELECT organization_id INTO v_org
  FROM onboarding_applications WHERE id = p_application_id;

  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  INSERT INTO onboarding_events (
    organization_id, application_id, event_type, from_status, to_status,
    actor_user_id, actor_kind, metadata
  ) VALUES (
    v_org, p_application_id, p_event_type, p_from_status, p_to_status,
    auth.uid(), p_actor_kind, COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$function$;

-- public.log_portal_bookkeeping_action(_entity_type text, _entity_id uuid, _action text, _details jsonb) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=ac478966cd21919b06eef31991edaf2d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.log_portal_bookkeeping_action(_entity_type text, _entity_id uuid, _action text, _details jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_log_id uuid;
  v_client_id uuid;
  v_company_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF _entity_type NOT IN ('client','company') THEN RAISE EXCEPTION 'bad_entity_type'; END IF;

  IF _entity_type = 'client' THEN v_client_id := _entity_id; ELSE v_company_id := _entity_id; END IF;

  IF NOT public.portal_can_access_bookkeeping(v_client_id, v_company_id) THEN
    RAISE EXCEPTION 'permission_denied';
  END IF;

  IF _entity_type = 'client' THEN
    SELECT organization_id INTO v_org FROM public.clients WHERE id = _entity_id;
  ELSE
    SELECT organization_id INTO v_org FROM public.companies WHERE id = _entity_id;
  END IF;
  IF v_org IS NULL THEN RAISE EXCEPTION 'entity_not_found'; END IF;

  INSERT INTO public.bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, actor_id, actor_role, metadata)
  VALUES (v_org, _entity_type, _entity_id, _action, v_uid, 'portal_client',
          jsonb_build_object('source','portal') || COALESCE(_details, '{}'::jsonb))
  RETURNING id INTO v_log_id;

  RETURN v_log_id;
END
$function$;

-- public.log_portal_bookkeeping_revocation(_organization_id uuid, _client_id uuid, _company_id uuid, _reason text) -> void
--   language=sql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=e2fddffd5c472e1ccfdbd9d9c27258dc (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.log_portal_bookkeeping_revocation(_organization_id uuid, _client_id uuid, _company_id uuid, _reason text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.bookkeeping_audit_log
    (organization_id, entity_type, entity_id, action, reason, actor_id)
  VALUES (
    _organization_id,
    CASE WHEN _client_id IS NOT NULL THEN 'client' ELSE 'company' END,
    COALESCE(_client_id, _company_id),
    'portal_access_revoked',
    COALESCE(_reason, 'Bookkeeping service deactivated'),
    auth.uid()
  );
$function$;

-- public.mark_lead_dormant(p_lead_id uuid, p_reason text) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=5267b2dc71c53e67a7feefb343bb1e53 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.mark_lead_dormant(p_lead_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.leads WHERE id = p_lead_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Lead not found'; END IF;
  IF NOT user_has_organization_access(v_org) THEN RAISE EXCEPTION 'Not authorised'; END IF;
  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
  VALUES (v_org, 'LEAD_DORMANT', 'lead', p_lead_id, jsonb_build_object('reason', p_reason));
END;
$function$;

-- public.mark_lead_lost(p_lead_id uuid, p_reason text) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=50e079a3fcba7074140eb14ab56cc2a5 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.mark_lead_lost(p_lead_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.leads WHERE id = p_lead_id;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Lead not found'; END IF;
  IF NOT user_has_organization_access(v_org) THEN RAISE EXCEPTION 'Not authorised'; END IF;
  UPDATE public.leads SET pipeline_stage = 'lost', lost_at = now(),
                          lost_reason = coalesce(p_reason, lost_reason)
   WHERE id = p_lead_id;
  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
  VALUES (v_org, 'LEAD_LOST', 'lead', p_lead_id, jsonb_build_object('reason', p_reason));
END;
$function$;

-- public.mcp_cron_job_health(p_window_minutes integer) -> jsonb
--   language=sql volatility=stable security_definer=True search_path=search_path=public, pg_catalog
--   definition_hash=842fdbdfb675178bc8f38748c1a09437 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.mcp_cron_job_health(p_window_minutes integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.jobname), '[]'::jsonb)
  FROM (
    SELECT
      j.jobname,
      j.schedule,
      j.active,
      count(d.runid)                                                    AS runs,
      count(*) FILTER (WHERE d.status = 'succeeded')                    AS succeeded,
      count(*) FILTER (WHERE d.status IS NOT NULL
                         AND d.status <> 'succeeded')                   AS failed,
      max(d.start_time)                                                 AS last_run_at,
      (ARRAY_AGG(d.status ORDER BY d.start_time DESC)
         FILTER (WHERE d.status IS NOT NULL))[1]                        AS last_status,
      public.redact_secrets(
        (ARRAY_AGG(d.return_message ORDER BY d.start_time DESC)
           FILTER (WHERE d.return_message IS NOT NULL))[1]
      )                                                                 AS last_message,
      -- The DEF-018 signature. Surfaced explicitly so a regression is unmistakable
      -- rather than something to be inferred from an error string.
      count(*) FILTER (
        WHERE d.return_message ILIKE '%unrecognized configuration parameter%'
      )                                                                 AS unrecognized_parameter_failures
    FROM cron.job j
    LEFT JOIN cron.job_run_details d
      ON d.jobid = j.jobid
     AND d.start_time > now() - make_interval(mins => greatest(p_window_minutes, 1))
    GROUP BY j.jobname, j.schedule, j.active
  ) t;
$function$;

-- public.mcp_http_delivery_health(p_window_minutes integer) -> jsonb
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public, pg_catalog
--   definition_hash=89d7be377b772794c0bc3164565b1e29 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.mcp_http_delivery_health(p_window_minutes integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  -- pg_net's response relation is internal and has been renamed across versions. Report the
  -- fact rather than raising, so a verifier check fails with a legible reason.
  IF to_regclass('net._http_response') IS NULL THEN
    RETURN jsonb_build_object(
      'available', false,
      'reason', 'net._http_response is not present in this pg_net version; delivery cannot be verified from SQL.'
    );
  END IF;

  EXECUTE format($q$
    SELECT jsonb_build_object(
      'available', true,
      'window_minutes', %1$s,
      'total',        count(*),
      'succeeded_2xx',count(*) FILTER (WHERE status_code BETWEEN 200 AND 299),
      'unauthorized', count(*) FILTER (WHERE status_code IN (401, 403)),
      'client_error', count(*) FILTER (WHERE status_code BETWEEN 400 AND 499),
      'server_error', count(*) FILTER (WHERE status_code BETWEEN 500 AND 599),
      'timed_out',    count(*) FILTER (WHERE timed_out),
      'no_response',  count(*) FILTER (WHERE status_code IS NULL),
      'sample_errors', coalesce((
        SELECT jsonb_agg(jsonb_build_object(
                 'status_code', s.status_code,
                 'created', s.created,
                 'error', public.redact_secrets(s.error_msg)))
        FROM (
          SELECT status_code, created, error_msg
          FROM net._http_response
          WHERE created > now() - make_interval(mins => greatest(%1$s, 1))
            AND (status_code IS NULL OR status_code >= 400)
          ORDER BY created DESC
          LIMIT 5
        ) s), '[]'::jsonb)
    )
    FROM net._http_response
    WHERE created > now() - make_interval(mins => greatest(%1$s, 1))
  $q$, p_window_minutes)
  INTO v_result;

  RETURN v_result;
END;
$function$;

-- public.mcp_list_cron_jobs() -> jsonb
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public, pg_catalog
--   definition_hash=bc644f5be0de03a80d048a91ffe028a5 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.mcp_list_cron_jobs()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  result jsonb;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron')
     AND EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'cron') THEN
    EXECUTE $q$
      SELECT coalesce(jsonb_agg(row_to_json(j) ORDER BY j.jobname), '[]'::jsonb)
      FROM (
        SELECT jobid, schedule, jobname, command, active, database, username
        FROM cron.job
      ) j
    $q$ INTO result;
    RETURN coalesce(result, '[]'::jsonb);
  END IF;
  RETURN '[]'::jsonb;
END;
$function$;

-- public.mcp_list_functions(name_like text, include_source boolean) -> jsonb
--   language=sql volatility=stable security_definer=True search_path=search_path=public, pg_catalog
--   definition_hash=6c0d50a2eaf66d323a998463b98bce51 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.mcp_list_functions(name_like text DEFAULT NULL::text, include_source boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.name), '[]'::jsonb)
  FROM (
    SELECT
      n.nspname                                     AS schema,
      p.proname                                     AS name,
      pg_get_function_identity_arguments(p.oid)     AS arguments,
      pg_get_function_result(p.oid)                 AS return_type,
      l.lanname                                     AS language,
      p.prosecdef                                   AS security_definer,
      CASE p.provolatile WHEN 'i' THEN 'immutable' WHEN 's' THEN 'stable' WHEN 'v' THEN 'volatile' END AS volatility,
      (
        SELECT string_agg(cfg, ', ')
        FROM unnest(coalesce(p.proconfig, ARRAY[]::text[])) AS cfg
        WHERE cfg LIKE 'search_path=%'
      )                                             AS search_path,
      md5(pg_get_functiondef(p.oid))                AS definition_hash,
      CASE WHEN mcp_list_functions.include_source
           THEN pg_get_functiondef(p.oid)
           ELSE NULL END                            AS definition
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    JOIN pg_language  l ON l.oid = p.prolang
    WHERE n.nspname = 'public'
      AND p.prokind = 'f'
      AND (mcp_list_functions.name_like IS NULL
           OR p.proname ILIKE '%' || mcp_list_functions.name_like || '%')
  ) t;
$function$;

-- public.mcp_list_grants(table_name text) -> jsonb
--   language=sql volatility=stable security_definer=True search_path=search_path=public, pg_catalog
--   definition_hash=88ab55848b1b4d0ac885da7a74d1e98e (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.mcp_list_grants(table_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t."table", t.grantee, t.privilege), '[]'::jsonb)
  FROM (
    SELECT
      g.table_schema   AS schema,
      g.table_name     AS "table",
      g.grantee,
      g.privilege_type AS privilege,
      g.is_grantable
    FROM information_schema.role_table_grants g
    WHERE g.table_schema = 'public'
      AND g.grantee IN ('anon','authenticated','service_role','postgres')
      AND (mcp_list_grants.table_name IS NULL OR g.table_name = mcp_list_grants.table_name)
  ) t;
$function$;

-- public.mcp_list_indexes(table_name text) -> jsonb
--   language=sql volatility=stable security_definer=True search_path=search_path=public, pg_catalog
--   definition_hash=07d2c3d2608479777de29ab06f5ce9b0 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.mcp_list_indexes(table_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t."table", t.name), '[]'::jsonb)
  FROM (
    SELECT
      n.nspname                          AS schema,
      c.relname                          AS "table",
      ic.relname                         AS name,
      i.indisunique                      AS is_unique,
      i.indisprimary                     AS is_primary,
      (i.indpred IS NOT NULL)            AS is_partial,
      pg_get_expr(i.indpred, i.indrelid) AS predicate,
      (
        SELECT array_agg(a.attname ORDER BY k.ord)
        FROM unnest(i.indkey) WITH ORDINALITY k(attnum, ord)
        JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum = k.attnum
      )                                  AS columns,
      pg_get_indexdef(i.indexrelid)      AS definition
    FROM pg_index i
    JOIN pg_class    c  ON c.oid  = i.indrelid
    JOIN pg_class    ic ON ic.oid = i.indexrelid
    JOIN pg_namespace n ON n.oid  = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'r'
      AND (mcp_list_indexes.table_name IS NULL OR c.relname = mcp_list_indexes.table_name)
  ) t;
$function$;

-- public.mcp_list_policies(table_name text) -> jsonb
