--   definition_hash=996ea34b73ed38a0c7d7852f5c42e32d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.mcp_list_policies(table_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t."table", t.name), '[]'::jsonb)
  FROM (
    SELECT
      pp.schemaname  AS schema,
      pp.tablename   AS "table",
      pp.policyname  AS name,
      pp.permissive,
