      pp.cmd,
      pp.qual,
      pp.with_check
    FROM pg_policies pp
    WHERE pp.schemaname = 'public'
      AND (mcp_list_policies.table_name IS NULL OR pp.tablename = mcp_list_policies.table_name)
  ) t;
$function$;

-- public.mcp_list_rls_status(table_name text) -> jsonb
--   language=sql volatility=stable security_definer=True search_path=search_path=public, pg_catalog
--   definition_hash=d3f290ab03fcc31af733b866ff5ef00f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.mcp_list_rls_status(table_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t."table"), '[]'::jsonb)
  FROM (
    SELECT
      n.nspname             AS schema,
      c.relname             AS "table",
      c.relrowsecurity      AS rls_enabled,
      c.relforcerowsecurity AS rls_forced
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'r'
      AND (mcp_list_rls_status.table_name IS NULL OR c.relname = mcp_list_rls_status.table_name)
  ) t;
