-- public.protect_engagement_letter_signatures() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=f8389700eea7e2ec93f2dade8a59a53e (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.protect_engagement_letter_signatures()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.signed_at IS NOT NULL AND (
       OLD.signed_at            IS DISTINCT FROM NEW.signed_at OR
       OLD.signature_ip         IS DISTINCT FROM NEW.signature_ip OR
       OLD.signature_user_agent IS DISTINCT FROM NEW.signature_user_agent OR
       OLD.signed_by            IS DISTINCT FROM NEW.signed_by OR
       OLD.signer_name          IS DISTINCT FROM NEW.signer_name OR
       OLD.signer_email         IS DISTINCT FROM NEW.signer_email OR
       OLD.document_content     IS DISTINCT FROM NEW.document_content
  ) THEN
    RAISE EXCEPTION 'Cannot modify signature fields on a signed engagement letter';
  END IF;
  RETURN NEW;
END;
$function$;

-- public.protect_signatory_signature() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=83c84f6a57d745b200021c09bcd95a2e (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.protect_signatory_signature()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.signed_at IS NOT NULL AND (
       OLD.signed_at            IS DISTINCT FROM NEW.signed_at OR
       OLD.signer_name          IS DISTINCT FROM NEW.signer_name OR
       OLD.signer_email         IS DISTINCT FROM NEW.signer_email OR
       OLD.signature_ip         IS DISTINCT FROM NEW.signature_ip OR
       OLD.signature_user_agent IS DISTINCT FROM NEW.signature_user_agent
  ) THEN
    RAISE EXCEPTION 'Cannot modify signature fields on a signed signatory';
  END IF;
  RETURN NEW;
END;
$function$;

-- public.protect_system_vat_codes() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=3a7ed1a3932219b8a8bc60da8a5403d3 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.protect_system_vat_codes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_system THEN
      RAISE EXCEPTION 'System VAT code "%" cannot be deleted', OLD.code
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.is_system AND (
       NEW.code IS DISTINCT FROM OLD.code
       OR NEW.rate IS DISTINCT FROM OLD.rate
       OR NEW.vat_type IS DISTINCT FROM OLD.vat_type
       OR NEW.is_system IS DISTINCT FROM OLD.is_system
    ) THEN
      RAISE EXCEPTION 'System VAT code "%" core fields (code/rate/type/is_system) cannot be modified', OLD.code
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  RETURN NEW;
END;
$function$;

-- public.public_accept_quote_by_token(p_token text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=4199627dad4b3e8d9c9e90f5872d0e72 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_accept_quote_by_token(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tok record;
  v_quote record;
  v_lead record;
  v_org uuid;
  v_canonical boolean;
  v_client_id uuid;
  v_company_id uuid;
  v_partnership_id uuid;
  v_has_individual boolean := false;
  v_has_company boolean := false;
  v_has_partnership boolean := false;
  v_has_cgt boolean := false;
  v_is_mtd boolean := false;
  v_company_name text;
  v_company record;
  v_today date := current_date;
  v_tax_year_start date;
  v_tax_year_end date;
  v_token_uuid uuid;
  v_director record;
  v_sa_first text;
  v_sa_last text;
  v_sa_email text;
  v_sa_phone text;
  v_sa_blocked boolean := false;
BEGIN
  BEGIN
    v_token_uuid := p_token::uuid;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('error','invalid');
  END;

  SELECT * INTO v_tok FROM public.quote_acceptance_tokens WHERE token = v_token_uuid;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;
  IF v_tok.used_at IS NOT NULL THEN RETURN jsonb_build_object('error','used'); END IF;
  IF v_tok.expires_at IS NOT NULL AND v_tok.expires_at < now() THEN
    RETURN jsonb_build_object('error','expired');
  END IF;

  SELECT * INTO v_quote FROM public.quotes WHERE id = v_tok.quote_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;

  IF v_quote.status = 'accepted' THEN
    UPDATE public.quote_acceptance_tokens SET used_at = now() WHERE token = v_token_uuid AND used_at IS NULL;
    RETURN jsonb_build_object('success', true, 'client_id', v_quote.ported_to_client_id, 'company_id', v_quote.ported_to_company_id, 'replay', true);
  END IF;

  IF v_quote.status NOT IN ('draft','sent') THEN
    RETURN jsonb_build_object('error','not_open');
  END IF;

  v_org := v_quote.organization_id;
  v_canonical := public.is_canonical_lifecycle_enabled(v_org);

  SELECT
    bool_or(sc.entity_scope = 'individual') OR bool_or(sc.code IN ('sa_mtd','sa_non_mtd','cgt_60_day')),
    bool_or(sc.entity_scope = 'company'),
    bool_or(sc.entity_scope = 'partnership'),
    bool_or(sc.code = 'sa_mtd'),
    bool_or(sc.code = 'cgt_60_day')
  INTO v_has_individual, v_has_company, v_has_partnership, v_is_mtd, v_has_cgt
  FROM public.quote_lines ql
  JOIN public.services_catalog sc ON sc.id = ql.service_id
  WHERE ql.quote_id = v_quote.id;

  v_has_individual := COALESCE(v_has_individual, false);
  v_has_company := COALESCE(v_has_company, false);
  v_has_partnership := COALESCE(v_has_partnership, false);
  v_has_cgt := COALESCE(v_has_cgt, false);

  IF v_quote.lead_id IS NOT NULL THEN
    SELECT * INTO v_lead FROM public.leads WHERE id = v_quote.lead_id;
  END IF;

  v_client_id := v_quote.client_id;
  v_company_id := v_quote.company_id;

  IF v_has_company AND v_company_id IS NULL AND v_lead.id IS NOT NULL THEN
    v_company_name := COALESCE(
      NULLIF(v_lead.ch_company_profile->>'company_name',''),
      NULLIF(v_lead.ch_company_profile->>'title',''),
      trim(coalesce(v_lead.first_name,'') || ' ' || coalesce(v_lead.last_name,''))
    );

    SELECT id INTO v_company_id FROM public.companies
      WHERE organization_id = v_org AND lower(email) = lower(v_lead.email)
      LIMIT 1;
    IF v_company_id IS NULL THEN
      INSERT INTO public.companies (organization_id, company_name, email, phone, company_number,
                                    ch_company_profile, status, notes)
      VALUES (v_org, v_company_name, v_lead.email, v_lead.phone,
              v_lead.ch_company_profile->>'company_number',
              v_lead.ch_company_profile, 'pending', v_lead.notes)
      RETURNING id INTO v_company_id;

      IF NOT v_canonical THEN
      INSERT INTO public.accountant_client_links (practice_id, company_id, status, initiated_by, activated_at)
      VALUES (v_org, v_company_id, 'active', 'practice', now());
      END IF;
    END IF;
  END IF;

  IF v_has_individual AND v_client_id IS NULL AND v_lead.id IS NOT NULL THEN
    IF v_has_company THEN
      SELECT * INTO v_director FROM public.resolve_company_director(v_company_id, v_quote.lead_id, v_org);
      IF v_director.first_name IS NOT NULL OR v_director.last_name IS NOT NULL THEN
        v_sa_first := v_director.first_name;
        v_sa_last  := v_director.last_name;
        v_sa_email := COALESCE(v_director.email, v_lead.email);
        v_sa_phone := COALESCE(v_director.phone, v_lead.phone);
      ELSE
        v_sa_blocked := true;
        INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
        VALUES (v_org, 'SA_DIRECTOR_DETAILS_REQUIRED', 'company', v_company_id,
                jsonb_build_object(
                  'quote_id', v_quote.id,
                  'lead_id', v_quote.lead_id,
                  'reason', 'no_director_on_file'
                ));
      END IF;
    ELSE
      v_sa_first := v_lead.first_name;
      v_sa_last  := v_lead.last_name;
      v_sa_email := v_lead.email;
      v_sa_phone := v_lead.phone;
    END IF;

    IF NOT v_sa_blocked THEN
      SELECT id INTO v_client_id FROM public.clients
        WHERE organization_id = v_org AND lower(email) = lower(v_sa_email)
          AND client_type IN ('sa_non_mtd','sa_mtd')
        LIMIT 1;
      IF v_client_id IS NULL THEN
        INSERT INTO public.clients (organization_id, first_name, last_name, email, phone, client_type, status, notes)
        VALUES (v_org, v_sa_first, v_sa_last, v_sa_email, v_sa_phone,
                CASE WHEN v_is_mtd THEN 'sa_mtd' ELSE 'sa_non_mtd' END,
                'pending', v_lead.notes)
        RETURNING id INTO v_client_id;

        INSERT INTO public.client_detail_sa (client_id, organization_id, is_mtd)
        VALUES (v_client_id, v_org, v_is_mtd)
        ON CONFLICT DO NOTHING;

        IF NOT v_canonical THEN
        INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
        VALUES (v_org, v_client_id, 'active', 'practice', now());
        END IF;
      END IF;

      IF v_has_cgt THEN
        INSERT INTO public.client_detail_cgt (client_id, organization_id)
        VALUES (v_client_id, v_org)
        ON CONFLICT DO NOTHING;
      END IF;
    END IF;
  END IF;

  IF v_has_partnership AND v_lead.id IS NOT NULL THEN
    SELECT id INTO v_partnership_id FROM public.clients
      WHERE organization_id = v_org AND lower(email) = lower(v_lead.email)
        AND client_type = 'partnership'
      LIMIT 1;
    IF v_partnership_id IS NULL THEN
      INSERT INTO public.clients (organization_id, first_name, last_name, email, phone, client_type, status, notes)
      VALUES (v_org, v_lead.first_name, v_lead.last_name, v_lead.email, v_lead.phone,
              'partnership', 'pending',
              coalesce(v_lead.notes,'') || E'\n[Action required] Partnership second contact required.')
      RETURNING id INTO v_partnership_id;
      INSERT INTO public.client_detail_partnership (client_id, organization_id)
      VALUES (v_partnership_id, v_org) ON CONFLICT DO NOTHING;
      IF NOT v_canonical THEN
      INSERT INTO public.accountant_client_links (practice_id, client_id, status, initiated_by, activated_at)
      VALUES (v_org, v_partnership_id, 'active', 'practice', now());
      END IF;

      INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
      VALUES (v_org, 'PARTNERSHIP_SECOND_CONTACT_REQUIRED', 'client', v_partnership_id,
              jsonb_build_object('quote_id', v_quote.id, 'lead_id', v_lead.id));
    END IF;
    IF v_client_id IS NULL THEN v_client_id := v_partnership_id; END IF;
  END IF;

  IF v_company_id IS NOT NULL THEN
    SELECT * INTO v_company FROM public.companies WHERE id = v_company_id;
  ELSE
    SELECT NULL::uuid AS id,
           NULL::int  AS year_end_month,
           NULL::int  AS year_end_day
    INTO v_company;
  END IF;

  IF EXTRACT(MONTH FROM v_today) > 4
     OR (EXTRACT(MONTH FROM v_today) = 4 AND EXTRACT(DAY FROM v_today) >= 6) THEN
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int, 4, 6);
  ELSE
    v_tax_year_start := make_date(EXTRACT(YEAR FROM v_today)::int - 1, 4, 6);
  END IF;
  v_tax_year_end := v_tax_year_start + INTERVAL '1 year' - INTERVAL '1 day';

  IF NOT v_canonical THEN
    PERFORM public.lifecycle_materialize_jobs(
      v_org, v_client_id, v_company_id, v_partnership_id, v_quote.id,
      'quote_acceptance:' || v_quote.id::text);
  END IF;

  UPDATE public.quotes
     SET status = 'accepted',
         accepted_at = now(),
         sent_at = COALESCE(sent_at, now()),
         client_id = COALESCE(client_id, v_client_id),
         company_id = COALESCE(company_id, v_company_id),
         ported_to_client_id = COALESCE(ported_to_client_id, v_client_id),
         ported_to_company_id = COALESCE(ported_to_company_id, v_company_id),
         ported_at = COALESCE(ported_at, now())
   WHERE id = v_quote.id;

  IF v_quote.lead_id IS NOT NULL THEN
    UPDATE public.leads SET pipeline_stage = 'won', updated_at = now() WHERE id = v_quote.lead_id;
  END IF;

  UPDATE public.quote_acceptance_tokens SET used_at = now() WHERE token = v_token_uuid;

  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
  VALUES (v_org, 'QUOTE_ACCEPTED', 'quote', v_quote.id,
          jsonb_build_object('client_id', v_client_id, 'company_id', v_company_id, 'partnership_id', v_partnership_id));

  RETURN jsonb_build_object('success', true, 'client_id', v_client_id, 'company_id', v_company_id, 'partnership_id', v_partnership_id);
END;
$function$;

-- public.public_complete_billing(p_application_id uuid, p_stripe_session_id text, p_amount numeric, p_access_token text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=872429e23eabf219da977ead2b5c6c8f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_complete_billing(p_application_id uuid, p_stripe_session_id text, p_amount numeric, p_access_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);

  UPDATE public.onboarding_applications
     SET billing_status = 'completed',
         billing_amount = COALESCE(p_amount, billing_amount),
         stripe_checkout_session_id = COALESCE(p_stripe_session_id, stripe_checkout_session_id),
         billing_completed_at = now(),
         status = CASE WHEN status IN ('billing_pending','aml_pending','engagement_pending')
                       THEN 'portal_pending' ELSE status END,
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('status','portal_pending');
END;
$function$;

-- public.public_get_engagement_letter_for_signing(p_token text) -> jsonb
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=025368f99784f805052c6b95b11c6f97 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_get_engagement_letter_for_signing(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid     uuid;
  v_sig      public.engagement_letter_signatories%ROWTYPE;
  v_letter   public.engagement_letters%ROWTYPE;
  v_org_name text;
  v_progress jsonb;
  v_expired  boolean;
BEGIN
  IF p_token IS NULL OR length(trim(p_token)) = 0 THEN
    RETURN jsonb_build_object('found', false, 'error', 'Missing signing token');
  END IF;

  -- A signatory token is a uuid; a letter token is free text. A non-uuid string simply
  -- means "this can only be a letter token".
  BEGIN
    v_uuid := trim(p_token)::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_uuid := NULL;
  END;

  IF v_uuid IS NOT NULL THEN
    SELECT * INTO v_sig
      FROM public.engagement_letter_signatories
     WHERE signature_token = v_uuid;
  END IF;

  IF v_sig.id IS NOT NULL THEN
    SELECT * INTO v_letter FROM public.engagement_letters WHERE id = v_sig.engagement_letter_id;
  ELSE
    SELECT * INTO v_letter FROM public.engagement_letters WHERE signature_token = trim(p_token);
  END IF;

  IF v_letter.id IS NULL THEN
    RETURN jsonb_build_object('found', false,
      'error', 'This engagement letter link is invalid or has expired.');
  END IF;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_org_name
    FROM public.organizations o
    LEFT JOIN public.organization_branding ob ON ob.organization_id = o.id
   WHERE o.id = v_letter.organization_id;

  v_progress := public.el_signature_progress(v_letter.id);
  v_expired  := (v_letter.token_expires_at IS NOT NULL AND v_letter.token_expires_at < now());

  RETURN jsonb_build_object(
    'found', true,
    'firm_name', COALESCE(v_org_name, 'Your Accountant'),
    'letter', jsonb_build_object(
      'id',             v_letter.id,
      'document_content', v_letter.document_content,
      'status',         v_letter.status,
      'signing_rule',   COALESCE(v_letter.signing_rule, 'all'),
      'signed_at',      v_letter.signed_at,
      'expired',        v_expired
    ),
    'signer', CASE WHEN v_sig.id IS NULL THEN NULL ELSE jsonb_build_object(
      'kind',         'signatory',
      'signatory_id', v_sig.id,
      'name',         v_sig.signer_name,
      'email',        v_sig.signer_email,
      'required',     v_sig.required,
      'signed_at',    v_sig.signed_at
    ) END,
    'progress', v_progress,
    'requires_personal_link', (
      v_sig.id IS NULL AND COALESCE((v_progress->>'has_signatories')::boolean, false)
    )
  );
END;
$function$;

-- public.public_get_onboarding(p_application_id uuid, p_access_token text) -> jsonb
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=fb7de739b15157921c9843929c50e0dc (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_get_onboarding(p_application_id uuid, p_access_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app record;
  v_org record;
  v_brand record;
  v_quote record;
  v_docs jsonb;
  v_engagement record;
  v_has_connect boolean;
  v_display_name text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Onboarding application not found' USING ERRCODE='P0002'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);

  SELECT id, name, logo_url, stripe_connect_account_id INTO v_org
    FROM public.organizations WHERE id = v_app.organization_id;
  v_has_connect := v_org.stripe_connect_account_id IS NOT NULL;

  SELECT trading_name, legal_name INTO v_brand
    FROM public.organization_branding WHERE organization_id = v_app.organization_id;

  v_display_name := COALESCE(NULLIF(v_brand.trading_name, ''), NULLIF(v_brand.legal_name, ''), v_org.name);

  SELECT id, quote_number, accepted_snapshot, currency
    INTO v_quote FROM public.quotes WHERE id = v_app.quote_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', id, 'document_type', document_type, 'file_name', file_name,
    'file_path', file_path, 'created_at', created_at
  ) ORDER BY created_at), '[]'::jsonb) INTO v_docs
    FROM public.onboarding_documents WHERE application_id = p_application_id;

  SELECT id, signed_at, sent_at, document_content INTO v_engagement
    FROM public.engagement_letters
   WHERE onboarding_application_id = p_application_id
   ORDER BY created_at DESC LIMIT 1;

  RETURN jsonb_build_object(
    'application', to_jsonb(v_app) - 'access_token' - 'access_token_expires_at',
    'organization', jsonb_build_object(
      'id', v_org.id,
      'name', v_display_name,
      'logo_url', v_org.logo_url,
      'has_stripe_connect', v_has_connect
    ),
    'quote', to_jsonb(v_quote),
    'documents', v_docs,
    'engagement_letter', to_jsonb(v_engagement)
  );
END;
$function$;

-- public.public_get_quote_by_token(p_token uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=a6fd1919e77b2df7428d0b312f3105a7 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_get_quote_by_token(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tok record; v_quote record; v_practice_name text; v_recipient_name text; v_lines jsonb;
  v_onboarding_id uuid;
  v_access_token text;
  v_lead record;
  v_app_type text;
  v_first_name text;
  v_last_name text;
  v_preferred text;
  v_email text;
  v_phone text;
  v_company_name text;
  v_company_number text;
  v_has_company boolean;
  v_snapshot jsonb;
  v_total_now numeric;
  v_total_monthly numeric;
  v_total_annual numeric;
BEGIN
  SELECT * INTO v_tok FROM quote_acceptance_tokens WHERE token = p_token;
  IF v_tok.token IS NULL THEN RETURN jsonb_build_object('error', 'invalid'); END IF;
  IF v_tok.expires_at <= now() THEN RETURN jsonb_build_object('error', 'expired'); END IF;

  SELECT * INTO v_quote FROM quotes WHERE id = v_tok.quote_id;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_practice_name
  FROM organizations o LEFT JOIN organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_quote.organization_id;

  IF v_quote.lead_id IS NOT NULL THEN
    SELECT NULLIF(trim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')), '')
      INTO v_recipient_name FROM leads WHERE id = v_quote.lead_id;
  ELSIF v_quote.client_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(trim(preferred_name), ''),
                    NULLIF(trim(coalesce(first_name,'') || ' ' || coalesce(last_name,'')), ''))
      INTO v_recipient_name FROM clients WHERE id = v_quote.client_id;
  END IF;

  IF v_recipient_name IS NULL AND v_quote.company_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(trim(c.preferred_name), ''),
                    NULLIF(trim(coalesce(c.first_name,'') || ' ' || coalesce(c.last_name,'')), ''))
      INTO v_recipient_name
    FROM clients c
    WHERE c.company_id = v_quote.company_id
    ORDER BY c.created_at ASC LIMIT 1;

    IF v_recipient_name IS NULL THEN
      SELECT company_name INTO v_recipient_name FROM companies WHERE id = v_quote.company_id;
    END IF;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'service_id', ql.service_id,
    'service_code', sc.code,
    'service_name', COALESCE(NULLIF(ql.description_override, ''), sc.name),
    'quantity', ql.quantity, 'unit_price', ql.unit_price,
    'subtotal', ql.subtotal, 'billing_frequency', ql.billing_frequency
  ) ORDER BY ql.line_order, ql.created_at), '[]'::jsonb)
    INTO v_lines
  FROM quote_lines ql JOIN services_catalog sc ON sc.id = ql.service_id
  WHERE ql.quote_id = v_quote.id;

  SELECT id, access_token INTO v_onboarding_id, v_access_token
  FROM onboarding_applications
  WHERE quote_id = v_quote.id
    AND status <> 'cancelled'
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_onboarding_id IS NULL AND v_quote.status = 'accepted' THEN
    IF v_quote.lead_id IS NOT NULL THEN
      SELECT * INTO v_lead FROM leads WHERE id = v_quote.lead_id;
      v_first_name := v_lead.first_name;
      v_last_name := v_lead.last_name;
      v_email := v_lead.email;
      v_phone := v_lead.phone;
    ELSIF v_quote.client_id IS NOT NULL THEN
      SELECT first_name, last_name, email, phone
        INTO v_first_name, v_last_name, v_email, v_phone
        FROM clients WHERE id = v_quote.client_id;
    END IF;

    v_has_company := v_quote.company_id IS NOT NULL;
    IF v_has_company THEN
      SELECT company_name, company_number INTO v_company_name, v_company_number
        FROM companies WHERE id = v_quote.company_id;
    END IF;

    v_app_type := CASE WHEN v_has_company THEN 'company' ELSE 'individual' END;

    INSERT INTO onboarding_applications (
      organization_id, lead_id, quote_id, application_type, status,
      first_name, last_name, email, phone,
      company_name, company_number, client_id, company_id
    ) VALUES (
      v_quote.organization_id, v_quote.lead_id, v_quote.id, v_app_type, 'in_progress',
      v_first_name, v_last_name, v_email, v_phone,
      v_company_name, v_company_number, v_quote.client_id, v_quote.company_id
    )
    RETURNING id, access_token INTO v_onboarding_id, v_access_token;
  END IF;

  IF v_quote.status <> 'accepted' THEN
    v_access_token := NULL;

  ELSIF v_onboarding_id IS NOT NULL AND (v_access_token IS NULL OR v_access_token = '') THEN
    UPDATE onboarding_applications
       SET access_token = public.gen_onboarding_access_token(),
           access_token_expires_at = COALESCE(access_token_expires_at, now() + interval '90 days')
     WHERE id = v_onboarding_id
    RETURNING access_token INTO v_access_token;
  END IF;

  IF v_quote.status = 'accepted' AND (v_quote.accepted_snapshot IS NULL OR v_quote.accepted_snapshot = 'null'::jsonb) THEN
    SELECT
      COALESCE(SUM(CASE WHEN COALESCE(billing_frequency,'one_off') NOT IN ('monthly','annual') THEN COALESCE(subtotal,0) ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN COALESCE(billing_frequency,'one_off') = 'monthly' THEN COALESCE(subtotal,0) ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN COALESCE(billing_frequency,'one_off') = 'annual'  THEN COALESCE(subtotal,0) ELSE 0 END), 0)
      INTO v_total_now, v_total_monthly, v_total_annual
    FROM jsonb_to_recordset(v_lines)
      AS x(subtotal numeric, billing_frequency text);

    v_snapshot := jsonb_build_object(
      'lines', v_lines,
      'currency', COALESCE(v_quote.currency, 'GBP'),
      'quote_number', v_quote.quote_number,
      'accepted_at', COALESCE(v_quote.accepted_at, now()),
      'valid_until', v_quote.valid_until,
      'total_now', v_total_now,
      'total_monthly', v_total_monthly,
      'total_annual', v_total_annual,
      'total_amount', COALESCE(v_quote.total_amount, v_total_now + v_total_monthly + v_total_annual)
    );

    UPDATE quotes SET accepted_snapshot = v_snapshot WHERE id = v_quote.id;
    v_quote.accepted_snapshot := v_snapshot;
  END IF;

  RETURN jsonb_build_object(
    'quote_id', v_quote.id, 'quote_number', v_quote.quote_number, 'status', v_quote.status,
    'currency', v_quote.currency, 'total_amount', v_quote.total_amount,
    'valid_until', v_quote.valid_until, 'sent_at', v_quote.sent_at,
    'accepted_at', v_quote.accepted_at, 'rejected_at', v_quote.rejected_at,
    'notes', v_quote.notes, 'practice_name', v_practice_name,
    'recipient_name', v_recipient_name, 'lines', v_lines,
    'used', v_tok.used_at IS NOT NULL,
    'onboarding_application_id', v_onboarding_id,
    'onboarding_access_token', v_access_token
  );
END;
$function$;

-- public.public_preview_engagement_letter(p_application_id uuid, p_access_token text) -> text
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=62319ab49fe6829a50964735e47b548d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_preview_engagement_letter(p_application_id uuid, p_access_token text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_quote record;
  v_org_name text;
  v_lines text := '';
  v_line jsonb;
  v_client_name text;
  v_preferred text;
  v_currency text;
  v_accepted_at timestamptz;
  v_total_now numeric;
  v_total_monthly numeric;
  v_client_type text;
  v_variant_id uuid;
  v_letter_body text;
  v_rendered text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id;
  IF v_app IS NULL THEN RETURN NULL; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_org_name
  FROM public.organizations o
  LEFT JOIN public.organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_app.organization_id;

  SELECT accepted_snapshot, currency, accepted_at
    INTO v_quote FROM public.quotes WHERE id = v_app.quote_id;

  IF v_app.client_id IS NOT NULL THEN
    SELECT preferred_name INTO v_preferred FROM public.clients WHERE id = v_app.client_id;
  END IF;

  v_client_name := COALESCE(
    NULLIF(trim(v_preferred), ''),
    NULLIF(trim(coalesce(v_app.first_name,'') || ' ' || coalesce(v_app.last_name,'')), ''),
    v_app.company_name
  );
  v_currency := COALESCE(v_quote.currency, 'GBP');
  v_accepted_at := COALESCE((v_quote.accepted_snapshot->>'accepted_at')::timestamptz, v_quote.accepted_at, now());
  v_total_now := COALESCE((v_quote.accepted_snapshot->>'total_now')::numeric, 0);
  v_total_monthly := COALESCE((v_quote.accepted_snapshot->>'total_monthly')::numeric, 0);

  IF v_quote.accepted_snapshot IS NOT NULL THEN
    FOR v_line IN SELECT * FROM jsonb_array_elements(v_quote.accepted_snapshot->'lines') LOOP
      v_lines := v_lines || '<li>' || (v_line->>'service_name') ||
        ' — ' || v_currency || ' ' || (v_line->>'subtotal') ||
        ' (' || COALESCE(v_line->>'billing_frequency','annual') || ')</li>';
    END LOOP;
  END IF;

  v_client_type := CASE WHEN v_app.application_type = 'individual' THEN 'individual' ELSE 'limited_company' END;
  v_variant_id := public.resolve_engagement_letter_variant(
    v_app.organization_id, v_client_type, NULL, NULL, 'recurring'
  );
  IF v_variant_id IS NOT NULL THEN
    SELECT letter_body INTO v_letter_body
      FROM public.engagement_letter_template_variants WHERE id = v_variant_id;
    v_rendered := public.render_engagement_letter_body(
      v_letter_body, v_org_name, v_client_name,
      '<ul>' || v_lines || '</ul>',
      v_currency, v_total_now, v_total_monthly, v_accepted_at
    );
    IF v_rendered IS NOT NULL THEN RETURN v_rendered; END IF;
  END IF;

  RETURN '<h1>Engagement Letter</h1>' ||
    '<p>Between <strong>' || v_org_name || '</strong> ("the Firm") and <strong>' ||
    v_client_name || '</strong> ("the Client").</p>' ||
    '<h2>Scope of Services</h2><ul>' || v_lines || '</ul>' ||
    '<h2>Fees</h2>' ||
    '<p>One-off fees due now total ' || v_currency || ' ' || v_total_now::text || '. ' ||
    'Ongoing monthly fees total ' || v_currency || ' ' || v_total_monthly::text || ' per month.</p>' ||
    '<h2>Confidentiality</h2>' ||
    '<p>The Firm will treat all information received in the course of this engagement as confidential, except where disclosure is required by law or regulatory authority.</p>' ||
    '<h2>Acceptance</h2>' ||
    '<p>By signing below the Client confirms acceptance of the terms above, in respect of the proposal accepted on ' ||
    to_char(v_accepted_at, 'DD Mon YYYY') || '.</p>';
END;
$function$;

-- public.public_record_aml_upload(p_application_id uuid, p_document_type text, p_file_name text, p_file_path text, p_file_size integer, p_mime_type text, p_access_token text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6646365a44a5b0fba2f5ddef91555b63 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_record_aml_upload(p_application_id uuid, p_document_type text, p_file_name text, p_file_path text, p_file_size integer, p_mime_type text, p_access_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_has_id boolean;
  v_has_poa boolean;
  v_next_status text;
BEGIN
  IF p_document_type NOT IN ('id','proof_of_address','incorporation_cert','other') THEN
    RAISE EXCEPTION 'Invalid document type';
  END IF;

  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status IN ('approved','rejected','cancelled') THEN
    RAISE EXCEPTION 'Onboarding is closed';
  END IF;

  INSERT INTO public.onboarding_documents (
    organization_id, application_id, document_type, file_name, file_path, file_size, mime_type
  ) VALUES (
    v_app.organization_id, p_application_id, p_document_type, p_file_name, p_file_path, p_file_size, p_mime_type
  );

  v_has_id := v_app.id_document_uploaded OR p_document_type = 'id';
  v_has_poa := v_app.proof_of_address_uploaded OR p_document_type = 'proof_of_address';

  v_next_status := v_app.status;
  IF v_has_id AND v_has_poa AND v_app.status IN ('engagement_pending','aml_pending') THEN
    v_next_status := 'billing_pending';
  END IF;

  UPDATE public.onboarding_applications
     SET id_document_uploaded = v_has_id,
         proof_of_address_uploaded = v_has_poa,
         additional_documents_uploaded = CASE WHEN p_document_type IN ('incorporation_cert','other')
                                              THEN true ELSE additional_documents_uploaded END,
         aml_submitted_at = COALESCE(aml_submitted_at,
                                     CASE WHEN v_has_id AND v_has_poa THEN now() ELSE NULL END),
         status = v_next_status,
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('status', v_next_status);
END;
$function$;

-- public.public_reject_quote_by_token(p_token text, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=8ce03cf1788fb8a37412366fbddbfbe3 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_reject_quote_by_token(p_token text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tok record;
  v_quote record;
  v_org uuid;
BEGIN
  SELECT * INTO v_tok FROM public.quote_acceptance_tokens WHERE token = p_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;
  IF v_tok.used_at IS NOT NULL THEN RETURN jsonb_build_object('error','used'); END IF;
  IF v_tok.expires_at IS NOT NULL AND v_tok.expires_at < now() THEN
    RETURN jsonb_build_object('error','expired');
  END IF;

  SELECT * INTO v_quote FROM public.quotes WHERE id = v_tok.quote_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','invalid'); END IF;
  IF v_quote.status NOT IN ('draft','sent') THEN RETURN jsonb_build_object('error','not_open'); END IF;

  v_org := v_quote.organization_id;

  UPDATE public.quotes
     SET status = 'rejected',
         rejected_at = now(),
         rejection_reason = COALESCE(NULLIF(p_reason,''), 'Declined by client')
   WHERE id = v_quote.id;

  UPDATE public.quote_acceptance_tokens SET used_at = now() WHERE id = v_tok.id;

  IF v_quote.lead_id IS NOT NULL THEN
    UPDATE public.leads
       SET pipeline_stage = 'lost',
           lost_at = now(),
           lost_reason = COALESCE(NULLIF(p_reason,''), 'Quote declined')
     WHERE id = v_quote.lead_id
       AND pipeline_stage <> 'won';
  END IF;

  INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, metadata)
  VALUES (v_org, 'QUOTE_REJECTED', 'quote', v_quote.id,
          jsonb_build_object('reason', p_reason, 'source','public_token'));

  RETURN jsonb_build_object('success', true);
END;
$function$;

-- public.public_reject_quote_by_token(p_token uuid, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=2a1c55d57405a0d1dcba36194871baf7 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_reject_quote_by_token(p_token uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tok record; v_quote record; v_old_status text;
BEGIN
  SELECT * INTO v_tok FROM quote_acceptance_tokens WHERE token = p_token;
  IF v_tok.token IS NULL THEN RETURN jsonb_build_object('error', 'invalid'); END IF;
  IF v_tok.used_at IS NOT NULL THEN RETURN jsonb_build_object('error', 'already_used'); END IF;
  IF v_tok.expires_at <= now() THEN RETURN jsonb_build_object('error', 'expired'); END IF;

  SELECT * INTO v_quote FROM quotes WHERE id = v_tok.quote_id FOR UPDATE;
  IF v_quote.status NOT IN ('draft','sent') THEN
    RETURN jsonb_build_object('error','invalid_status','status', v_quote.status);
  END IF;
  v_old_status := v_quote.status;

  UPDATE quotes SET status='rejected', rejected_at=now(),
                   rejection_reason=COALESCE(p_reason,'Declined by client')
  WHERE id = v_quote.id;
  UPDATE quote_acceptance_tokens SET used_at=now() WHERE token = p_token;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, old_value, new_value, user_id, metadata)
  VALUES (v_quote.organization_id, 'quote', v_quote.id, 'status_change', v_old_status, 'rejected', NULL,
          jsonb_build_object('source','public_token','reason', p_reason));

  RETURN jsonb_build_object('success', true, 'quote_id', v_quote.id, 'status','rejected');
END;
$function$;

-- public.public_save_onboarding_details(p_application_id uuid, p_access_token text, p_utr text, p_vat_number text, p_paye_reference text, p_personal_details jsonb, p_ch_correction_note text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=f0884d74ab2db2658289c785886c3f23 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_save_onboarding_details(p_application_id uuid, p_access_token text, p_utr text DEFAULT NULL::text, p_vat_number text DEFAULT NULL::text, p_paye_reference text DEFAULT NULL::text, p_personal_details jsonb DEFAULT NULL::jsonb, p_ch_correction_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status IN ('approved','rejected','cancelled') THEN
    RAISE EXCEPTION 'Onboarding is closed';
  END IF;

  UPDATE public.onboarding_applications
     SET utr = COALESCE(p_utr, utr),
         vat_number = COALESCE(p_vat_number, vat_number),
         paye_reference = COALESCE(p_paye_reference, paye_reference),
         personal_details = COALESCE(p_personal_details, personal_details),
         ch_correction_note = COALESCE(p_ch_correction_note, ch_correction_note),
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('ok', true);
END;
$function$;

-- public.public_sign_engagement_letter(p_application_id uuid, p_signature_data jsonb, p_access_token text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6c803c5dc60f01747d75d9a34ca8c8f1 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_sign_engagement_letter(p_application_id uuid, p_signature_data jsonb, p_access_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_quote record;
  v_org_name text;
  v_content text;
  v_letter_id uuid;
  v_lines text := '';
  v_line jsonb;
  v_client_name text;
  v_preferred text;
  v_currency text;
  v_accepted_at timestamptz;
  v_total_now numeric;
  v_total_monthly numeric;
  v_client_type text;
  v_variant_id uuid;
  v_letter_body text;
  v_rendered text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status IN ('approved','rejected','cancelled') THEN
    RAISE EXCEPTION 'Onboarding is closed';
  END IF;

  SELECT COALESCE(NULLIF(ob.trading_name, ''), NULLIF(ob.legal_name, ''), o.name)
    INTO v_org_name
  FROM public.organizations o
  LEFT JOIN public.organization_branding ob ON ob.organization_id = o.id
  WHERE o.id = v_app.organization_id;

  SELECT accepted_snapshot, currency, accepted_at
    INTO v_quote FROM public.quotes WHERE id = v_app.quote_id;

  IF v_app.client_id IS NOT NULL THEN
    SELECT preferred_name INTO v_preferred FROM public.clients WHERE id = v_app.client_id;
  END IF;

  v_client_name := COALESCE(
    NULLIF(trim(v_preferred), ''),
    NULLIF(trim(coalesce(v_app.first_name,'') || ' ' || coalesce(v_app.last_name,'')), ''),
    v_app.company_name
  );
  v_currency := COALESCE(v_quote.currency, 'GBP');
  v_accepted_at := COALESCE((v_quote.accepted_snapshot->>'accepted_at')::timestamptz, v_quote.accepted_at, now());
  v_total_now := COALESCE((v_quote.accepted_snapshot->>'total_now')::numeric, 0);
  v_total_monthly := COALESCE((v_quote.accepted_snapshot->>'total_monthly')::numeric, 0);

  IF v_quote.accepted_snapshot IS NOT NULL THEN
    FOR v_line IN SELECT * FROM jsonb_array_elements(v_quote.accepted_snapshot->'lines') LOOP
      v_lines := v_lines || '<li>' || (v_line->>'service_name') ||
        ' — ' || v_currency || ' ' || (v_line->>'subtotal') ||
        ' (' || COALESCE(v_line->>'billing_frequency','annual') || ')</li>';
    END LOOP;
  END IF;

  v_client_type := CASE WHEN v_app.application_type = 'individual' THEN 'individual' ELSE 'limited_company' END;
  v_variant_id := public.resolve_engagement_letter_variant(
    v_app.organization_id, v_client_type, NULL, NULL, 'recurring'
  );
  IF v_variant_id IS NOT NULL THEN
    SELECT letter_body INTO v_letter_body
      FROM public.engagement_letter_template_variants WHERE id = v_variant_id;
    v_rendered := public.render_engagement_letter_body(
      v_letter_body, v_org_name, v_client_name,
      '<ul>' || v_lines || '</ul>',
      v_currency, v_total_now, v_total_monthly, v_accepted_at
    );
  END IF;

  v_content := COALESCE(
    v_rendered,
    '<h1>Engagement Letter</h1>' ||
    '<p>Between <strong>' || v_org_name || '</strong> ("the Firm") and <strong>' ||
    v_client_name || '</strong> ("the Client").</p>' ||
    '<h2>Scope of Services</h2><ul>' || v_lines || '</ul>' ||
    '<h2>Fees</h2><p>Total commercial terms as per accepted proposal dated ' ||
    to_char(v_accepted_at, 'DD Mon YYYY') || '.</p>' ||
    '<h2>Acceptance</h2><p>By signing below the Client confirms acceptance of the terms above.</p>'
  );

  SELECT id INTO v_letter_id FROM public.engagement_letters
   WHERE onboarding_application_id = p_application_id ORDER BY created_at DESC LIMIT 1;

  IF v_letter_id IS NULL THEN
    INSERT INTO public.engagement_letters (
      organization_id, onboarding_application_id, document_content,
      sent_at, signed_at, signature_ip, signature_user_agent
    ) VALUES (
      v_app.organization_id, p_application_id, v_content,
      now(), now(),
      p_signature_data->>'ip', p_signature_data->>'user_agent'
    ) RETURNING id INTO v_letter_id;
  ELSE
    UPDATE public.engagement_letters
       SET document_content = v_content,
           signed_at = now(),
           sent_at = COALESCE(sent_at, now()),
           signature_ip = COALESCE(signature_ip, p_signature_data->>'ip'),
           signature_user_agent = COALESCE(signature_user_agent, p_signature_data->>'user_agent'),
           updated_at = now()
     WHERE id = v_letter_id;
  END IF;

  UPDATE public.onboarding_applications
     SET status = 'aml_pending',
         contracts_signed_at = now(),
         contracts_sent_at = COALESCE(contracts_sent_at, now()),
         signature_data = p_signature_data,
         updated_at = now()
   WHERE id = p_application_id;

  RETURN jsonb_build_object('engagement_letter_id', v_letter_id, 'status','aml_pending');
END;
$function$;

-- public.public_sign_engagement_letter_as_signatory(p_token text, p_signature_data jsonb) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=4bff131a1e593a0e5ac792807cb4da4e (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_sign_engagement_letter_as_signatory(p_token text, p_signature_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uuid       uuid;
  v_sig        public.engagement_letter_signatories%ROWTYPE;
  v_letter     public.engagement_letters%ROWTYPE;
  v_app        public.onboarding_applications%ROWTYPE;
  v_name       text;
  v_progress   jsonb;
  v_satisfied  boolean;
  v_status     text;
BEGIN
  IF p_token IS NULL OR length(trim(p_token)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Missing signing token');
  END IF;

  BEGIN
    v_uuid := trim(p_token)::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END;

  -- Lock signatory then letter then application — always in that order, so two
  -- signatories of the same letter signing at the same moment serialise instead of
  -- deadlocking.
  SELECT * INTO v_sig
    FROM public.engagement_letter_signatories
   WHERE signature_token = v_uuid
   FOR UPDATE;

  IF v_sig.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END IF;

  SELECT * INTO v_letter
    FROM public.engagement_letters
   WHERE id = v_sig.engagement_letter_id
   FOR UPDATE;

  IF v_letter.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END IF;

  -- Idempotent: re-opening the emailed link and signing again is a no-op success, never
  -- a second signature.
  IF v_sig.signed_at IS NOT NULL THEN
    v_progress := public.el_signature_progress(v_letter.id);
    RETURN jsonb_build_object(
      'success', true, 'already_signed', true, 'signed_at', v_sig.signed_at,
      'all_signed', COALESCE((v_progress->>'satisfied')::boolean, false),
      'progress', v_progress, 'letter_status', v_letter.status
    );
  END IF;

  IF v_letter.token_expires_at IS NOT NULL AND v_letter.token_expires_at < now() THEN
    RETURN jsonb_build_object('success', false,
      'error', 'This signing link has expired. Please ask your accountant to resend it.');
  END IF;

  SELECT * INTO v_app
    FROM public.onboarding_applications
   WHERE id = COALESCE(v_sig.onboarding_application_id, v_letter.onboarding_application_id)
   FOR UPDATE;

  IF v_app.id IS NOT NULL AND v_app.status IN ('approved','rejected','cancelled') THEN
    RETURN jsonb_build_object('success', false,
      'error', 'This engagement is no longer open for signature. Please contact your accountant.');
  END IF;

  v_name := COALESCE(NULLIF(trim(p_signature_data->>'full_name'), ''), v_sig.signer_name);

  UPDATE public.engagement_letter_signatories
     SET signed_at            = now(),
         signer_name          = v_name,
         signature_ip         = p_signature_data->>'ip',
         signature_user_agent = p_signature_data->>'user_agent'
   WHERE id = v_sig.id;

  -- The rule lives in ONE place (T2d-1) — the same function the activation gate calls.
  v_progress  := public.el_signature_progress(v_letter.id);
  v_satisfied := COALESCE((v_progress->>'satisfied')::boolean, false);

  IF v_satisfied THEN
    UPDATE public.engagement_letters
       SET signed_at            = COALESCE(signed_at, now()),
           status               = 'signed',
           signature_name       = COALESCE(signature_name, v_name),
           signature_ip         = COALESCE(signature_ip, p_signature_data->>'ip'),
           signature_user_agent = COALESCE(signature_user_agent, p_signature_data->>'user_agent'),
           viewed_at            = COALESCE(viewed_at, now()),
           updated_at           = now()
     WHERE id = v_letter.id;

    -- The application-side write the emailed-link path has always been missing.
    IF v_app.id IS NOT NULL THEN
      UPDATE public.onboarding_applications
         SET contracts_signed_at = COALESCE(contracts_signed_at, now()),
             contracts_sent_at   = COALESCE(contracts_sent_at, now()),
             signature_data      = COALESCE(signature_data, p_signature_data),
             status = CASE
               WHEN status IN ('draft','in_progress','engagement_pending') THEN 'aml_pending'
               ELSE status
             END,
             updated_at = now()
       WHERE id = v_app.id;
    END IF;
  ELSE
    UPDATE public.engagement_letters
       SET status     = CASE WHEN status = 'signed' THEN 'signed' ELSE 'partially_signed' END,
           viewed_at  = COALESCE(viewed_at, now()),
           updated_at = now()
     WHERE id = v_letter.id;
  END IF;

  SELECT status INTO v_status FROM public.engagement_letters WHERE id = v_letter.id;

  RETURN jsonb_build_object(
    'success', true, 'signed_at', now(), 'all_signed', v_satisfied,
    'progress', v_progress, 'letter_status', v_status
  );
END;
$function$;

-- public.public_sign_engagement_letter_by_token(p_signature_token text, p_signature_data jsonb) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=8a6b7d2df1f224cc86006483ca66329d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_sign_engagement_letter_by_token(p_signature_token text, p_signature_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_letter   record;
  v_progress jsonb;
BEGIN
  IF p_signature_token IS NULL OR length(trim(p_signature_token)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Missing signing token');
  END IF;

  SELECT * INTO v_letter
    FROM public.engagement_letters
   WHERE signature_token = p_signature_token
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link is not valid.');
  END IF;

  IF v_letter.token_expires_at IS NOT NULL AND v_letter.token_expires_at < now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'This signing link has expired. Please ask your accountant to resend it.');
  END IF;

  IF v_letter.signed_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'already_signed', true, 'signed_at', v_letter.signed_at);
  END IF;

  -- T2d-2 (1): per-signatory letters must be signed through each signatory's own link.
  v_progress := public.el_signature_progress(v_letter.id);
  IF COALESCE((v_progress->>'has_signatories')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'requires_personal_link', true,
      'error', 'This engagement letter is signed by each signatory using the personal link emailed to them. Please use your own link, or ask your accountant to resend it.');
  END IF;

  UPDATE public.engagement_letters
     SET signed_at = now(),
         signature_name = COALESCE(signature_name, NULLIF(trim(p_signature_data->>'full_name'), '')),
         signature_user_agent = COALESCE(signature_user_agent, p_signature_data->>'user_agent'),
         viewed_at = COALESCE(viewed_at, now())
   WHERE id = v_letter.id;

  -- T2d-2 (2): the application-side write this path always omitted.
  UPDATE public.engagement_letters
     SET status = 'signed', updated_at = now()
   WHERE id = v_letter.id;

  UPDATE public.onboarding_applications
     SET contracts_signed_at = COALESCE(contracts_signed_at, now()),
         contracts_sent_at   = COALESCE(contracts_sent_at, now()),
         signature_data      = COALESCE(signature_data, p_signature_data),
         status = CASE
           WHEN status IN ('draft','in_progress','engagement_pending') THEN 'aml_pending'
           ELSE status
         END,
         updated_at = now()
   WHERE id = v_letter.onboarding_application_id
     AND status NOT IN ('approved','rejected','cancelled');

  RETURN jsonb_build_object('success', true, 'signed_at', now());
END;
$function$;

-- public.public_skip_billing(p_application_id uuid, p_access_token text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=64902ddf02bfd9e30633243639d6de13 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_skip_billing(p_application_id uuid, p_access_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  UPDATE public.onboarding_applications
     SET billing_status = 'skipped',
         status = CASE WHEN status IN ('billing_pending','aml_pending','engagement_pending')
                       THEN 'portal_pending' ELSE status END,
         updated_at = now()
   WHERE id = p_application_id
     AND status NOT IN ('approved','rejected','cancelled');
  RETURN jsonb_build_object('status','portal_pending');
END;
$function$;

-- public.public_submit_onboarding_for_review(p_application_id uuid, p_portal_email text, p_access_token text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=16eb330c06c28fb3732b0bf90172aa64 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.public_submit_onboarding_for_review(p_application_id uuid, p_portal_email text, p_access_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_app public.onboarding_applications%ROWTYPE;
  v_org_name text;
  v_member record;
  v_client_name text;
BEGIN
  SELECT * INTO v_app FROM public.onboarding_applications WHERE id = p_application_id FOR UPDATE;
  IF v_app IS NULL THEN RAISE EXCEPTION 'Application not found'; END IF;
  PERFORM public.lifecycle_require_onboarding_token(p_application_id, p_access_token);
  IF v_app.status = 'for_review' THEN
    RETURN jsonb_build_object('status','for_review','already', true);
  END IF;

  UPDATE public.onboarding_applications
     SET status = 'for_review',
         portal_email = COALESCE(p_portal_email, portal_email),
         submitted_for_review_at = now(),
         updated_at = now()
   WHERE id = p_application_id;

  SELECT name INTO v_org_name FROM public.organizations WHERE id = v_app.organization_id;
  v_client_name := COALESCE(v_app.company_name,
    NULLIF(trim(coalesce(v_app.first_name,'') || ' ' || coalesce(v_app.last_name,'')), ''),
    v_app.email, 'New onboarding');

  FOR v_member IN
    SELECT user_id FROM public.organization_users WHERE organization_id = v_app.organization_id
  LOOP
    INSERT INTO public.notifications (
      organization_id, user_id, type, title, message, entity_type, entity_id
    ) VALUES (
      v_app.organization_id, v_member.user_id, 'onboarding_for_review',
      'New onboarding ready for review',
      v_client_name || ' has completed onboarding and is ready for review.',
      'onboarding_application', p_application_id
    );
  END LOOP;

  INSERT INTO public.email_queue (
    organization_id, to_email, to_name, subject, body_html, status, context, entity_type, entity_id
  )
  SELECT v_app.organization_id,
         u.email,
         COALESCE(u.raw_user_meta_data->>'full_name', u.email),
         'Onboarding ready for review: ' || v_client_name,
         '<p>' || v_client_name || ' has completed the onboarding wizard.</p>' ||
         '<p>Please review in AccountancyOS.</p>',
         'pending', 'onboarding', 'onboarding_application', p_application_id
    FROM public.organization_users om
    JOIN auth.users u ON u.id = om.user_id
   WHERE om.organization_id = v_app.organization_id
     AND om.role = 'owner'
     AND u.email IS NOT NULL;

  RETURN jsonb_build_object('status','for_review','already', false);
END;
$function$;

-- public.queue_email_safe(p_organization_id uuid, p_to_email text, p_to_name text, p_subject text, p_body_html text, p_template_id uuid, p_merge_data jsonb, p_scheduled_at timestamp with time zone, p_entity_type text, p_entity_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=0315b118c32579219c4c13b0a1845d3b (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.queue_email_safe(p_organization_id uuid, p_to_email text, p_to_name text DEFAULT NULL::text, p_subject text DEFAULT NULL::text, p_body_html text DEFAULT NULL::text, p_template_id uuid DEFAULT NULL::uuid, p_merge_data jsonb DEFAULT '{}'::jsonb, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_email_id uuid;
  v_status text;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  IF NOT public.user_in_organization(v_user_id, p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- Draft if no scheduled_at, queued otherwise
  v_status := CASE WHEN p_scheduled_at IS NULL THEN 'draft' ELSE 'queued' END;

  INSERT INTO email_queue (
    organization_id, to_email, to_name, subject, body_html, template_id,
    merge_data, scheduled_at, status, entity_type, entity_id, created_by
  ) VALUES (
    p_organization_id, p_to_email, p_to_name, p_subject, p_body_html, p_template_id,
    p_merge_data, p_scheduled_at, v_status, p_entity_type, p_entity_id, v_user_id
  ) RETURNING id INTO v_email_id;

  INSERT INTO audit_log (organization_id, user_id, entity_type, entity_id, action, after_state)
  VALUES (p_organization_id, v_user_id, 'email', v_email_id, 'queued',
    jsonb_build_object('status', v_status, 'to_email', p_to_email));

  RETURN jsonb_build_object('success', true, 'email_id', v_email_id, 'status', v_status);
END;
$function$;

-- public.queue_filing_for_submission(p_filing_id uuid, p_filing_type text, p_user_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=de24e5137dc73e9633f39f2f38a77434 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.queue_filing_for_submission(p_filing_id uuid, p_filing_type text, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_validation JSONB;
  v_filing RECORD;
  v_snapshot_hash TEXT;
  v_idempotency_key TEXT;
  v_queue_id UUID;
  v_existing_queue RECORD;
BEGIN
  -- Validate first
  v_validation := public.validate_filing_submission(p_filing_id, p_filing_type, p_user_id);
  
  IF NOT (v_validation->>'valid')::boolean THEN
    RETURN v_validation;
  END IF;
  
  -- Get filing and snapshot hash
  SELECT * INTO v_filing FROM public.filings WHERE id = p_filing_id;
  
  IF p_filing_type = 'ACCOUNTS_CH' THEN
    SELECT snapshot_hash INTO v_snapshot_hash 
    FROM public.accounts_model_snapshots WHERE id = v_filing.accounts_snapshot_id;
  ELSE
    SELECT snapshot_hash INTO v_snapshot_hash 
    FROM public.ct_computation_snapshots WHERE id = v_filing.ct_snapshot_id;
  END IF;
  
  -- Generate idempotency key
  v_idempotency_key := v_filing.organization_id || ':' || p_filing_type || ':' || 
    COALESCE(v_filing.company_id::text, v_filing.client_id::text) || ':' ||
    v_filing.period_start || ':' || v_filing.period_end || ':' || v_snapshot_hash;
  
  -- Check for existing queue entry
  SELECT * INTO v_existing_queue 
  FROM public.filing_queue 
  WHERE idempotency_key = v_idempotency_key AND status NOT IN ('failed', 'cancelled');
  
  IF v_existing_queue.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'valid', false,
      'errors', ARRAY['Filing already queued or submitted with this snapshot'],
      'existing_queue_id', v_existing_queue.id
    );
  END IF;
  
  -- Insert queue entry
  INSERT INTO public.filing_queue (
    organization_id, filing_id, filing_type, idempotency_key, snapshot_hash, 
    approval_id, status
  )
  VALUES (
    v_filing.organization_id, p_filing_id, p_filing_type, v_idempotency_key, 
    v_snapshot_hash, (v_validation->>'approval_id')::uuid, 'queued'
  )
  RETURNING id INTO v_queue_id;
  
  -- Update filing status
  UPDATE public.filings SET status = 'queued' WHERE id = p_filing_id;
  
  RETURN jsonb_build_object(
    'valid', true,
    'queue_id', v_queue_id,
    'idempotency_key', v_idempotency_key
  );
END;
$function$;

-- public.quote_acceptance_tokens_backfill_org() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=d93d9e14c2a9e80c0e0224ff09931f1f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.quote_acceptance_tokens_backfill_org()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.organization_id IS NULL AND NEW.quote_id IS NOT NULL THEN
    SELECT organization_id INTO NEW.organization_id FROM public.quotes WHERE id = NEW.quote_id;
  END IF;
  RETURN NEW;
END;
$function$;

-- public.quote_lines_stamp_canonical_code() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=affe213bc57acc8521a47ca77d2c5a75 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.quote_lines_stamp_canonical_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_canonical TEXT;
BEGIN
  IF NEW.service_id IS NOT NULL THEN
    SELECT canonical_service_code
      INTO v_canonical
      FROM public.services_catalog
     WHERE id = NEW.service_id;

    -- Always sync to whatever the catalogue row says (including NULL for custom services)
    NEW.canonical_service_code := v_canonical;
  END IF;

  RETURN NEW;
END;
$function$;

-- public.quotes_set_created_by() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=45e43b80cb4f80d47128c9755c9a3c73 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.quotes_set_created_by()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.created_by IS NULL THEN NEW.created_by := auth.uid(); END IF;
  RETURN NEW;
END;
$function$;

-- public.read_email_batch(queue_name text, batch_size integer, vt integer) -> TABLE(msg_id bigint, read_ct integer, message jsonb)
--   language=plpgsql volatility=volatile security_definer=True search_path=(not set)
--   definition_hash=5fee21c55dc3930a992c82b934e73167 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.read_email_batch(queue_name text, batch_size integer, vt integer)
 RETURNS TABLE(msg_id bigint, read_ct integer, message jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN QUERY SELECT r.msg_id, r.read_ct, r.message FROM pgmq.read(queue_name, vt, batch_size) r;
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN;
END;
$function$;

-- public.recompute_aged_balances(p_organization_id uuid, p_entity_type text, p_entity_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=ee6ba3d6025828d1d46e803906075b18 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.recompute_aged_balances(p_organization_id uuid, p_entity_type text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_inv int := 0; v_bills int := 0;
BEGIN
  IF NOT public.user_has_organization_access(p_organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  IF p_entity_type NOT IN ('client','company') THEN
    RETURN jsonb_build_object('success', false, 'error', 'entity_type must be client or company');
  END IF;

  WITH ip AS (
    SELECT i.id, i.total_amount,
      COALESCE((SELECT SUM(amount) FROM public.invoice_payments WHERE invoice_id = i.id),0)
      + COALESCE((SELECT SUM(amount) FROM public.credit_note_allocations WHERE invoice_id = i.id),0) AS paid
    FROM public.invoices i
    WHERE i.organization_id = p_organization_id
      AND ((p_entity_type='client' AND i.client_id=p_entity_id) OR (p_entity_type='company' AND i.company_id=p_entity_id))
      AND lower(i.status) NOT IN ('voided','draft','cancelled')
  ), upd AS (
    UPDATE public.invoices i SET amount_paid = ip.paid,
      remaining_balance = GREATEST(ip.total_amount - ip.paid, 0),
      status = CASE WHEN ip.paid <= 0 THEN i.status
        WHEN ip.paid >= ip.total_amount - 0.005 THEN 'paid'
        ELSE 'part_paid' END,
      updated_at = now()
    FROM ip WHERE i.id = ip.id RETURNING 1
  ) SELECT count(*) INTO v_inv FROM upd;

  WITH bp AS (
    SELECT b.id, b.total_amount, b.status AS s,
      COALESCE((SELECT SUM(amount) FROM public.bill_payments WHERE bill_id = b.id),0)
      + COALESCE((SELECT SUM(amount) FROM public.credit_note_allocations WHERE bill_id = b.id),0) AS paid
    FROM public.bills b
    WHERE b.organization_id = p_organization_id
      AND ((p_entity_type='client' AND b.client_id=p_entity_id) OR (p_entity_type='company' AND b.company_id=p_entity_id))
      AND lower(b.status) NOT IN ('voided','void','draft','cancelled')
  ), upd2 AS (
    UPDATE public.bills b SET amount_paid = bp.paid,
      remaining_balance = GREATEST(bp.total_amount - bp.paid, 0),
      status = CASE WHEN bp.paid <= 0 THEN b.status
        WHEN bp.paid >= bp.total_amount - 0.005 THEN CASE WHEN bp.s = upper(bp.s) THEN 'PAID' ELSE 'paid' END
        ELSE CASE WHEN bp.s = upper(bp.s) THEN 'PART_PAID' ELSE 'part_paid' END END,
      updated_at = now()
    FROM bp WHERE b.id = bp.id RETURNING 1
  ) SELECT count(*) INTO v_bills FROM upd2;

  RETURN jsonb_build_object('success', true, 'invoices_updated', v_inv, 'bills_updated', v_bills);
END; $function$;

-- public.record_automation_audit(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_action text, p_before jsonb, p_after jsonb, p_metadata jsonb) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=5d8b749c902ea492ccaa4250e43419cf (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.record_automation_audit(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_action text, p_before jsonb, p_after jsonb, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF NOT user_in_organization(auth.uid(), p_org_id) THEN
    RAISE EXCEPTION 'not a member';
  END IF;
  INSERT INTO automation_audit_logs(organization_id, actor_id, entity_type, entity_id, action, before_state, after_state, metadata)
  VALUES (p_org_id, auth.uid(), p_entity_type, p_entity_id, p_action, p_before, p_after, p_metadata)
  RETURNING id INTO v_id;
  RETURN v_id;
END;$function$;

-- public.record_automation_execution(p_organization_id uuid, p_rule_id uuid, p_triggered_by_entity text, p_triggered_by_id uuid, p_execution_hash text, p_status text, p_error_message text, p_action_result jsonb) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=c68769c4a51fbea8a91840318f87fbca (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.record_automation_execution(p_organization_id uuid, p_rule_id uuid, p_triggered_by_entity text, p_triggered_by_id uuid, p_execution_hash text, p_status text, p_error_message text DEFAULT NULL::text, p_action_result jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_execution_id UUID;
BEGIN
  INSERT INTO public.automation_executions (
    organization_id,
    automation_rule_id,
    triggered_by_entity,
    triggered_by_id,
    execution_hash,
    status,
    error_message,
    action_result,
    executed_at
  ) VALUES (
    p_organization_id,
    p_rule_id,
    p_triggered_by_entity,
    p_triggered_by_id,
    p_execution_hash,
    p_status,
    p_error_message,
    p_action_result,
    CASE WHEN p_status IN ('success', 'failed') THEN now() ELSE NULL END
  )
  ON CONFLICT (automation_rule_id, execution_hash) 
  WHERE execution_hash IS NOT NULL
  DO UPDATE SET
    status = EXCLUDED.status,
    error_message = EXCLUDED.error_message,
    action_result = EXCLUDED.action_result,
    executed_at = CASE WHEN EXCLUDED.status IN ('success', 'failed') THEN now() ELSE automation_executions.executed_at END
  RETURNING id INTO v_execution_id;
  
  RETURN v_execution_id;
END;
$function$;

-- public.record_bill_payment(p_bill_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid, p_bank_transaction_id uuid, p_reference text, p_payment_method text, p_user_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=830108c75c572dc60992eb3d1b373ac1 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.record_bill_payment(p_bill_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid DEFAULT NULL::uuid, p_bank_transaction_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_bill RECORD;
  v_entity_type text;
  v_entity_id uuid;
  v_creditors_id uuid;
  v_payment_id uuid;
  v_remaining numeric;
  v_alloc numeric;
  v_over numeric;
  v_is_over boolean;
  v_entries jsonb;
  v_post_result jsonb;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
  v_new_paid numeric;
  v_new_remaining numeric;
  v_new_status text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'invalid_amount', 'error_message', 'Payment amount must be positive');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Bill not found');
  END IF;
  IF NOT v_bill.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_posted', 'error_message', 'Bill must be posted before recording payment');
  END IF;

  v_entity_type := CASE WHEN v_bill.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_bill.client_id, v_bill.company_id);

  v_remaining := COALESCE(v_bill.total_gross,0) - COALESCE(v_bill.amount_paid,0);
  v_is_over := p_amount > v_remaining;
  v_alloc := LEAST(p_amount, v_remaining);
  v_over  := CASE WHEN v_is_over THEN p_amount - v_remaining ELSE 0 END;

  SELECT id INTO v_creditors_id FROM bookkeeping_accounts
   WHERE organization_id = v_bill.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('TRADE_CREDITORS','CREDITOR','PAYABLE','ACCOUNTS_PAYABLE')
   LIMIT 1;
  IF v_creditors_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_control_account', 'error_message', 'Trade Creditors account not found');
  END IF;

  INSERT INTO bill_payments (
    bill_id, amount, payment_date, bank_account_id, bank_transaction_id,
    reference, payment_method, payment_type, unallocated_amount, created_by
  ) VALUES (
    p_bill_id, p_amount, p_payment_date, p_bank_account_id, p_bank_transaction_id,
    p_reference, p_payment_method,
    CASE WHEN v_is_over THEN 'overpayment' ELSE 'normal' END,
    v_over, v_uid
  ) RETURNING id INTO v_payment_id;

  IF p_bank_account_id IS NOT NULL THEN
    v_entries := jsonb_build_array(
      jsonb_build_object(
        'account_id', v_creditors_id,
        'debit', p_amount, 'credit', NULL,
        'description', 'Payment: Bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8))
      ),
      jsonb_build_object(
        'account_id', p_bank_account_id,
        'debit', NULL, 'credit', p_amount,
        'description', 'Payment: Bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8))
      )
    );

    v_post_result := post_to_ledger(
      p_organization_id := v_bill.organization_id,
      p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
      p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
      p_journal_date    := p_payment_date,
      p_reference       := p_reference,
      p_description     := 'PAYMENT posting',
      p_journal_type    := 'SYSTEM',
      p_source_type     := 'PAYMENT',
      p_source_id       := v_payment_id,
      p_currency        := COALESCE(v_bill.currency,'GBP'),
      p_fx_rate         := COALESCE(v_bill.exchange_rate,1.0),
      p_created_by      := v_uid,
      p_entries         := v_entries
    );

    IF NOT (v_post_result->>'success')::boolean THEN
      RAISE EXCEPTION 'Payment posting failed: %', v_post_result->>'error_message'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  v_new_paid := COALESCE(v_bill.amount_paid,0) + v_alloc;
  v_new_remaining := COALESCE(v_bill.total_gross,0) - v_new_paid;
  v_new_status := CASE WHEN v_new_remaining <= 0 THEN 'PAID' ELSE 'PART_PAID' END;

  UPDATE bills
     SET amount_paid = v_new_paid,
         remaining_balance = v_new_remaining,
         status = v_new_status,
         updated_at = now()
   WHERE id = p_bill_id;

  RETURN jsonb_build_object('success', true, 'payment_id', v_payment_id);
END;
$function$;

-- public.record_bill_payment(p_bill_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid, p_bank_transaction_id uuid, p_reference text, p_payment_method text, p_user_id uuid, p_payment_fx_rate numeric) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=5c3ec7d638d60cc912921beb71bcbed6 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.record_bill_payment(p_bill_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid DEFAULT NULL::uuid, p_bank_transaction_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_payment_fx_rate numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_bill RECORD;
  v_entity_type text;
  v_entity_id uuid;
  v_creditors_id uuid;
  v_fx_account_id uuid;
  v_payment_id uuid;
  v_remaining numeric;
  v_alloc numeric;
  v_over numeric;
  v_is_over boolean;
  v_entries jsonb;
  v_post_result jsonb;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
  v_new_paid numeric;
  v_new_remaining numeric;
  v_new_status text;
  v_bill_rate numeric;
  v_payment_rate numeric;
  v_bank_base numeric;
  v_creditors_base numeric;
  v_fx_diff numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'invalid_amount', 'error_message', 'Payment amount must be positive');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Bill not found');
  END IF;
  IF NOT v_bill.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_posted', 'error_message', 'Bill must be posted before recording payment');
  END IF;
  IF NOT (auth.role() = 'service_role'
          OR public.user_in_organization(auth.uid(), v_bill.organization_id)) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_authorized', 'error_message', 'Not authorized for this organization');
  END IF;
  v_uid := CASE WHEN auth.role() = 'service_role' THEN COALESCE(p_user_id, auth.uid()) ELSE auth.uid() END;

  v_entity_type := CASE WHEN v_bill.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_bill.client_id, v_bill.company_id);

  v_remaining := COALESCE(v_bill.total_gross,0) - COALESCE(v_bill.amount_paid,0);
  v_is_over := p_amount > v_remaining;
  v_alloc := LEAST(p_amount, v_remaining);
  v_over  := CASE WHEN v_is_over THEN p_amount - v_remaining ELSE 0 END;

  v_bill_rate := COALESCE(v_bill.exchange_rate, 1.0);
  v_payment_rate := COALESCE(p_payment_fx_rate, v_bill_rate);

  SELECT id INTO v_creditors_id FROM bookkeeping_accounts
   WHERE organization_id = v_bill.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('TRADE_CREDITORS','CREDITOR','PAYABLE','ACCOUNTS_PAYABLE')
   LIMIT 1;
  IF v_creditors_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_control_account', 'error_message', 'Trade Creditors account not found');
  END IF;

  INSERT INTO bill_payments (
    bill_id, amount, payment_date, bank_account_id, bank_transaction_id,
    reference, payment_method, payment_type, unallocated_amount, created_by, exchange_rate
  ) VALUES (
    p_bill_id, p_amount, p_payment_date, p_bank_account_id, p_bank_transaction_id,
    p_reference, p_payment_method,
    CASE WHEN v_is_over THEN 'overpayment' ELSE 'normal' END,
    v_over, v_uid, v_payment_rate
  ) RETURNING id INTO v_payment_id;

  IF p_bank_account_id IS NOT NULL THEN
    v_bank_base      := ROUND(p_amount * v_payment_rate, 2);
    v_creditors_base := ROUND(p_amount * v_bill_rate, 2);
    v_fx_diff        := ROUND(v_creditors_base - v_bank_base, 2);

    v_entries := jsonb_build_array(
      jsonb_build_object(
        'account_id', v_creditors_id,
        'debit', v_creditors_base, 'credit', NULL,
        'description', 'Payment made: Bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8))
      ),
      jsonb_build_object(
        'account_id', p_bank_account_id,
        'debit', NULL, 'credit', v_bank_base,
        'description', 'Payment made: Bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8))
      )
    );

    IF ABS(v_fx_diff) >= 0.01 THEN
      SELECT id INTO v_fx_account_id FROM bookkeeping_accounts
       WHERE organization_id = v_bill.organization_id
         AND ((v_entity_type='client'  AND client_id  = v_entity_id)
           OR (v_entity_type='company' AND company_id = v_entity_id))
         AND is_active = true
         AND account_subtype IN ('FX_GAIN_LOSS','FOREIGN_EXCHANGE','EXCHANGE_GAIN_LOSS')
       LIMIT 1;
      IF v_fx_account_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error_code', 'missing_fx_account',
          'error_message', 'FX Gain/Loss account not found for entity. Please add one with subtype FX_GAIN_LOSS.');
      END IF;

      IF v_fx_diff > 0 THEN
        v_entries := v_entries || jsonb_build_array(jsonb_build_object(
          'account_id', v_fx_account_id,
          'debit', NULL, 'credit', ABS(v_fx_diff),
          'description', 'FX gain on bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8))
        ));
      ELSE
        v_entries := v_entries || jsonb_build_array(jsonb_build_object(
          'account_id', v_fx_account_id,
          'debit', ABS(v_fx_diff), 'credit', NULL,
          'description', 'FX loss on bill ' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8))
        ));
      END IF;
    END IF;

    v_post_result := post_to_ledger(
      p_organization_id := v_bill.organization_id,
      p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
      p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
      p_journal_date    := p_payment_date,
      p_reference       := p_reference,
      p_description     := 'PAYMENT posting',
      p_journal_type    := 'SYSTEM',
      p_source_type     := 'PAYMENT',
      p_source_id       := v_payment_id,
      p_currency        := COALESCE(v_bill.currency,'GBP'),
      p_fx_rate         := 1.0,
      p_created_by      := v_uid,
      p_entries         := v_entries
    );

    IF NOT (v_post_result->>'success')::boolean THEN
      RAISE EXCEPTION 'Payment posting failed: %', v_post_result->>'error_message'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  v_new_paid := COALESCE(v_bill.amount_paid,0) + v_alloc;
  v_new_remaining := COALESCE(v_bill.total_gross,0) - v_new_paid;
  v_new_status := CASE WHEN v_new_remaining <= 0 THEN 'PAID' ELSE 'PART_PAID' END;

  UPDATE bills
     SET amount_paid = v_new_paid,
         remaining_balance = v_new_remaining,
         status = v_new_status,
         updated_at = now()
   WHERE id = p_bill_id;

  RETURN jsonb_build_object('success', true, 'payment_id', v_payment_id,
    'fx_diff_base', COALESCE(v_fx_diff,0));
END;
$function$;

-- public.record_bill_payment_safe(p_bill_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid, p_payment_method text, p_reference text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=292cc437e0a5001e2af9be8e79533dae (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.record_bill_payment_safe(p_bill_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT NULL::text, p_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_bill record;
  v_payment_id uuid;
  v_new_amount_paid numeric;
  v_new_status text;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id;
  IF v_bill.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bill not found');
  END IF;

  IF NOT public.user_in_organization(v_user_id, v_bill.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF v_bill.status NOT IN ('APPROVED', 'AWAITING_PAYMENT', 'PART_PAID') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot record payment on this bill');
  END IF;

  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment amount must be positive');
  END IF;

  INSERT INTO bill_payments (
    bill_id, amount, payment_date, bank_account_id, payment_method, reference, created_by
  ) VALUES (
    p_bill_id, p_amount, p_payment_date, p_bank_account_id, p_payment_method, p_reference, v_user_id
  ) RETURNING id INTO v_payment_id;

  v_new_amount_paid := COALESCE(v_bill.amount_paid, 0) + p_amount;
  v_new_status := CASE
    WHEN v_new_amount_paid >= v_bill.total_gross THEN 'PAID'
    ELSE 'PART_PAID'
  END;

  UPDATE bills SET
    amount_paid = v_new_amount_paid,
    remaining_balance = total_gross - v_new_amount_paid,
    status = v_new_status
  WHERE id = p_bill_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, after_state)
  VALUES (v_bill.organization_id, 'bill_payment', v_payment_id, 'created', v_user_id,
    jsonb_build_object('amount', p_amount, 'bill_id', p_bill_id));

  RETURN jsonb_build_object('success', true, 'payment_id', v_payment_id);
END;
$function$;

-- public.record_invoice_payment(p_invoice_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid, p_bank_transaction_id uuid, p_reference text, p_payment_method text, p_user_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=2b6cb82cb5dc9208348f6a14a71df226 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.record_invoice_payment(p_invoice_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid DEFAULT NULL::uuid, p_bank_transaction_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice RECORD;
  v_entity_type text;
  v_entity_id uuid;
  v_debtors_id uuid;
  v_payment_id uuid;
  v_remaining numeric;
  v_alloc numeric;
  v_over numeric;
  v_is_over boolean;
  v_entries jsonb;
  v_post_result jsonb;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
  v_new_paid numeric;
  v_new_remaining numeric;
  v_new_status text;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'invalid_amount', 'error_message', 'Payment amount must be positive');
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Invoice not found');
  END IF;
  IF NOT v_invoice.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_posted', 'error_message', 'Invoice must be posted before recording payment');
  END IF;

  v_entity_type := CASE WHEN v_invoice.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_invoice.client_id, v_invoice.company_id);

  v_remaining := COALESCE(v_invoice.total_gross,0) - COALESCE(v_invoice.amount_paid,0);
  v_is_over := p_amount > v_remaining;
  v_alloc := LEAST(p_amount, v_remaining);
  v_over  := CASE WHEN v_is_over THEN p_amount - v_remaining ELSE 0 END;

  SELECT id INTO v_debtors_id FROM bookkeeping_accounts
   WHERE organization_id = v_invoice.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('TRADE_DEBTORS','DEBTOR','RECEIVABLE','ACCOUNTS_RECEIVABLE')
   LIMIT 1;
  IF v_debtors_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_control_account', 'error_message', 'Trade Debtors account not found');
  END IF;

  INSERT INTO invoice_payments (
    invoice_id, amount, payment_date, bank_account_id, bank_transaction_id,
    reference, payment_method, payment_type, unallocated_amount, created_by
  ) VALUES (
    p_invoice_id, p_amount, p_payment_date, p_bank_account_id, p_bank_transaction_id,
    p_reference, p_payment_method,
    CASE WHEN v_is_over THEN 'overpayment' ELSE 'normal' END,
    v_over, v_uid
  ) RETURNING id INTO v_payment_id;

  IF p_bank_account_id IS NOT NULL THEN
    v_entries := jsonb_build_array(
      jsonb_build_object(
        'account_id', p_bank_account_id,
        'debit', p_amount, 'credit', NULL,
        'description', 'Payment received: Invoice ' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8))
      ),
      jsonb_build_object(
        'account_id', v_debtors_id,
        'debit', NULL, 'credit', p_amount,
        'description', 'Payment received: Invoice ' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8))
      )
    );

    v_post_result := post_to_ledger(
      p_organization_id := v_invoice.organization_id,
      p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
      p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
      p_journal_date    := p_payment_date,
      p_reference       := p_reference,
      p_description     := 'PAYMENT posting',
      p_journal_type    := 'SYSTEM',
      p_source_type     := 'PAYMENT',
      p_source_id       := v_payment_id,
      p_currency        := COALESCE(v_invoice.currency,'GBP'),
      p_fx_rate         := COALESCE(v_invoice.exchange_rate,1.0),
      p_created_by      := v_uid,
      p_entries         := v_entries
    );

    IF NOT (v_post_result->>'success')::boolean THEN
      RAISE EXCEPTION 'Payment posting failed: %', v_post_result->>'error_message'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  v_new_paid := COALESCE(v_invoice.amount_paid,0) + v_alloc;
  v_new_remaining := COALESCE(v_invoice.total_gross,0) - v_new_paid;
  v_new_status := CASE WHEN v_new_remaining <= 0 THEN 'PAID' ELSE 'PART_PAID' END;

  UPDATE invoices
     SET amount_paid = v_new_paid,
         remaining_balance = v_new_remaining,
         status = v_new_status,
         updated_at = now()
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object('success', true, 'payment_id', v_payment_id);
END;
$function$;

-- public.record_invoice_payment(p_invoice_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid, p_bank_transaction_id uuid, p_reference text, p_payment_method text, p_user_id uuid, p_payment_fx_rate numeric) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=30af8eb6d062e2ba0db8b6f010567635 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.record_invoice_payment(p_invoice_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid DEFAULT NULL::uuid, p_bank_transaction_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_payment_fx_rate numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice RECORD;
  v_entity_type text;
  v_entity_id uuid;
  v_debtors_id uuid;
  v_fx_account_id uuid;
  v_payment_id uuid;
  v_remaining numeric;
  v_alloc numeric;
  v_over numeric;
  v_is_over boolean;
  v_entries jsonb;
  v_post_result jsonb;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
  v_new_paid numeric;
  v_new_remaining numeric;
  v_new_status text;
  v_invoice_rate numeric;
  v_payment_rate numeric;
  v_bank_base numeric;
  v_debtors_base numeric;
  v_fx_diff numeric;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'invalid_amount', 'error_message', 'Payment amount must be positive');
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Invoice not found');
  END IF;
  IF NOT v_invoice.is_posted THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_posted', 'error_message', 'Invoice must be posted before recording payment');
  END IF;
  IF NOT (auth.role() = 'service_role'
          OR public.user_in_organization(auth.uid(), v_invoice.organization_id)) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_authorized', 'error_message', 'Not authorized for this organization');
  END IF;
  v_uid := CASE WHEN auth.role() = 'service_role' THEN COALESCE(p_user_id, auth.uid()) ELSE auth.uid() END;

  v_entity_type := CASE WHEN v_invoice.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_invoice.client_id, v_invoice.company_id);

  v_remaining := COALESCE(v_invoice.total_gross,0) - COALESCE(v_invoice.amount_paid,0);
  v_is_over := p_amount > v_remaining;
  v_alloc := LEAST(p_amount, v_remaining);
  v_over  := CASE WHEN v_is_over THEN p_amount - v_remaining ELSE 0 END;

  v_invoice_rate := COALESCE(v_invoice.exchange_rate, 1.0);
  v_payment_rate := COALESCE(p_payment_fx_rate, v_invoice_rate);

  SELECT id INTO v_debtors_id FROM bookkeeping_accounts
   WHERE organization_id = v_invoice.organization_id
     AND ((v_entity_type='client'  AND client_id  = v_entity_id)
       OR (v_entity_type='company' AND company_id = v_entity_id))
     AND is_active = true AND is_control_account = true
     AND account_subtype IN ('TRADE_DEBTORS','DEBTOR','RECEIVABLE','ACCOUNTS_RECEIVABLE')
   LIMIT 1;
  IF v_debtors_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'missing_control_account', 'error_message', 'Trade Debtors account not found');
  END IF;

  INSERT INTO invoice_payments (
    invoice_id, amount, payment_date, bank_account_id, bank_transaction_id,
    reference, payment_method, payment_type, unallocated_amount, created_by, exchange_rate
  ) VALUES (
    p_invoice_id, p_amount, p_payment_date, p_bank_account_id, p_bank_transaction_id,
    p_reference, p_payment_method,
    CASE WHEN v_is_over THEN 'overpayment' ELSE 'normal' END,
    v_over, v_uid, v_payment_rate
  ) RETURNING id INTO v_payment_id;

  IF p_bank_account_id IS NOT NULL THEN
    v_bank_base    := ROUND(p_amount * v_payment_rate, 2);
    v_debtors_base := ROUND(p_amount * v_invoice_rate, 2);
    v_fx_diff      := ROUND(v_bank_base - v_debtors_base, 2);

    v_entries := jsonb_build_array(
      jsonb_build_object(
        'account_id', p_bank_account_id,
        'debit', v_bank_base, 'credit', NULL,
        'description', 'Payment received: Invoice ' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8))
      ),
      jsonb_build_object(
        'account_id', v_debtors_id,
        'debit', NULL, 'credit', v_debtors_base,
        'description', 'Payment received: Invoice ' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8))
      )
    );

    IF ABS(v_fx_diff) >= 0.01 THEN
      SELECT id INTO v_fx_account_id FROM bookkeeping_accounts
       WHERE organization_id = v_invoice.organization_id
         AND ((v_entity_type='client'  AND client_id  = v_entity_id)
           OR (v_entity_type='company' AND company_id = v_entity_id))
         AND is_active = true
         AND account_subtype IN ('FX_GAIN_LOSS','FOREIGN_EXCHANGE','EXCHANGE_GAIN_LOSS')
       LIMIT 1;
      IF v_fx_account_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error_code', 'missing_fx_account',
          'error_message', 'FX Gain/Loss account not found for entity. Please add one with subtype FX_GAIN_LOSS.');
      END IF;

      IF v_fx_diff > 0 THEN
        v_entries := v_entries || jsonb_build_array(jsonb_build_object(
          'account_id', v_fx_account_id,
          'debit', NULL, 'credit', ABS(v_fx_diff),
          'description', 'FX gain on invoice ' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8))
        ));
      ELSE
        v_entries := v_entries || jsonb_build_array(jsonb_build_object(
          'account_id', v_fx_account_id,
          'debit', ABS(v_fx_diff), 'credit', NULL,
          'description', 'FX loss on invoice ' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8))
        ));
      END IF;
    END IF;

    v_post_result := post_to_ledger(
      p_organization_id := v_invoice.organization_id,
      p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
      p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
      p_journal_date    := p_payment_date,
      p_reference       := p_reference,
      p_description     := 'PAYMENT posting',
      p_journal_type    := 'SYSTEM',
      p_source_type     := 'PAYMENT',
      p_source_id       := v_payment_id,
      p_currency        := COALESCE(v_invoice.currency,'GBP'),
      p_fx_rate         := 1.0,
      p_created_by      := v_uid,
      p_entries         := v_entries
    );

    IF NOT (v_post_result->>'success')::boolean THEN
      RAISE EXCEPTION 'Payment posting failed: %', v_post_result->>'error_message'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  v_new_paid := COALESCE(v_invoice.amount_paid,0) + v_alloc;
  v_new_remaining := COALESCE(v_invoice.total_gross,0) - v_new_paid;
  v_new_status := CASE WHEN v_new_remaining <= 0 THEN 'PAID' ELSE 'PART_PAID' END;

  UPDATE invoices
     SET amount_paid = v_new_paid,
         remaining_balance = v_new_remaining,
         status = v_new_status,
         updated_at = now()
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object('success', true, 'payment_id', v_payment_id,
    'fx_diff_base', COALESCE(v_fx_diff,0));
END;
$function$;

-- public.record_invoice_payment_safe(p_invoice_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid, p_payment_method text, p_reference text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=8014a7e549a4c86d8aa2930bcaca3b21 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.record_invoice_payment_safe(p_invoice_id uuid, p_amount numeric, p_payment_date date, p_bank_account_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT NULL::text, p_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_invoice record;
  v_res jsonb;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;
  IF NOT public.user_in_organization(v_user_id, v_invoice.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  IF v_invoice.status NOT IN ('AWAITING_PAYMENT', 'PART_PAID') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot record payment for this invoice status');
  END IF;
  v_res := public.record_invoice_payment(
    p_invoice_id, p_amount, p_payment_date, p_bank_account_id, NULL,
    p_reference, p_payment_method, v_user_id);
  IF NOT COALESCE((v_res->>'success')::boolean, false) THEN
    RAISE EXCEPTION 'Could not post payment: %',
      COALESCE(v_res->>'error_message', v_res->>'error', 'posting error')
      USING ERRCODE = 'P0001';
  END IF;
  RETURN jsonb_build_object('success', true, 'payment_id', v_res->>'payment_id');
END;
$function$;

-- public.record_kyc_subject_progress(p_subject_id uuid, p_new_status text, p_notes text) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=3de4640e57dd1fc22e8e2c0546d5499a (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.record_kyc_subject_progress(p_subject_id uuid, p_new_status text, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_pack_id uuid; v_org_id uuid; v_client_id uuid; v_all_done boolean;
BEGIN
  UPDATE public.kyc_pack_subjects
    SET subject_status = p_new_status,
        waiver_reason = CASE WHEN p_new_status = 'waived' THEN p_notes ELSE waiver_reason END
  WHERE id = p_subject_id
  RETURNING kyc_pack_id, organization_id INTO v_pack_id, v_org_id;
  IF v_pack_id IS NULL THEN RAISE EXCEPTION 'Subject not found'; END IF;
  IF NOT user_has_organization_access(v_org_id) THEN RAISE EXCEPTION 'Not authorised'; END IF;

  SELECT bool_and(subject_status IN ('complete','waived')) INTO v_all_done
  FROM public.kyc_pack_subjects WHERE kyc_pack_id = v_pack_id;

  IF v_all_done THEN
    UPDATE public.kyc_packs SET status = 'submitted', submitted_at = now()
    WHERE id = v_pack_id RETURNING client_id INTO v_client_id;
    INSERT INTO public.automation_events (organization_id, event_type, entity_type, entity_id, new_value)
    VALUES (v_org_id, 'KYC_STATUS_CHANGED', 'client', v_client_id,
            jsonb_build_object('kyc_pack_id', v_pack_id, 'status', 'submitted'));
  END IF;
END;
$function$;

-- public.record_vat_filing_approval(_vat_return_id uuid, _snapshot_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6af0f8ef04d34e26abe8b9d59f42623e (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.record_vat_filing_approval(_vat_return_id uuid, _snapshot_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ret record; v_snap record;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  SELECT * INTO v_ret FROM public.vat_returns WHERE id = _vat_return_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'VAT return not found'); END IF;
  IF NOT public.user_in_organization(auth.uid(), v_ret.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  IF v_ret.submitted_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This VAT return has already been submitted');
  END IF;
  SELECT * INTO v_snap FROM public.filing_model_snapshots WHERE id = _snapshot_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Snapshot not found'); END IF;
  IF v_snap.organization_id <> v_ret.organization_id
     OR v_snap.snapshot_type <> 'vat_return'
     OR v_snap.company_id IS DISTINCT FROM v_ret.company_id
     OR v_snap.client_id  IS DISTINCT FROM v_ret.client_id
     OR v_snap.period_start <> v_ret.period_start
     OR v_snap.period_end   <> v_ret.period_end THEN
    RETURN jsonb_build_object('success', false, 'error', 'Snapshot does not match this VAT return');
  END IF;
  IF v_ret.model_snapshot_id = _snapshot_id AND v_ret.filing_approved_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'already_approved', true,
                              'snapshot_id', _snapshot_id, 'snapshot_hash', v_ret.snapshot_hash);
  END IF;
  UPDATE public.vat_returns
     SET model_snapshot_id  = _snapshot_id, snapshot_hash = v_snap.snapshot_hash,
         filing_approved_by = auth.uid(), filing_approved_at = now(), updated_at = now()
   WHERE id = _vat_return_id;
  RETURN jsonb_build_object('success', true, 'snapshot_id', _snapshot_id, 'snapshot_hash', v_snap.snapshot_hash);
END;
$function$;

-- public.redact_secrets(p_text text) -> text
--   language=sql volatility=immutable security_definer=False search_path=search_path=pg_catalog
--   definition_hash=26a62b36a3bb694692f451f199c400df (hash of the ORIGINAL, pre-sanitization body)
--   *** SANITIZED-BODY: placeholders substituted below; this body is NOT executable ***
CREATE OR REPLACE FUNCTION public.redact_secrets(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT CASE
    WHEN p_text IS NULL THEN NULL
    ELSE regexp_replace(
           regexp_replace(p_text, '[JWT-PREFIX][A-Za-z0-9_-]{6,}\.[A-Za-z0-9_-]{6,}\.[A-Za-z0-9_-]*', '[REDACTED-JWT]', 'g'),
           '(?i)(bearer|apikey|api[-_]?key|password|secret)[=: ]+\S+', '\1 [REDACTED]', 'g')
  END
$function$;

-- public.regenerate_ct_snapshot_on_accounts_change() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=2a531c3d3907d6119e469fdd64f9c2c3 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.regenerate_ct_snapshot_on_accounts_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filing RECORD;
BEGIN
  -- Find filings using this accounts snapshot
  FOR v_filing IN 
    SELECT f.* FROM public.filings f
    WHERE f.accounts_snapshot_id = NEW.id
    AND f.filing_type IN ('corporation_tax', 'CT600')
  LOOP
    -- Mark that CT snapshot needs regeneration
    -- The actual regeneration should be triggered by application code
    -- Here we just log the event
    INSERT INTO public.audit_log (
      organization_id,
      entity_type,
      entity_id,
      action,
      metadata
    ) VALUES (
      v_filing.organization_id,
      'filing',
      v_filing.id,
      'ct_snapshot_regeneration_required',
      jsonb_build_object(
        'accounts_snapshot_id', NEW.id,
        'old_hash', OLD.snapshot_hash,
        'new_hash', NEW.snapshot_hash
      )
    );
  END LOOP;
  
  RETURN NEW;
END;
$function$;

-- public.regress_filing_status(p_filing_id uuid, p_reason text) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=2f459b4816f1c8efb53a50939fd2778d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.regress_filing_status(p_filing_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filing RECORD;
BEGIN
  SELECT * INTO v_filing FROM public.filings WHERE id = p_filing_id;
  
  IF v_filing.id IS NULL THEN
    RETURN;
  END IF;
  
  -- Only regress if in a state that can be regressed
  -- Never regress 'filed' or 'accepted' filings (they need amendments)
  IF v_filing.status IN ('approved', 'queued', 'ready_for_approval', 'draft') THEN
    UPDATE public.filings
    SET 
      status = 'ready_for_approval',
      updated_at = now()
    WHERE id = p_filing_id
    AND status NOT IN ('filed', 'accepted', 'submitted');
    
    -- Log audit event
    INSERT INTO public.audit_log (
      organization_id,
      entity_type,
      entity_id,
      action,
      old_value,
      new_value,
      metadata
    ) VALUES (
      v_filing.organization_id,
      'filing',
      p_filing_id,
      'status_regressed',
      v_filing.status,
      'ready_for_approval',
      jsonb_build_object('reason', p_reason, 'system_actor', 'SYSTEM')
    );
  END IF;
END;
$function$;

-- public.reissue_quote(p_quote_id uuid) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=d787e5c39b3067c7b802e96b0378d2e7 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.reissue_quote(p_quote_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_src record;
  v_new_id uuid;
  v_new_number text;
BEGIN
  SELECT * INTO v_src FROM public.quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Quote not found'; END IF;
  IF NOT user_has_organization_access(v_src.organization_id) THEN RAISE EXCEPTION 'Not authorised'; END IF;
  IF v_src.status = 'accepted' THEN RAISE EXCEPTION 'Accepted quotes cannot be re-issued'; END IF;

  v_new_number := public.generate_quote_number(v_src.organization_id);

  INSERT INTO public.quotes
    (organization_id, quote_number, lead_id, client_id, company_id, status,
     total_amount, currency, valid_until, notes, supersedes_quote_id)
  VALUES
    (v_src.organization_id, v_new_number, v_src.lead_id, v_src.client_id, v_src.company_id, 'draft',
     v_src.total_amount, v_src.currency, v_src.valid_until, v_src.notes, v_src.id)
  RETURNING id INTO v_new_id;

  INSERT INTO public.quote_lines
    (organization_id, quote_id, service_id, description_override, quantity, unit_price, subtotal, line_order, billing_frequency)
  SELECT organization_id, v_new_id, service_id, description_override, quantity, unit_price, subtotal, line_order, billing_frequency
    FROM public.quote_lines WHERE quote_id = v_src.id;

  -- Supersede original if still open
  IF v_src.status IN ('draft','sent') THEN
    UPDATE public.quotes SET status = 'superseded' WHERE id = v_src.id;
  END IF;

  -- Invalidate any open acceptance tokens for the original
  UPDATE public.quote_acceptance_tokens
     SET used_at = now()
   WHERE quote_id = v_src.id AND used_at IS NULL;

  RETURN v_new_id;
END;
$function$;

-- public.remove_reconciliation_line(p_line_id uuid) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6e6f76631d8067c1179c193fd6478dd0 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.remove_reconciliation_line(p_line_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec public.reconciliations%ROWTYPE;
  v_txn_id uuid;
BEGIN
  SELECT r.* INTO v_rec
  FROM public.reconciliation_lines rl
  JOIN public.reconciliations r ON r.id = rl.reconciliation_id
  WHERE rl.id = p_line_id FOR UPDATE OF r;

  IF NOT FOUND THEN RAISE EXCEPTION 'Reconciliation line not found'; END IF;
  IF v_rec.status <> 'in_progress' THEN
    RAISE EXCEPTION 'Reconciliation is not in progress (status=%)', v_rec.status;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_rec.organization_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for this organization';
  END IF;

  SELECT bank_transaction_id INTO v_txn_id FROM public.reconciliation_lines WHERE id = p_line_id;
  DELETE FROM public.reconciliation_lines WHERE id = p_line_id;

  -- Restore prior status (matched/posted)
  UPDATE public.bank_transactions
     SET status = CASE
       WHEN matched_ledger_entry_id IS NOT NULL THEN 'MATCHED'
       ELSE 'UNREVIEWED'
     END,
     updated_at = now()
   WHERE id = v_txn_id;
END;
$function$;

-- public.render_engagement_letter_body(p_template text, p_firm_name text, p_client_name text, p_services_list_html text, p_currency text, p_total_one_off numeric, p_total_monthly numeric, p_accepted_at timestamp with time zone) -> text
--   language=plpgsql volatility=immutable security_definer=False search_path=search_path=public
--   definition_hash=dc220b40adc8d6e1858f0570daced093 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.render_engagement_letter_body(p_template text, p_firm_name text, p_client_name text, p_services_list_html text, p_currency text, p_total_one_off numeric, p_total_monthly numeric, p_accepted_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v text;
BEGIN
  IF p_template IS NULL OR length(btrim(p_template)) = 0 THEN
    RETURN NULL;
  END IF;
  v := p_template;
  v := replace(v, '{{firm_name}}',     COALESCE(p_firm_name, ''));
  v := replace(v, '{{firm.name}}',     COALESCE(p_firm_name, ''));
  v := replace(v, '{{client_name}}',   COALESCE(p_client_name, ''));
  v := replace(v, '{{client.name}}',   COALESCE(p_client_name, ''));
  v := replace(v, '{{recipient_name}}',COALESCE(p_client_name, ''));
  v := replace(v, '{{services_list}}', COALESCE(p_services_list_html, ''));
  v := replace(v, '{{currency}}',      COALESCE(p_currency, ''));
  v := replace(v, '{{total_one_off}}', COALESCE(p_total_one_off::text, '0'));
  v := replace(v, '{{total_monthly}}', COALESCE(p_total_monthly::text, '0'));
  v := replace(v, '{{accepted_date}}', to_char(COALESCE(p_accepted_at, now()), 'DD Mon YYYY'));
  v := replace(v, '{{today}}',         to_char(now(), 'DD Mon YYYY'));
  RETURN v;
END;
$function$;

-- public.reopen_bank_reconciliation(p_reconciliation_id uuid, p_reason text) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=b5f6258f1fbdbf118e448b59e9217ec9 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.reopen_bank_reconciliation(p_reconciliation_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec public.reconciliations%ROWTYPE;
BEGIN
  IF p_reason IS NULL OR length(btrim(p_reason)) < 5 THEN
    RAISE EXCEPTION 'A reason (>= 5 chars) is required to reopen a reconciliation';
  END IF;

  SELECT * INTO v_rec FROM public.reconciliations WHERE id = p_reconciliation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reconciliation not found'; END IF;
  IF v_rec.status <> 'completed' THEN
    RAISE EXCEPTION 'Only completed reconciliations can be reopened';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_rec.organization_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized for this organization';
  END IF;

  PERFORM public.assert_no_locked_period_write(
    v_rec.organization_id, v_rec.client_id, v_rec.company_id, v_rec.statement_end_date
  );

  UPDATE public.reconciliations
     SET status = 'in_progress',
         reopened_by = auth.uid(),
         reopened_at = now(),
         reopen_reason = p_reason,
         completed_by = NULL,
         completed_at = NULL,
         updated_at = now()
   WHERE id = p_reconciliation_id;

  -- Revert RECONCILED txns back to MATCHED so they can be re-included
  UPDATE public.bank_transactions bt
     SET status = 'MATCHED', updated_at = now()
   FROM public.reconciliation_lines rl
   WHERE rl.reconciliation_id = p_reconciliation_id
     AND bt.id = rl.bank_transaction_id
     AND bt.status = 'RECONCILED';

  INSERT INTO public.bookkeeping_audit_log (
    organization_id, client_id, company_id, entity_type, entity_id, action, performed_by, metadata
  ) VALUES (
    v_rec.organization_id, v_rec.client_id, v_rec.company_id,
    'reconciliation', p_reconciliation_id, 'reopen_bank_reconciliation', auth.uid(),
    jsonb_build_object('reason', p_reason)
  );

  RETURN p_reconciliation_id;
END;
$function$;

-- public.resolve_company_director(p_company_id uuid, p_lead_id uuid, p_org_id uuid) -> TABLE(first_name text, last_name text, email text, phone text, source text)
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=a354ebabab97b4ddc12a443c9a175d0d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.resolve_company_director(p_company_id uuid, p_lead_id uuid, p_org_id uuid)
 RETURNS TABLE(first_name text, last_name text, email text, phone text, source text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_name text;
  v_contact record;
  v_person record;
  v_officer jsonb;
  v_full_name text;
  v_comma_pos int;
  v_lead record;
BEGIN
  IF p_company_id IS NOT NULL THEN
    SELECT company_name INTO v_company_name FROM public.companies WHERE id = p_company_id;
  END IF;

  IF p_company_id IS NOT NULL THEN
    SELECT * INTO v_contact
    FROM public.contacts
    WHERE company_id = p_company_id
      AND role ILIKE 'director%'
    ORDER BY is_primary DESC NULLS LAST, created_at ASC
    LIMIT 1;

    IF v_contact.id IS NOT NULL AND COALESCE(trim(v_contact.name), '') <> '' THEN
      first_name := split_part(trim(v_contact.name), ' ', 1);
      last_name  := NULLIF(trim(substring(trim(v_contact.name) FROM position(' ' IN trim(v_contact.name) || ' ') + 1)), '');
      email := v_contact.email;
      phone := v_contact.phone;
      source := 'contacts';
      RETURN NEXT;
      RETURN;
    END IF;
  END IF;

  IF p_company_id IS NOT NULL THEN
    SELECT cp.first_name, cp.last_name, cp.email, cp.phone
      INTO v_person
    FROM public.company_officers co
    JOIN public.company_persons cp ON cp.id = co.person_id
    WHERE co.company_id = p_company_id
      AND co.role ILIKE 'director%'
      AND co.resigned_at IS NULL
    ORDER BY co.appointed_at ASC NULLS LAST
    LIMIT 1;

    IF v_person.first_name IS NOT NULL OR v_person.last_name IS NOT NULL THEN
      first_name := v_person.first_name;
      last_name := v_person.last_name;
      email := v_person.email;
      phone := v_person.phone;
      source := 'company_officers';
      RETURN NEXT;
      RETURN;
    END IF;
  END IF;

  IF p_company_id IS NOT NULL THEN
    SELECT officer INTO v_officer
    FROM public.companies c,
         LATERAL jsonb_array_elements(COALESCE(c.ch_company_profile->'officers','[]'::jsonb)) AS officer
    WHERE c.id = p_company_id
      AND lower(COALESCE(officer->>'officer_role','')) LIKE 'director%'
      AND (officer->>'resigned_on') IS NULL
    LIMIT 1;

    IF v_officer IS NOT NULL THEN
      v_full_name := COALESCE(v_officer->>'name', '');
      v_comma_pos := position(',' IN v_full_name);
      IF v_comma_pos > 0 THEN
        last_name := NULLIF(trim(substring(v_full_name FROM 1 FOR v_comma_pos - 1)), '');
        first_name := NULLIF(trim(substring(v_full_name FROM v_comma_pos + 1)), '');
      ELSE
        first_name := split_part(trim(v_full_name), ' ', 1);
        last_name  := NULLIF(trim(substring(trim(v_full_name) FROM position(' ' IN trim(v_full_name) || ' ') + 1)), '');
      END IF;
      IF first_name IS NOT NULL OR last_name IS NOT NULL THEN
        email := NULL;
        phone := NULL;
        source := 'ch_profile';
        RETURN NEXT;
        RETURN;
      END IF;
    END IF;
  END IF;

  IF p_lead_id IS NOT NULL THEN
    SELECT * INTO v_lead FROM public.leads WHERE id = p_lead_id;
    IF v_lead.id IS NOT NULL THEN
      v_full_name := trim(COALESCE(v_lead.first_name,'') || ' ' || COALESCE(v_lead.last_name,''));
      IF v_full_name <> ''
         AND lower(v_full_name) <> lower(COALESCE(v_company_name,''))
         AND lower(COALESCE(v_lead.first_name,'')) <> lower(COALESCE(v_company_name,'')) THEN
        first_name := v_lead.first_name;
        last_name := v_lead.last_name;
        email := v_lead.email;
        phone := v_lead.phone;
        source := 'lead';
        RETURN NEXT;
        RETURN;
      END IF;
    END IF;
  END IF;

  RETURN;
END;
$function$;

-- public.resolve_engagement_letter_variant(p_organization_id uuid, p_client_type text, p_service_code text, p_legal_entity text, p_engagement_kind text) -> uuid
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=88857a6d9206bfe7ecee025ad9056113 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.resolve_engagement_letter_variant(p_organization_id uuid, p_client_type text, p_service_code text, p_legal_entity text, p_engagement_kind text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT id FROM public.engagement_letter_template_variants
  WHERE organization_id = p_organization_id
    AND is_active
    AND engagement_kind = coalesce(p_engagement_kind,'recurring')
    AND (client_type = p_client_type OR client_type IS NULL)
    AND (service_code = p_service_code OR service_code IS NULL)
    AND (legal_entity = p_legal_entity OR legal_entity IS NULL)
  ORDER BY
    (client_type = p_client_type)::int DESC,
    (service_code = p_service_code)::int DESC,
    (legal_entity = p_legal_entity)::int DESC,
    is_default DESC
  LIMIT 1;
$function$;

-- public.resume_automation(p_pause_id uuid) -> boolean
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=ab934f0cd2ab206831c7d920751a8a56 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.resume_automation(p_pause_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM automation_pauses WHERE id = p_pause_id;
  IF v_org IS NULL THEN RETURN false; END IF;
  IF NOT user_in_organization(auth.uid(), v_org) THEN RAISE EXCEPTION 'not a member'; END IF;
  DELETE FROM automation_pauses WHERE id = p_pause_id;
  INSERT INTO automation_audit_logs(organization_id, actor_id, entity_type, entity_id, action)
  VALUES (v_org, auth.uid(), 'automation_pause', p_pause_id, 'resume');
  RETURN true;
END;$function$;

-- public.resume_workflow_instance(p_instance_id uuid) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=ea30edaad69c87abcfef5498fc9335c6 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.resume_workflow_instance(p_instance_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.automation_workflow_instances
     SET status = 'QUEUED', paused_at = NULL, next_run_at = COALESCE(next_run_at, now()), updated_at = now()
   WHERE id = p_instance_id
     AND status = 'PAUSED'
     AND org_id IN (SELECT organization_id FROM organization_users WHERE user_id = auth.uid());
END;
$function$;

-- public.retry_failed_email_safe(p_email_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=2dae8a2d7a65ae6993d0d41af49613ee (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.retry_failed_email_safe(p_email_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_email RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_email FROM email_queue WHERE id = p_email_id;
  IF v_email.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;

  IF NOT user_in_organization(v_user_id, v_email.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF v_email.status != 'failed' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only retry failed emails');
  END IF;

  UPDATE email_queue SET
    status = 'pending',
    retry_count = COALESCE(retry_count, 0) + 1,
    last_error_message = NULL,
    updated_at = now()
  WHERE id = p_email_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (v_email.organization_id, 'email', p_email_id, 'retry_requested', v_user_id);

  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$function$;

-- public.revalue_bank_account_fx(p_bank_account_id uuid, p_revaluation_date date, p_fx_rate_to_base numeric, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=dc88a987a0df1a249661f9068165a667 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.revalue_bank_account_fx(p_bank_account_id uuid, p_revaluation_date date, p_fx_rate_to_base numeric, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_bank record;
  v_org_settings record;
  v_base_currency text;
  v_gl_account_id uuid;
  v_txn_balance numeric := 0;     -- balance in transaction currency
  v_base_balance numeric := 0;    -- current GL balance in base currency
  v_revalued_base numeric;        -- revalued amount in base currency
  v_diff numeric;                 -- gain (>0) or loss (<0)
  v_journal_id uuid;
  v_fx_account uuid;
  v_user_id uuid := auth.uid();
  v_org_id uuid;
BEGIN
  IF p_fx_rate_to_base IS NULL OR p_fx_rate_to_base <= 0 THEN
    RAISE EXCEPTION 'Invalid FX rate' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_bank FROM public.bank_accounts WHERE id = p_bank_account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank account not found';
  END IF;
  v_org_id := v_bank.organization_id;

  -- Org membership
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_org_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'Not a member of this organization';
  END IF;

  -- Period lock guard
  PERFORM public.assert_no_locked_period_write(
    v_org_id, v_bank.client_id, v_bank.company_id, p_revaluation_date
  );

  v_gl_account_id := v_bank.account_id;
  IF v_gl_account_id IS NULL THEN
    RAISE EXCEPTION 'Bank account has no mapped GL account';
  END IF;

  SELECT * INTO v_org_settings FROM public.org_settings WHERE organization_id = v_org_id;
  v_base_currency := COALESCE(v_org_settings.base_currency, 'GBP');

  IF v_bank.currency = v_base_currency THEN
    RAISE EXCEPTION 'Bank account currency matches base currency; no FX revaluation needed';
  END IF;

  -- Aggregate balances on the GL bank account, scoped to entity
  SELECT
    COALESCE(SUM(COALESCE(le.transaction_debit, le.debit) - COALESCE(le.transaction_credit, le.credit)), 0),
    COALESCE(SUM(le.debit - le.credit), 0)
  INTO v_txn_balance, v_base_balance
  FROM public.ledger_entries le
  WHERE le.account_id = v_gl_account_id
    AND le.organization_id = v_org_id
    AND le.transaction_date <= p_revaluation_date
    AND (
      (v_bank.company_id IS NOT NULL AND le.company_id = v_bank.company_id) OR
      (v_bank.client_id IS NOT NULL AND le.client_id = v_bank.client_id)
    );

  v_revalued_base := ROUND(v_txn_balance * p_fx_rate_to_base, 2);
  v_diff := ROUND(v_revalued_base - v_base_balance, 2);

  IF ABS(v_diff) < 0.005 THEN
    RETURN jsonb_build_object(
      'success', true,
      'no_adjustment', true,
      'txn_balance', v_txn_balance,
      'base_balance', v_base_balance,
      'revalued_base', v_revalued_base
    );
  END IF;

  -- Determine FX account: gain if diff > 0, loss if diff < 0
  IF v_diff > 0 THEN
    v_fx_account := v_org_settings.fx_gain_account_id;
  ELSE
    v_fx_account := v_org_settings.fx_loss_account_id;
  END IF;
  IF v_fx_account IS NULL THEN
    RAISE EXCEPTION 'FX gain/loss account not configured in org_settings';
  END IF;

  -- Build journal: adjust bank GL by v_diff (base only, txn amount = 0)
  -- Debit bank / Credit FX gain  (when diff > 0)
  -- Credit bank / Debit FX loss  (when diff < 0)
  INSERT INTO public.journals (
    organization_id, client_id, company_id, journal_date, description,
    source_type, source_id, created_by
  ) VALUES (
    v_org_id, v_bank.client_id, v_bank.company_id, p_revaluation_date,
    COALESCE(p_reason, 'FX revaluation: ' || v_bank.name),
    'FX_REVALUATION', p_bank_account_id, v_user_id
  ) RETURNING id INTO v_journal_id;

  -- Bank leg (base only)
  INSERT INTO public.journal_lines (journal_id, account_id, debit, credit, description)
  VALUES (
    v_journal_id, v_gl_account_id,
    GREATEST(v_diff, 0), GREATEST(-v_diff, 0),
    'FX revaluation adjustment'
  );

  -- FX gain/loss leg
  INSERT INTO public.journal_lines (journal_id, account_id, debit, credit, description)
  VALUES (
    v_journal_id, v_fx_account,
    GREATEST(-v_diff, 0), GREATEST(v_diff, 0),
    'FX revaluation ' || CASE WHEN v_diff > 0 THEN 'gain' ELSE 'loss' END
  );

  -- Post journal to ledger
  PERFORM public.post_to_ledger(v_journal_id);

  -- Audit log
  INSERT INTO public.bookkeeping_audit_log (
    organization_id, client_id, company_id, action, entity_type, entity_id, payload, performed_by
  ) VALUES (
    v_org_id, v_bank.client_id, v_bank.company_id,
    'fx_revaluation', 'bank_account', p_bank_account_id,
    jsonb_build_object(
      'revaluation_date', p_revaluation_date,
      'fx_rate', p_fx_rate_to_base,
      'txn_balance', v_txn_balance,
      'base_balance', v_base_balance,
      'revalued_base', v_revalued_base,
      'adjustment', v_diff,
      'journal_id', v_journal_id,
      'reason', p_reason
    ),
    v_user_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'journal_id', v_journal_id,
    'adjustment', v_diff,
    'txn_balance', v_txn_balance,
    'base_balance_before', v_base_balance,
    'base_balance_after', v_revalued_base
  );
END;
$function$;

-- public.reverse_bill_payment_safe(p_payment_id uuid, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6858414aa45df75a6d6fc4b8460bcb5a (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.reverse_bill_payment_safe(p_payment_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_payment RECORD;
  v_bill RECORD;
  v_org_id UUID;
  v_reversal_id UUID;
  v_new_total_paid NUMERIC;
  v_new_status TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_payment FROM bill_payments WHERE id = p_payment_id;
  IF v_payment.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment not found');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = v_payment.bill_id;
  v_org_id := v_bill.organization_id;

  IF NOT can_approve_bills(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: manager+ required');
  END IF;

  IF v_payment.payment_type = 'reversal' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot reverse a reversal');
  END IF;

  -- Create reversal entry
  INSERT INTO bill_payments (bill_id, amount, payment_date, payment_type, reference, notes, created_by)
  VALUES (v_payment.bill_id, -v_payment.amount, CURRENT_DATE, 'reversal', 'REV-' || v_payment.id, p_reason, v_user_id)
  RETURNING id INTO v_reversal_id;

  SELECT COALESCE(SUM(amount), 0) INTO v_new_total_paid FROM bill_payments WHERE bill_id = v_payment.bill_id;

  -- FIXED: Use APPROVED when no payments remain, not AWAITING_PAYMENT
  IF v_new_total_paid <= 0 THEN
    v_new_status := 'APPROVED';
  ELSIF v_new_total_paid >= v_bill.total_gross THEN
    v_new_status := 'PAID';
  ELSE
    v_new_status := 'PART_PAID';
  END IF;

  UPDATE bills SET
    amount_paid = GREATEST(v_new_total_paid, 0),
    remaining_balance = total_gross - GREATEST(v_new_total_paid, 0),
    status = v_new_status,
    updated_at = now()
  WHERE id = v_payment.bill_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata, actor_role)
  VALUES (v_org_id, 'bill_payment', v_reversal_id, 'payment_reversed', v_user_id,
    jsonb_build_object('original_payment_id', p_payment_id, 'reason', p_reason, 'amount', v_payment.amount, 'new_status', v_new_status),
    (SELECT role FROM organization_users WHERE user_id = v_user_id AND organization_id = v_org_id LIMIT 1));

  RETURN jsonb_build_object('success', true, 'reversal_id', v_reversal_id, 'bill_status', v_new_status);
END;
$function$;

-- public.reverse_invoice_payment_safe(p_payment_id uuid, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=19843e290961da74d31cbee0223f546f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.reverse_invoice_payment_safe(p_payment_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment RECORD;
  v_invoice RECORD;
  v_user_id UUID;
  v_org_id UUID;
  v_new_status TEXT;
  v_new_paid NUMERIC;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  
  IF p_reason IS NULL OR p_reason = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reason is required for payment reversal');
  END IF;

  SELECT * INTO v_payment FROM invoice_payments WHERE id = p_payment_id FOR UPDATE;
  
  IF v_payment.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment not found');
  END IF;
  
  SELECT * INTO v_invoice FROM invoices WHERE id = v_payment.invoice_id FOR UPDATE;
  v_org_id := v_invoice.organization_id;
  
  -- Check permission - manager+ for reversals
  IF NOT user_has_role_at_least(v_user_id, v_org_id, 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: payment reversal requires manager role');
  END IF;
  
  -- Calculate new balances
  v_new_paid := GREATEST(COALESCE(v_invoice.amount_paid, 0) - v_payment.amount, 0);
  
  IF v_new_paid <= 0 THEN
    v_new_status := 'ISSUED';
  ELSIF v_new_paid < v_invoice.total_gross THEN
    v_new_status := 'PART_PAID';
  ELSE
    v_new_status := 'PAID';
  END IF;
  
  -- Instead of deleting, mark as reversed (soft delete pattern)
  UPDATE invoice_payments SET
    payment_type = 'reversed',
    notes = COALESCE(notes, '') || E'\n[REVERSED] ' || p_reason
  WHERE id = p_payment_id;
  
  -- Update invoice
  UPDATE invoices SET
    amount_paid = v_new_paid,
    remaining_balance = v_invoice.total_gross - v_new_paid,
    status = v_new_status,
    updated_at = now()
  WHERE id = v_invoice.id;
  
  -- Write audit log
  PERFORM write_audit_log(
    v_org_id,
    'invoice_payment',
    p_payment_id,
    'reverse',
    'payment_type',
    v_payment.payment_type,
    'reversed',
    to_jsonb(v_payment),
    NULL,
    jsonb_build_object('reason', p_reason, 'invoice_id', v_invoice.id, 'new_status', v_new_status)
  );
  
  RETURN jsonb_build_object('success', true, 'new_invoice_status', v_new_status);
END;
$function$;

-- public.reverse_journal(p_journal_id uuid, p_reversal_date date, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=71cf2ca844763ddf1b32fa006c10c797 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.reverse_journal(p_journal_id uuid, p_reversal_date date, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_original_journal RECORD;
  v_new_journal_id UUID;
  v_is_locked BOOLEAN;
  v_line RECORD;
BEGIN
  SELECT * INTO v_original_journal
  FROM public.journals
  WHERE id = p_journal_id;

  IF v_original_journal IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Journal not found');
  END IF;

  IF v_original_journal.is_reversed THEN
    RETURN jsonb_build_object('success', false, 'error', 'Journal has already been reversed');
  END IF;

  IF NOT (auth.role() = 'service_role'
          OR public.user_in_organization(auth.uid(), v_original_journal.organization_id)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized for this organization');
  END IF;

  v_is_locked := public.is_period_locked(
    v_original_journal.organization_id,
    v_original_journal.client_id,
    v_original_journal.company_id,
    p_reversal_date
  );

  IF v_is_locked THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reversal date is in a locked period');
  END IF;

  v_new_journal_id := gen_random_uuid();

  INSERT INTO public.journals (
    id, organization_id, client_id, company_id, journal_date, reference,
    description, journal_type, status, total_debit, total_credit,
    transaction_currency, fx_rate_to_base, reverses_journal_id, created_by
  ) VALUES (
    v_new_journal_id,
    v_original_journal.organization_id,
    v_original_journal.client_id,
    v_original_journal.company_id,
    p_reversal_date,
    'REV-' || v_original_journal.reference,
    COALESCE(p_reason, 'Reversal of ' || v_original_journal.reference),
    'REVERSING',
    'POSTED',
    v_original_journal.total_credit,
    v_original_journal.total_debit,
    v_original_journal.transaction_currency,
    v_original_journal.fx_rate_to_base,
    p_journal_id,
    auth.uid()
  );

  FOR v_line IN
    SELECT * FROM public.journal_lines WHERE journal_id = p_journal_id
  LOOP
    INSERT INTO public.journal_lines (
      journal_id, account_id, debit, credit, description
    ) VALUES (
      v_new_journal_id,
      v_line.account_id,
      v_line.credit,
      v_line.debit,
      'Reversal: ' || COALESCE(v_line.description, '')
    );
  END LOOP;

  INSERT INTO public.ledger_entries (
    organization_id, client_id, company_id, account_id, entry_date, transaction_date,
    debit, credit, description, reference, journal_id, source_type, source_id,
    transaction_currency, transaction_debit, transaction_credit, fx_rate_to_base, base_currency
  )
  SELECT
    organization_id, client_id, company_id, account_id,
    p_reversal_date, p_reversal_date,
    credit, debit,
    'Reversal: ' || COALESCE(description, ''),
    'REV-' || reference,
    v_new_journal_id,
    source_type, source_id,
    transaction_currency, transaction_credit, transaction_debit,
    fx_rate_to_base, base_currency
  FROM public.ledger_entries
  WHERE journal_id = p_journal_id;

  UPDATE public.journals
  SET is_reversed = TRUE, reversal_date = p_reversal_date
  WHERE id = p_journal_id;

  INSERT INTO public.audit_log (
    organization_id, entity_type, entity_id, action, user_id, old_value, new_value, metadata
  ) VALUES (
    v_original_journal.organization_id,
    'journal',
    p_journal_id,
    'reversed',
    auth.uid(),
    p_journal_id::TEXT,
    v_new_journal_id::TEXT,
    jsonb_build_object(
      'reversal_journal_id', v_new_journal_id,
      'reversal_date', p_reversal_date,
      'reason', p_reason
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'reversal_journal_id', v_new_journal_id,
    'message', 'Journal reversed successfully'
  );
END;
$function$;

-- public.revert_bank_rule_application(p_bank_transaction_id uuid, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=e13cebb630294608894fc7e4d12267d2 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.revert_bank_rule_application(p_bank_transaction_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_txn record;
  v_is_member boolean;
  v_journal_id uuid;
  v_before jsonb;
BEGIN
  IF p_reason IS NULL OR length(trim(p_reason)) < 5 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'reason_required',
                              'error_message', 'A reason of at least 5 characters is required');
  END IF;

  SELECT * INTO v_txn FROM bank_transactions WHERE id = p_bank_transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'transaction_not_found',
                              'error_message', 'Bank transaction not found');
  END IF;

  SELECT user_in_organization(v_actor, v_txn.organization_id) INTO v_is_member;
  IF NOT COALESCE(v_is_member, false) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'forbidden',
                              'error_message', 'Not a member of this organisation');
  END IF;

  IF v_txn.rule_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'no_rule_applied',
                              'error_message', 'Transaction has no rule application to revert');
  END IF;

  IF upper(COALESCE(v_txn.status,'')) = 'RECONCILED' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'reconciled',
                              'error_message', 'Cannot revert a reconciled transaction; reopen the reconciliation first');
  END IF;

  BEGIN
    PERFORM assert_no_locked_period_write(
      v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
    );
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'period_locked',
                              'error_message', SQLERRM);
  END;

  v_before := to_jsonb(v_txn);

  -- If a journal was posted, reverse it via existing helper if available
  SELECT id INTO v_journal_id FROM journals
   WHERE source_type = 'bank_transaction'
     AND source_id = p_bank_transaction_id
     AND COALESCE(is_reversed, false) = false
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_journal_id IS NOT NULL THEN
    BEGIN
      PERFORM reverse_journal(v_journal_id, p_reason);
    EXCEPTION WHEN undefined_function THEN
      UPDATE journals SET is_reversed = true, reversed_at = now(), reversed_by = v_actor,
                          reversal_reason = p_reason
       WHERE id = v_journal_id;
    END;
  END IF;

  UPDATE bank_transactions
     SET status = 'UNREVIEWED',
         rule_id = NULL,
         category = NULL,
         client_suggested_account_id = NULL,
         review_status = NULL
   WHERE id = p_bank_transaction_id;

  INSERT INTO bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id,
    'revert_bank_rule_application', v_actor,
    v_before,
    jsonb_build_object('status','UNREVIEWED'),
    jsonb_build_object('reason', p_reason, 'reversed_journal_id', v_journal_id)
  );

  RETURN jsonb_build_object('success', true, 'reversed_journal_id', v_journal_id);
END;
$function$;

-- public.revoke_approval_with_audit(p_approval_id uuid, p_old_snapshot_id uuid, p_old_snapshot_hash text, p_new_snapshot_id uuid, p_new_snapshot_hash text, p_revocation_reason text, p_metadata jsonb) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=cb62a9abcf7dd660d4d513c68addbb80 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.revoke_approval_with_audit(p_approval_id uuid, p_old_snapshot_id uuid, p_old_snapshot_hash text, p_new_snapshot_id uuid, p_new_snapshot_hash text, p_revocation_reason text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_approval RECORD;
BEGIN
  -- Get approval details
  SELECT * INTO v_approval 
  FROM public.filing_approvals 
  WHERE id = p_approval_id AND revoked_at IS NULL;
  
  IF v_approval.id IS NULL THEN
    RETURN; -- Already revoked or doesn't exist
  END IF;
  
  -- Revoke the approval
  UPDATE public.filing_approvals
  SET 
    revoked_at = now(),
    revocation_reason = p_revocation_reason
  WHERE id = p_approval_id AND revoked_at IS NULL;
  
  -- Log revocation with full audit trail
  INSERT INTO public.approval_revocation_log (
    organization_id,
    approval_id,
    filing_id,
    approval_scope,
    old_snapshot_id,
    old_snapshot_hash,
    new_snapshot_id,
    new_snapshot_hash,
    revocation_reason,
    system_actor,
    metadata
  ) VALUES (
    v_approval.organization_id,
    p_approval_id,
    v_approval.filing_id,
    v_approval.approval_scope,
    p_old_snapshot_id,
    p_old_snapshot_hash,
    p_new_snapshot_id,
    p_new_snapshot_hash,
    p_revocation_reason,
    'SYSTEM',
    p_metadata
  );
END;
$function$;

-- public.revoke_approvals_on_snapshot_change() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=ab91c2642aa3e48ac0ad7e3e262c3134 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.revoke_approvals_on_snapshot_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- If accounts snapshot changed, revoke both approvals
  IF OLD.accounts_snapshot_id IS DISTINCT FROM NEW.accounts_snapshot_id THEN
    UPDATE public.filing_approvals
    SET revoked_at = now(), revocation_reason = 'accounts_snapshot_changed'
    WHERE filing_id = NEW.id AND revoked_at IS NULL;
  -- If only CT snapshot changed, revoke CT approval only
  ELSIF OLD.ct_snapshot_id IS DISTINCT FROM NEW.ct_snapshot_id THEN
    UPDATE public.filing_approvals
    SET revoked_at = now(), revocation_reason = 'ct_snapshot_changed'
    WHERE filing_id = NEW.id AND approval_scope = 'CT600' AND revoked_at IS NULL;
  END IF;
  RETURN NEW;
END;
$function$;

-- public.revoke_vat_filing_approval(_vat_return_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=6be1e859f92e21bd37acffb421a366cc (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.revoke_vat_filing_approval(_vat_return_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ret record;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  SELECT * INTO v_ret FROM public.vat_returns WHERE id = _vat_return_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'VAT return not found'); END IF;
  IF NOT public.user_in_organization(auth.uid(), v_ret.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  IF v_ret.submitted_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'This VAT return has already been submitted');
  END IF;
  UPDATE public.vat_returns
     SET model_snapshot_id = NULL, snapshot_hash = NULL,
         filing_approved_by = NULL, filing_approved_at = NULL, updated_at = now()
   WHERE id = _vat_return_id;
  RETURN jsonb_build_object('success', true);
END;
$function$;

-- public.revoke_vat_return_filing_approval(_vat_return_id uuid, _reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=b4b43aa1da8cc57748221d7aee656ea2 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.revoke_vat_return_filing_approval(_vat_return_id uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.vat_returns%ROWTYPE;
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Access denied: not authenticated';
  END IF;

  SELECT * INTO v_row FROM public.vat_returns WHERE id = _vat_return_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'VAT return not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE organization_id = v_row.organization_id AND user_id = v_uid
  ) THEN
    RAISE EXCEPTION 'Access denied: not a member of this organization';
  END IF;

  IF v_row.submitted_at IS NOT NULL THEN
    RAISE EXCEPTION 'VAT return already submitted; cannot revoke approval';
  END IF;

  UPDATE public.vat_returns
     SET filing_approved_at = NULL,
         filing_approved_by = NULL,
         model_snapshot_id = NULL,
         model_snapshot_hash = NULL,
         client_approved_at = NULL,
         client_approved_by = NULL,
         updated_at = now()
   WHERE id = _vat_return_id;

  RETURN jsonb_build_object('ok', true, 'reason', _reason);
END;
$function$;

-- public.role_level(r text) -> integer
--   language=sql volatility=immutable security_definer=False search_path=search_path=public
--   definition_hash=db122f62539bed97776b7ba761063152 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.role_level(r text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE r
    WHEN 'owner' THEN 3
    WHEN 'admin' THEN 2
    WHEN 'staff' THEN 1
    ELSE 0
  END;
$function$;

-- public.run_monthly_depreciation(p_organization_id uuid, p_company_id uuid, p_period_end date) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=67506922b56dc695e3f6698c337c2085 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.run_monthly_depreciation(p_organization_id uuid, p_company_id uuid, p_period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_asset record;
  v_results jsonb := '[]'::jsonb;
  v_r jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.organization_users WHERE user_id = auth.uid() AND organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'Cross-tenant access denied';
  END IF;

  FOR v_asset IN
    SELECT id FROM public.fixed_assets
     WHERE organization_id = p_organization_id
       AND company_id = p_company_id
       AND status = 'active'
       AND depreciation_method <> 'NONE'
  LOOP
    v_r := public.post_monthly_depreciation(v_asset.id, p_period_end);
    v_results := v_results || jsonb_build_array(jsonb_build_object('asset_id', v_asset.id, 'result', v_r));
  END LOOP;

  RETURN jsonb_build_object('success', true, 'period_end', p_period_end, 'results', v_results);
END; $function$;

-- public.save_questionnaire_answer_by_token(p_instance_id uuid, p_token text, p_question_id text, p_answer_text text, p_answer_number numeric, p_answer_boolean boolean, p_answer_date date, p_answer_array text[]) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=d57f2fa3d7c1ae97b394cfdf0d4afcac (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.save_questionnaire_answer_by_token(p_instance_id uuid, p_token text, p_question_id text, p_answer_text text DEFAULT NULL::text, p_answer_number numeric DEFAULT NULL::numeric, p_answer_boolean boolean DEFAULT NULL::boolean, p_answer_date date DEFAULT NULL::date, p_answer_array text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_link public.questionnaire_public_links;
  v_hash TEXT;
BEGIN
  v_link := public._require_valid_questionnaire_link(p_instance_id, p_token);
  v_hash := public._hash_token(p_token);

  -- Check instance is not already submitted
  IF EXISTS (
    SELECT 1 FROM public.questionnaire_instances 
    WHERE id = p_instance_id AND status = 'submitted'
  ) THEN
    RAISE EXCEPTION 'Questionnaire already submitted';
  END IF;

  INSERT INTO public.questionnaire_responses(
    questionnaire_instance_id, 
    question_id, 
    answer_text, 
    answer_number, 
    answer_boolean, 
    answer_date, 
    answer_array
  )
  VALUES (
    p_instance_id, 
    p_question_id, 
    p_answer_text, 
    p_answer_number, 
    p_answer_boolean, 
    p_answer_date, 
    p_answer_array
  )
  ON CONFLICT (questionnaire_instance_id, question_id)
  DO UPDATE SET 
    answer_text = EXCLUDED.answer_text,
    answer_number = EXCLUDED.answer_number,
    answer_boolean = EXCLUDED.answer_boolean,
    answer_date = EXCLUDED.answer_date,
    answer_array = EXCLUDED.answer_array;

  -- Update instance status to in_progress if it was sent
  UPDATE public.questionnaire_instances
  SET status = 'in_progress'
  WHERE id = p_instance_id AND status = 'sent';

  INSERT INTO public.questionnaire_access_log(questionnaire_instance_id, token_hash, action)
  VALUES (p_instance_id, v_hash, 'save');

  RETURN jsonb_build_object('ok', true);
END;
$function$;

-- public.seed_default_chart_of_accounts(p_organization_id uuid, p_client_id uuid, p_company_id uuid) -> void
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=c8d2c887560c27143b5645733fa6e993 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.seed_default_chart_of_accounts(p_organization_id uuid, p_client_id uuid DEFAULT NULL::uuid, p_company_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO bookkeeping_accounts (organization_id, client_id, company_id, code, name, account_type, account_subtype, is_bank_account, is_control_account)
  VALUES
    -- Assets
    (p_organization_id, p_client_id, p_company_id, '1000', 'Current Account', 'ASSET', 'CURRENT_ASSET', true, false),
    (p_organization_id, p_client_id, p_company_id, '1100', 'Trade Debtors', 'ASSET', 'CURRENT_ASSET', false, true),
    (p_organization_id, p_client_id, p_company_id, '1200', 'Other Debtors', 'ASSET', 'CURRENT_ASSET', false, false),
    (p_organization_id, p_client_id, p_company_id, '1300', 'Prepayments', 'ASSET', 'CURRENT_ASSET', false, false),
    (p_organization_id, p_client_id, p_company_id, '1500', 'Fixed Assets', 'ASSET', 'FIXED_ASSET', false, false),
    -- Liabilities
    (p_organization_id, p_client_id, p_company_id, '2000', 'Trade Creditors', 'LIABILITY', 'CURRENT_LIABILITY', false, true),
    (p_organization_id, p_client_id, p_company_id, '2100', 'VAT Control', 'LIABILITY', 'CURRENT_LIABILITY', false, true),
    (p_organization_id, p_client_id, p_company_id, '2200', 'PAYE/NIC Payable', 'LIABILITY', 'CURRENT_LIABILITY', false, true),
    (p_organization_id, p_client_id, p_company_id, '2300', 'Corporation Tax', 'LIABILITY', 'CURRENT_LIABILITY', false, true),
    (p_organization_id, p_client_id, p_company_id, '2500', 'Loans', 'LIABILITY', 'LONG_TERM_LIABILITY', false, false),
    -- Equity
    (p_organization_id, p_client_id, p_company_id, '3000', 'Share Capital', 'EQUITY', 'EQUITY', false, false),
    (p_organization_id, p_client_id, p_company_id, '3100', 'Retained Earnings', 'EQUITY', 'RETAINED_EARNINGS', false, true),
    (p_organization_id, p_client_id, p_company_id, '3200', 'Dividends', 'EQUITY', 'DRAWINGS', false, false),
    -- Income
    (p_organization_id, p_client_id, p_company_id, '4000', 'Sales Revenue', 'INCOME', 'SALES', false, false),
    (p_organization_id, p_client_id, p_company_id, '4100', 'Other Income', 'INCOME', 'OTHER_INCOME', false, false),
    -- Cost of Sales
    (p_organization_id, p_client_id, p_company_id, '5000', 'Cost of Sales', 'EXPENSE', 'COST_OF_SALES', false, false),
    (p_organization_id, p_client_id, p_company_id, '5100', 'Direct Labour', 'EXPENSE', 'COST_OF_SALES', false, false),
    -- Overheads
    (p_organization_id, p_client_id, p_company_id, '6000', 'Wages & Salaries', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '6100', 'Employer NIC', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '6200', 'Pension Costs', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '6300', 'Rent & Rates', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '6400', 'Utilities', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '6500', 'Insurance', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '6600', 'Professional Fees', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '6700', 'Motor Expenses', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '6800', 'Travel & Entertainment', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '6900', 'Office Costs', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '7000', 'Depreciation', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '7100', 'Bank Charges', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '7200', 'Interest Paid', 'EXPENSE', 'FINANCE', false, false),
    (p_organization_id, p_client_id, p_company_id, '7300', 'Bad Debts', 'EXPENSE', 'OVERHEAD', false, false),
    (p_organization_id, p_client_id, p_company_id, '7900', 'Sundry Expenses', 'EXPENSE', 'OVERHEAD', false, false);
END;
$function$;

