-- public.tg_job_canonical_generate_deadlines() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=34612ea3862890edfb1619d545186906 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.tg_job_canonical_generate_deadlines()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_enabled boolean;
  v_facts   jsonb;
  v_result  jsonb;
BEGIN
  IF NEW.automation_source IS DISTINCT FROM 'canonical_spine_v1'
     OR NEW.job_template_code IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(canonical_spine_v1, false) INTO v_enabled
    FROM public.org_settings WHERE organization_id = NEW.organization_id LIMIT 1;
  IF NOT COALESCE(v_enabled, false) THEN
    RETURN NEW;
  END IF;

  v_facts := jsonb_build_object();
  IF NEW.period_start IS NOT NULL THEN
    v_facts := v_facts
      || jsonb_build_object('accounting_period_start', NEW.period_start)
      || jsonb_build_object('vat_period_start', NEW.period_start);
  END IF;
  IF NEW.period_end IS NOT NULL THEN
    v_facts := v_facts
      || jsonb_build_object('accounting_period_end', NEW.period_end)
      || jsonb_build_object('vat_period_end', NEW.period_end)
      || jsonb_build_object('cis_period_end', NEW.period_end)
      || jsonb_build_object('tax_month_end', NEW.period_end)
      || jsonb_build_object('financial_year_end', NEW.period_end);
  END IF;

  BEGIN
    v_result := public.lifecycle_generate_deadlines_for_job(NEW.id, v_facts);
    INSERT INTO public.audit_log (organization_id, action, entity_type, entity_id, metadata)
    VALUES (NEW.organization_id, 'canonical_lifecycle_generate_deadlines', 'job', NEW.id, v_result);
  EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.audit_log (organization_id, action, entity_type, entity_id, metadata)
    VALUES (NEW.organization_id, 'canonical_lifecycle_generate_deadlines_error', 'job', NEW.id,
            jsonb_build_object('error', SQLERRM));
  END;

  RETURN NEW;
END;
$function$;

-- public.tg_job_completed_rollover() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=ee06c08d14253c105ea8ef1d01e2b8f7 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.tg_job_completed_rollover()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year       int;
  v_next_start date;
  v_next_end   date;
  v_next_label text;
  v_svc_name   text;
  v_new_job    uuid;
BEGIN
  IF NEW.status <> 'completed' OR OLD.status = 'completed' THEN
    RETURN NEW;
  END IF;

  IF NEW.service_type IN ('sa_mtd','sa_non_mtd') THEN
    v_year := NULLIF(split_part(COALESCE(NEW.period_label,''), '/', 1), '')::int;
    IF v_year IS NULL AND NEW.period_start IS NOT NULL THEN
      v_year := EXTRACT(YEAR FROM NEW.period_start)::int;
    END IF;
    IF v_year IS NULL THEN RETURN NEW; END IF;
    v_next_start := make_date(v_year + 1, 4, 6);
    v_next_end   := make_date(v_year + 2, 4, 5);
    v_next_label := (v_year + 1)::text || '/' || substr((v_year + 2)::text, 3, 2);

  ELSIF NEW.service_type IN ('company_accounts','corporation_tax','confirmation_statement')
        AND NEW.period_start IS NOT NULL AND NEW.period_end IS NOT NULL THEN
    v_next_start := (NEW.period_start + INTERVAL '1 year')::date;
    v_next_end   := (NEW.period_end + INTERVAL '1 year')::date;
    v_next_label := to_char(v_next_end, 'YYYY') || ' Year-End';

  ELSE
    RETURN NEW;
  END IF;

  v_svc_name := COALESCE(
    (SELECT name FROM public.services_catalog WHERE code = NEW.service_type LIMIT 1),
    NEW.service_type);

  v_new_job := public.lifecycle_upsert_job_with_deadlines(
    NEW.organization_id, NEW.client_id, NEW.company_id, NULL,
    NEW.service_type, v_svc_name, v_next_start, v_next_end, v_next_label,
    'rollover:' || NEW.id::text);

  UPDATE public.jobs
     SET source_job_id = NEW.id,
         assigned_to = COALESCE(assigned_to, NEW.assigned_to)
   WHERE id = v_new_job AND source_job_id IS NULL AND id <> NEW.id;

  RETURN NEW;
END;
$function$;

-- public.tg_onboarding_status_audit() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=ab9d5335585fa4f31a8c7fb85cdab2e4 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.tg_onboarding_status_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO onboarding_events (
      organization_id, application_id, event_type, from_status, to_status,
      actor_user_id, actor_kind, metadata
    ) VALUES (
      NEW.organization_id, NEW.id, 'status_changed',
      OLD.status, NEW.status,
      auth.uid(),
      CASE WHEN auth.uid() IS NULL THEN 'system' ELSE 'user' END,
      jsonb_build_object('at', now())
    );
  END IF;
  RETURN NEW;
END;
$function$;

-- public.tg_quote_accepted_activate_canonical() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=8b3fbd1f5d89dd8b6f0ffa6e1700a4e1 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.tg_quote_accepted_activate_canonical()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_enabled boolean;
  v_result  jsonb;
BEGIN
  IF NEW.status = 'accepted'
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN

    SELECT COALESCE(canonical_spine_v1, false) INTO v_enabled
      FROM public.org_settings WHERE organization_id = NEW.organization_id LIMIT 1;

    IF COALESCE(v_enabled, false) THEN
      BEGIN
        v_result := public.lifecycle_activate_client_services(NEW.id);
        INSERT INTO public.audit_log (organization_id, action, entity_type, entity_id, metadata)
        VALUES (NEW.organization_id, 'canonical_lifecycle_activate', 'quote', NEW.id, v_result);
      EXCEPTION WHEN OTHERS THEN
        INSERT INTO public.audit_log (organization_id, action, entity_type, entity_id, metadata)
        VALUES (NEW.organization_id, 'canonical_lifecycle_activate_error', 'quote', NEW.id,
                jsonb_build_object('error', SQLERRM));
      END;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

-- public.tg_quote_sent_update_lead() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=1e1f058b309e866b066b00a3058d38a0 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.tg_quote_sent_update_lead()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'sent' AND COALESCE(OLD.status, '') <> 'sent' AND NEW.lead_id IS NOT NULL THEN
    UPDATE public.leads
       SET pipeline_stage = 'proposal_sent',
           proposal_sent_at = COALESCE(proposal_sent_at, now()),
           updated_at = now()
     WHERE id = NEW.lead_id
       AND pipeline_stage NOT IN ('won', 'lost');
  END IF;
  RETURN NEW;
END;
$function$;

-- public.toggle_automation_rule_safe(p_rule_id uuid, p_is_active boolean) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=9c543364ef75810276f023e96f2e57ed (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.toggle_automation_rule_safe(p_rule_id uuid, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_rule record;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_rule FROM automation_rules WHERE id = p_rule_id;
  IF v_rule.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rule not found');
  END IF;

  IF NOT public.user_in_organization(v_user_id, v_rule.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  UPDATE automation_rules SET is_active = p_is_active, updated_at = now() WHERE id = p_rule_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, after_state)
  VALUES (v_rule.organization_id, 'automation_rule', p_rule_id, 'toggled', v_user_id,
    jsonb_build_object('is_active', p_is_active));

  RETURN jsonb_build_object('success', true, 'rule_id', p_rule_id);
END;
$function$;

