-- public.trigger_records_request(p_job_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=81692278598b710c5f10d138d1435af2 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.trigger_records_request(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job jobs%ROWTYPE;
  v_service services_catalog%ROWTYPE;
  v_template templates%ROWTYPE;
  v_questionnaire_instance_id uuid;
  v_client_email text;
  v_client_name text;
  v_access_token text;
BEGIN
  -- Get job
  SELECT * INTO v_job FROM jobs WHERE id = p_job_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Job not found');
  END IF;
  
  -- Get service
  IF v_job.service_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Job has no service assigned');
  END IF;
  
  SELECT * INTO v_service FROM services_catalog WHERE id = v_job.service_id;
  IF v_service.records_request_template_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Service has no records request template');
  END IF;
  
  -- Get template
  SELECT * INTO v_template FROM templates WHERE id = v_service.records_request_template_id;
  
  -- Get client email
  IF v_job.client_id IS NOT NULL THEN
    SELECT email, first_name || ' ' || last_name INTO v_client_email, v_client_name
    FROM clients WHERE id = v_job.client_id;
  ELSIF v_job.company_id IS NOT NULL THEN
    SELECT email, company_name INTO v_client_email, v_client_name
    FROM companies WHERE id = v_job.company_id;
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'Job has no client or company');
  END IF;
  
  -- Generate access token
  v_access_token := encode(gen_random_bytes(32), 'hex');
  
  -- Create questionnaire instance
  INSERT INTO questionnaire_instances (
    organization_id,
    template_id,
    client_id,
    company_id,
    job_id,
    status,
    access_token,
    token_expires_at
  ) VALUES (
    v_job.organization_id,
    v_service.records_request_template_id,
    v_job.client_id,
    v_job.company_id,
    p_job_id,
    'sent',
    v_access_token,
    now() + interval '30 days'
  ) RETURNING id INTO v_questionnaire_instance_id;
  
  -- Link to job
  INSERT INTO job_questionnaire_instances (
    job_id,
    questionnaire_instance_id,
    questionnaire_type,
    trigger_status,
    feeds_workpaper
  ) VALUES (
    p_job_id,
    v_questionnaire_instance_id,
    'records_request',
    'awaiting_info',
    true
  );
  
  -- Update job
  UPDATE jobs SET info_requested_at = now() WHERE id = p_job_id;
  
  -- Queue email (will be sent via connected mailbox)
  INSERT INTO email_queue (
    organization_id,
    to_email,
    to_name,
    subject,
    body_html,
    status,
    entity_type,
    entity_id,
    job_id,
    client_id,
    company_id,
    context,
    merge_data
  ) VALUES (
    v_job.organization_id,
    v_client_email,
    v_client_name,
    'Information Request: ' || v_job.name,
    '<p>Dear ' || v_client_name || ',</p>' ||
    '<p>We need some information from you to complete your ' || v_job.name || '.</p>' ||
    '<p>Please click the link below to provide the required information:</p>' ||
    '<p><a href="{{questionnaire_url}}">Complete Information Request</a></p>' ||
    '<p>This link will expire in 30 days.</p>',
    'queued',
    'questionnaire',
    v_questionnaire_instance_id,
    p_job_id,
    v_job.client_id,
    v_job.company_id,
    'records_request',
    jsonb_build_object(
      'questionnaire_url', '{{BASE_URL}}/questionnaire/' || v_access_token,
      'job_name', v_job.name,
      'client_name', v_client_name
    )
  );
  
  -- Log audit
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, metadata)
  VALUES (
    v_job.organization_id,
    'job',
    p_job_id,
    'records_request_sent',
    jsonb_build_object('questionnaire_instance_id', v_questionnaire_instance_id)
  );
  
  RETURN jsonb_build_object(
    'success', true,
    'questionnaire_instance_id', v_questionnaire_instance_id
  );
END;
$function$;

-- public.trigger_records_request(p_job_id uuid, p_questionnaire_template_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=11e7ff28337f34e4896539a63c473e30 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.trigger_records_request(p_job_id uuid, p_questionnaire_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job jobs%ROWTYPE;
  v_questionnaire_instance_id uuid;
  v_access_token text;
  v_client_email text;
  v_client_name text;
BEGIN
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job % not found', p_job_id;
  END IF;

  SELECT COALESCE(c.email, co.email),
         COALESCE(TRIM(c.first_name || ' ' || c.last_name), co.company_name)
    INTO v_client_email, v_client_name
    FROM public.jobs j
    LEFT JOIN public.clients   c  ON c.id  = j.client_id
    LEFT JOIN public.companies co ON co.id = j.company_id
   WHERE j.id = p_job_id;

  IF v_client_email IS NULL OR v_client_email = '' THEN
    RAISE EXCEPTION 'No client email on job %', p_job_id;
  END IF;

  v_access_token := encode(gen_random_bytes(24), 'hex');
  INSERT INTO public.questionnaire_instances (
    organization_id, template_id, job_id, client_id, company_id,
    status, access_token, expires_at
  ) VALUES (
    v_job.organization_id, p_questionnaire_template_id, p_job_id, v_job.client_id, v_job.company_id,
    'sent', v_access_token, now() + interval '30 days'
  ) RETURNING id INTO v_questionnaire_instance_id;

  INSERT INTO public.email_queue (
    organization_id,
    to_email,
    to_name,
    subject,
    body_html,
    status,
    entity_type,
    entity_id,
    job_id,
    client_id,
    company_id,
    context,
    merge_data
  ) VALUES (
    v_job.organization_id,
    v_client_email,
    v_client_name,
    'Information Request: ' || v_job.name,
    '<p>Dear ' || v_client_name || ',</p>' ||
    '<p>We need some information from you to complete your ' || v_job.name || '.</p>' ||
    '<p>Please click the link below to provide the required information:</p>' ||
    '<p><a href="{{questionnaire_url}}">Complete Information Request</a></p>' ||
    '<p>This link will expire in 30 days.</p>',
    'pending',
    'questionnaire',
    v_questionnaire_instance_id,
    p_job_id,
    v_job.client_id,
    v_job.company_id,
    'job',
    jsonb_build_object(
      'questionnaire_url', '{{BASE_URL}}/questionnaire/' || v_access_token,
      'job_name', v_job.name,
      'client_name', v_client_name
    )
  );

  RETURN jsonb_build_object('status', 'sent', 'questionnaire_instance_id', v_questionnaire_instance_id);
END;
$function$;

-- public.try_parse_numeric(val text) -> numeric
--   language=plpgsql volatility=immutable security_definer=False search_path=search_path=public
--   definition_hash=a66eb7c0f7e55dd1bcbda3671632c56b (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.try_parse_numeric(val text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  IF val IS NULL OR val = '' THEN
    RETURN NULL;
  END IF;
  RETURN val::numeric;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$function$;

-- public.unlock_period(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=721785f38d0be6b8921d0f5c2b2b4474 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.unlock_period(p_organization_id uuid, p_entity_type text, p_entity_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid();
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Not authenticated'); END IF;
  IF NOT public.has_organization_role(p_organization_id, 'owner') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only owners may unlock periods');
  END IF;
  IF coalesce(trim(p_reason), '') = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'A reason is required to unlock a period');
  END IF;
  DELETE FROM public.period_locks
  WHERE organization_id = p_organization_id
    AND ((p_entity_type = 'client'  AND client_id  = p_entity_id)
      OR (p_entity_type = 'company' AND company_id = p_entity_id));
  RETURN jsonb_build_object('success', true);
END; $function$;

-- public.unmatch_bank_transaction(p_bank_transaction_id uuid, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=4a47b0a1246f17a25785763842c43818 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.unmatch_bank_transaction(p_bank_transaction_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_txn RECORD;
  v_user_id UUID := auth.uid();
  v_reverse JSONB;
  v_before JSONB;
BEGIN
  SELECT * INTO v_txn FROM public.bank_transactions WHERE id = p_bank_transaction_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bank transaction not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organization_users
    WHERE user_id = v_user_id AND organization_id = v_txn.organization_id
  ) THEN
    RAISE EXCEPTION 'Not authorised for organization';
  END IF;

  IF upper(COALESCE(v_txn.status,'')) = 'RECONCILED' THEN
    RAISE EXCEPTION 'Cannot unmatch a reconciled transaction; reopen reconciliation first';
  END IF;
  IF upper(COALESCE(v_txn.status,'')) <> 'MATCHED' THEN
    RAISE EXCEPTION 'Transaction is not matched';
  END IF;

  PERFORM assert_no_locked_period_write(
    v_txn.organization_id, v_txn.client_id, v_txn.company_id, v_txn.transaction_date
  );

  v_before := to_jsonb(v_txn);

  -- Delete linked payments (Phase 3 triggers recompute aged balances)
  DELETE FROM public.invoice_payments WHERE bank_transaction_id = p_bank_transaction_id;
  DELETE FROM public.bill_payments    WHERE bank_transaction_id = p_bank_transaction_id;

  -- Reverse the journal if present and not already reversed
  IF v_txn.matched_ledger_entry_id IS NOT NULL THEN
    v_reverse := public.reverse_journal(
      v_txn.matched_ledger_entry_id,
      CURRENT_DATE,
      COALESCE(p_reason, 'Bank match unmatched')
    );
  END IF;

  UPDATE public.bank_transactions
     SET status = 'UNREVIEWED',
         matched_ledger_entry_id = NULL,
         rule_id = NULL
   WHERE id = p_bank_transaction_id;

  INSERT INTO public.bookkeeping_audit_log(
    organization_id, entity_type, entity_id, action, actor_id,
    before_state, after_state, reason, metadata
  ) VALUES (
    v_txn.organization_id, 'bank_transaction', p_bank_transaction_id, 'unmatch_bank_transaction', v_user_id,
    v_before,
    jsonb_build_object('status','UNREVIEWED'),
    p_reason,
    jsonb_build_object('reverse_result', v_reverse)
  );

  RETURN jsonb_build_object('success', true, 'reverse_result', v_reverse);
END;
$function$;

-- public.update_automation_rule_safe(p_rule_id uuid, p_name text, p_trigger_type text, p_trigger_config jsonb, p_action_type text, p_action_config jsonb, p_is_active boolean, p_email_mode text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=0817073de1351fb15e0e4dafc56e4740 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_automation_rule_safe(p_rule_id uuid, p_name text DEFAULT NULL::text, p_trigger_type text DEFAULT NULL::text, p_trigger_config jsonb DEFAULT NULL::jsonb, p_action_type text DEFAULT NULL::text, p_action_config jsonb DEFAULT NULL::jsonb, p_is_active boolean DEFAULT NULL::boolean, p_email_mode text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_rule record;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_rule FROM automation_rules WHERE id = p_rule_id;
  IF v_rule.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rule not found');
  END IF;

  IF NOT public.user_in_organization(v_user_id, v_rule.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF NOT public.user_has_role_at_least(v_user_id, v_rule.organization_id, 'manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Manager role required');
  END IF;

  UPDATE automation_rules SET
    name = COALESCE(p_name, name),
    trigger_type = COALESCE(p_trigger_type, trigger_type),
    trigger_config = COALESCE(p_trigger_config, trigger_config),
    action_type = COALESCE(p_action_type, action_type),
    action_config = COALESCE(p_action_config, action_config),
    is_active = COALESCE(p_is_active, is_active),
    email_mode = COALESCE(p_email_mode, email_mode),
    updated_at = now()
  WHERE id = p_rule_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id)
  VALUES (v_rule.organization_id, 'automation_rule', p_rule_id, 'updated', v_user_id);

  RETURN jsonb_build_object('success', true, 'rule_id', p_rule_id);
END;
$function$;

-- public.update_bill_draft_safe(p_bill_id uuid, p_supplier_id uuid, p_bill_number text, p_reference text, p_issue_date date, p_due_date date, p_notes text, p_lines jsonb) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=23eac9e31c559d26e4fd88691b703b00 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_bill_draft_safe(p_bill_id uuid, p_supplier_id uuid DEFAULT NULL::uuid, p_bill_number text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_issue_date date DEFAULT NULL::date, p_due_date date DEFAULT NULL::date, p_notes text DEFAULT NULL::text, p_lines jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_bill record;
  v_line jsonb;
  v_line_number int := 0;
  v_total_net numeric := 0;
  v_total_vat numeric := 0;
  v_total_gross numeric := 0;
  v_quantity numeric;
  v_unit_price numeric;
  v_vat_rate numeric;
  v_net numeric;
  v_vat numeric;
  v_gross numeric;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bill not found');
  END IF;
  
  IF NOT public.user_in_organization(v_user_id, v_bill.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;
  
  IF v_bill.status NOT IN ('DRAFT', 'draft') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only DRAFT bills can be updated');
  END IF;

  IF p_lines IS NOT NULL THEN
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
      v_quantity := public.try_parse_numeric(v_line->>'quantity');
      v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
      IF v_quantity IS NULL OR v_unit_price IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid line data');
      END IF;
    END LOOP;
  END IF;

  UPDATE bills SET
    supplier_id = COALESCE(p_supplier_id, supplier_id),
    bill_number = COALESCE(p_bill_number, bill_number),
    reference = COALESCE(p_reference, reference),
    issue_date = COALESCE(p_issue_date, issue_date),
    due_date = COALESCE(p_due_date, due_date),
    notes = COALESCE(p_notes, notes),
    updated_at = now()
  WHERE id = p_bill_id;

  IF p_lines IS NOT NULL THEN
    DELETE FROM bill_lines WHERE bill_id = p_bill_id;
    
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
      v_line_number := v_line_number + 1;
      v_quantity := public.try_parse_numeric(v_line->>'quantity');
      v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
      v_vat_rate := COALESCE(public.try_parse_numeric(v_line->>'vat_rate'), 0);
      
      v_net := ROUND(v_quantity * v_unit_price, 2);
      v_vat := ROUND(v_net * v_vat_rate / 100, 2);
      v_gross := v_net + v_vat;
      
      v_total_net := v_total_net + v_net;
      v_total_vat := v_total_vat + v_vat;
      v_total_gross := v_total_gross + v_gross;
      
      INSERT INTO bill_lines (
        bill_id, line_number, description, quantity, unit_price,
        vat_rate, net_amount, vat_amount, gross_amount, account_id, vat_code_id
      ) VALUES (
        p_bill_id, v_line_number, v_line->>'description',
        v_quantity, v_unit_price, v_vat_rate, v_net, v_vat, v_gross,
        NULLIF(v_line->>'account_id', '')::uuid,
        NULLIF(v_line->>'vat_code_id', '')::uuid
      );
    END LOOP;

    UPDATE bills SET total_net = v_total_net, total_vat = v_total_vat, total_gross = v_total_gross
    WHERE id = p_bill_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'bill_id', p_bill_id);
END;
$function$;

-- public.update_bill_payment_status() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=1bab212f8c5986df3d06a51198511fc0 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_bill_payment_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_paid NUMERIC;
  v_bill_total NUMERIC;
  v_bill_id UUID;
BEGIN
  v_bill_id := COALESCE(NEW.bill_id, OLD.bill_id);
  SELECT COALESCE(SUM(amount), 0) INTO v_total_paid FROM bill_payments WHERE bill_id = v_bill_id;
  SELECT total_gross INTO v_bill_total FROM bills WHERE id = v_bill_id;
  UPDATE bills
  SET 
    amount_paid = v_total_paid,
    status = CASE
      WHEN v_total_paid = 0 THEN 'AWAITING_PAYMENT'
      WHEN v_total_paid >= v_bill_total THEN 'PAID'
      ELSE 'PART_PAID'
    END,
    updated_at = now()
  WHERE id = v_bill_id AND status NOT IN ('DRAFT', 'VOID');
  RETURN COALESCE(NEW, OLD);
END;
$function$;

-- public.update_bill_totals() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=7858d7faa1ed58cf5cc80ac17fc7a302 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_bill_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE bills
  SET 
    total_net = COALESCE((SELECT SUM(net_amount) FROM bill_lines WHERE bill_id = COALESCE(NEW.bill_id, OLD.bill_id)), 0),
    total_vat = COALESCE((SELECT SUM(vat_amount) FROM bill_lines WHERE bill_id = COALESCE(NEW.bill_id, OLD.bill_id)), 0),
    total_gross = COALESCE((SELECT SUM(gross_amount) FROM bill_lines WHERE bill_id = COALESCE(NEW.bill_id, OLD.bill_id)), 0),
    updated_at = now()
  WHERE id = COALESCE(NEW.bill_id, OLD.bill_id);
  RETURN COALESCE(NEW, OLD);
END;
$function$;

-- public.update_credit_note_totals() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=56515850c3b31bf7aae44bfbe560f827 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_credit_note_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE credit_notes
  SET 
    subtotal = COALESCE((SELECT SUM(net_amount) FROM credit_note_lines WHERE credit_note_id = COALESCE(NEW.credit_note_id, OLD.credit_note_id)), 0),
    vat_total = COALESCE((SELECT SUM(vat_amount) FROM credit_note_lines WHERE credit_note_id = COALESCE(NEW.credit_note_id, OLD.credit_note_id)), 0),
    total = COALESCE((SELECT SUM(gross_amount) FROM credit_note_lines WHERE credit_note_id = COALESCE(NEW.credit_note_id, OLD.credit_note_id)), 0),
    updated_at = now()
  WHERE id = COALESCE(NEW.credit_note_id, OLD.credit_note_id);
  RETURN COALESCE(NEW, OLD);
END;
$function$;

-- public.update_deadline_safe(p_deadline_id uuid, p_updates jsonb) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=b82ba431ba8883a5b66475e6275fcb21 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_deadline_safe(p_deadline_id uuid, p_updates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deadline record;
BEGIN
  -- Fetch deadline
  SELECT * INTO v_deadline FROM deadlines WHERE id = p_deadline_id;
  
  IF v_deadline.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Deadline not found');
  END IF;
  
  -- Check permission
  IF NOT can_modify_jobs(auth.uid(), v_deadline.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
  END IF;
  
  -- Update deadline
  UPDATE deadlines SET 
    name = COALESCE(p_updates->>'name', name),
    due_date = COALESCE((p_updates->>'due_date')::date, due_date),
    status = COALESCE(p_updates->>'status', status),
    updated_at = now()
  WHERE id = p_deadline_id;
  
  -- Write audit log
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (v_deadline.organization_id, 'deadline', p_deadline_id, 'update', auth.uid(), p_updates);
  
  RETURN jsonb_build_object('success', true);
END;
$function$;

-- public.update_idempotency_keys_updated_at() -> trigger
--   language=plpgsql volatility=volatile security_definer=False search_path=search_path=public
--   definition_hash=101b48f7a0b8ce217e4c1f1cdef95660 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_idempotency_keys_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

-- public.update_invoice_draft_safe(p_invoice_id uuid, p_customer_id uuid, p_contact_name text, p_contact_email text, p_reference text, p_issue_date text, p_due_date text, p_notes text, p_lines jsonb) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=d7d6bad7ec27315f76c05c44c9d0c1d4 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_invoice_draft_safe(p_invoice_id uuid, p_customer_id uuid DEFAULT NULL::uuid, p_contact_name text DEFAULT NULL::text, p_contact_email text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_issue_date text DEFAULT NULL::text, p_due_date text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_lines jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_invoice record;
  v_line jsonb;
  v_line_number int := 0;
  v_quantity numeric; v_unit_price numeric; v_vat_rate numeric;
  v_net_amount numeric; v_vat_amount numeric; v_gross_amount numeric;
  v_total_net numeric := 0; v_total_vat numeric := 0; v_total_gross numeric := 0;
  v_validated_lines jsonb[] := ARRAY[]::jsonb[];
  v_is_portal boolean := false;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id;
  IF v_invoice IS NULL THEN
    RAISE EXCEPTION 'Invoice not found' USING ERRCODE = '42704';
  END IF;

  -- Scoped to THIS invoice's owning entity: a portal user cannot reach another client's
  -- invoice, and portal authority covers draft create/edit only.
  v_is_portal := public.portal_has_perm(v_invoice.client_id, v_invoice.company_id, 'allow_invoice_create');

  IF NOT v_is_portal THEN
    IF NOT public.user_in_organization(v_user_id, v_invoice.organization_id) THEN
      RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
    END IF;
    -- INTENTIONAL TIGHTENING (owner ruling): update now requires the invoice capability.
    -- A member without can_create_invoices could previously edit drafts and no longer can.
    IF NOT public.can_create_invoices(v_user_id, v_invoice.organization_id) THEN
      RAISE EXCEPTION 'Permission denied: cannot edit invoices' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_invoice.status != 'DRAFT' THEN
    RAISE EXCEPTION 'Can only edit DRAFT invoices' USING ERRCODE = '42501';
  END IF;

  IF p_customer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.customers WHERE id = p_customer_id AND organization_id = v_invoice.organization_id
  ) THEN
    RAISE EXCEPTION 'Customer does not belong to organization' USING ERRCODE = '42501';
  END IF;

  UPDATE invoices SET
    customer_id   = COALESCE(p_customer_id, customer_id),
    contact_name  = COALESCE(p_contact_name, contact_name),
    contact_email = COALESCE(p_contact_email, contact_email),
    reference     = COALESCE(p_reference, reference),
    issue_date    = COALESCE(p_issue_date::date, issue_date),
    due_date      = COALESCE(p_due_date::date, due_date),
    notes         = COALESCE(p_notes, notes),
    updated_at    = now()
  WHERE id = p_invoice_id;

  IF p_lines IS NOT NULL AND jsonb_array_length(p_lines) > 0 THEN
    -- PHASE 1 — validate everything before destroying anything.
    v_line_number := 0;
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
      v_line_number := v_line_number + 1;
      v_quantity := public.try_parse_numeric(v_line->>'quantity');
      v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
      v_vat_rate := COALESCE(public.try_parse_numeric(v_line->>'vat_rate'), 0);

      IF v_quantity IS NULL OR v_unit_price IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: quantity or unit_price is missing/invalid', v_line_number), ERRCODE = '22023';
      END IF;
      IF v_quantity <= 0 THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: quantity must be > 0', v_line_number), ERRCODE = '22023';
      END IF;
      IF v_unit_price < 0 THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: unit_price must be >= 0', v_line_number), ERRCODE = '22023';
      END IF;
      IF v_vat_rate < 0 OR v_vat_rate > 100 THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: vat_rate must be between 0 and 100', v_line_number), ERRCODE = '22023';
      END IF;
      IF NULLIF(v_line->>'account_id', '') IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: account_id is required', v_line_number), ERRCODE = '22023';
      END IF;
      IF NULLIF(v_line->>'account_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: account_id is not a valid identifier', v_line_number), ERRCODE = '22023';
      END IF;
      IF NULLIF(v_line->>'vat_code_id', '') IS NOT NULL
         AND NULLIF(v_line->>'vat_code_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION USING MESSAGE = format('Invalid line %s: vat_code_id is not a valid identifier', v_line_number), ERRCODE = '22023';
      END IF;

      v_validated_lines := array_append(v_validated_lines, v_line);
    END LOOP;

    -- PHASE 2 — only now is mutation safe.
    DELETE FROM invoice_lines WHERE invoice_id = p_invoice_id;

    v_line_number := 0;
    FOREACH v_line IN ARRAY v_validated_lines
    LOOP
      v_line_number := v_line_number + 1;
      v_quantity := public.try_parse_numeric(v_line->>'quantity');
      v_unit_price := public.try_parse_numeric(v_line->>'unit_price');
      v_vat_rate := COALESCE(public.try_parse_numeric(v_line->>'vat_rate'), 0);

      v_net_amount := ROUND(v_quantity * v_unit_price, 2);
      v_vat_amount := ROUND(v_net_amount * (v_vat_rate / 100), 2);
      v_gross_amount := v_net_amount + v_vat_amount;
      v_total_net := v_total_net + v_net_amount;
      v_total_vat := v_total_vat + v_vat_amount;
      v_total_gross := v_total_gross + v_gross_amount;

      INSERT INTO invoice_lines (
        invoice_id, line_number, description, quantity, unit_price, vat_rate,
        vat_code_id, account_id, net_amount, vat_amount, gross_amount
      ) VALUES (
        p_invoice_id, v_line_number, COALESCE(v_line->>'description', ''),
        v_quantity, v_unit_price, v_vat_rate,
        NULLIF(v_line->>'vat_code_id', '')::uuid, NULLIF(v_line->>'account_id', '')::uuid,
        v_net_amount, v_vat_amount, v_gross_amount
      );
    END LOOP;

    UPDATE invoices SET
      total_net = v_total_net, total_vat = v_total_vat, total_gross = v_total_gross,
      remaining_balance = v_total_gross - COALESCE(amount_paid, 0),
      updated_at = now()
    WHERE id = p_invoice_id;
  END IF;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, metadata)
  VALUES (v_invoice.organization_id, 'invoice', p_invoice_id, 'updated', v_user_id,
    jsonb_build_object('lines_updated', p_lines IS NOT NULL,
                       'via', CASE WHEN v_is_portal THEN 'portal' ELSE 'staff' END));

  RETURN jsonb_build_object('success', true, 'invoice_id', p_invoice_id);
END;
$function$;

-- public.update_invoice_payment_status() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=e82aeca6403dfee05cf1ba9fa53d47e2 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_invoice_payment_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_paid NUMERIC;
  v_invoice_total NUMERIC;
  v_invoice_id UUID;
BEGIN
  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id);

  SELECT COALESCE(SUM(amount), 0) INTO v_total_paid
  FROM invoice_payments
  WHERE invoice_id = v_invoice_id;

  SELECT total_gross INTO v_invoice_total
  FROM invoices
  WHERE id = v_invoice_id;

  UPDATE invoices
  SET
    amount_paid = v_total_paid,
    status = CASE
      WHEN v_total_paid = 0 THEN 'sent'
      WHEN v_total_paid >= v_invoice_total THEN 'paid'
      ELSE 'part_paid'
    END,
    updated_at = now()
  WHERE id = v_invoice_id
    AND status NOT IN ('draft', 'voided', 'cancelled');

  RETURN COALESCE(NEW, OLD);
END;
$function$;

-- public.update_invoice_totals() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=e689b2a85b361409db170277c84cd43a (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_invoice_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE invoices
  SET 
    total_net = COALESCE((
      SELECT SUM(net_amount)
      FROM invoice_lines
      WHERE invoice_id = COALESCE(NEW.invoice_id, OLD.invoice_id)
    ), 0),
    total_vat = COALESCE((
      SELECT SUM(vat_amount)
      FROM invoice_lines
      WHERE invoice_id = COALESCE(NEW.invoice_id, OLD.invoice_id)
    ), 0),
    total_gross = COALESCE((
      SELECT SUM(gross_amount)
      FROM invoice_lines
      WHERE invoice_id = COALESCE(NEW.invoice_id, OLD.invoice_id)
    ), 0),
    updated_at = now()
  WHERE id = COALESCE(NEW.invoice_id, OLD.invoice_id);
  
  RETURN COALESCE(NEW, OLD);
END;
$function$;

-- public.update_issued_invoice_safe(p_invoice_id uuid, p_updates jsonb, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=d6a1a3336d90a3364aaea9833f295097 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_issued_invoice_safe(p_invoice_id uuid, p_updates jsonb, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice RECORD;
  v_user_id UUID;
  v_org_id UUID;
  v_user_role TEXT;
  v_before_state JSONB;
  v_allowed_fields TEXT[] := ARRAY['notes', 'internal_notes', 'tags', 'attachments', 'message_to_customer'];
  v_manager_fields TEXT[] := ARRAY['due_date'];
  v_key TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  
  IF v_invoice.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;
  
  v_org_id := v_invoice.organization_id;
  
  -- Check basic permission
  IF NOT user_in_organization(v_user_id, v_org_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
  END IF;
  
  -- Get user role
  SELECT role INTO v_user_role FROM organization_users 
  WHERE user_id = v_user_id AND organization_id = v_org_id;
  
  -- Validate status - only issued, part_paid, or paid invoices
  IF v_invoice.status NOT IN ('ISSUED', 'PART_PAID', 'PAID', 'AWAITING_PAYMENT') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot update invoice in ' || v_invoice.status || ' status');
  END IF;
  
  v_before_state := to_jsonb(v_invoice);
  
  -- Validate each field in updates
  FOR v_key IN SELECT jsonb_object_keys(p_updates)
  LOOP
    -- Check if field is allowed for all users
    IF v_key = ANY(v_allowed_fields) THEN
      CONTINUE;
    -- Check if field is allowed for manager+
    ELSIF v_key = ANY(v_manager_fields) THEN
      IF NOT user_has_role_at_least(v_user_id, v_org_id, 'manager') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied: ' || v_key || ' requires manager role');
      END IF;
    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'Field ' || v_key || ' is locked on issued invoices');
    END IF;
  END LOOP;
  
  -- Apply updates
  UPDATE invoices SET
    notes = COALESCE(p_updates->>'notes', notes),
    due_date = COALESCE((p_updates->>'due_date')::DATE, due_date),
    updated_at = now()
  WHERE id = p_invoice_id;
  
  -- Write audit log
  PERFORM write_audit_log(
    v_org_id,
    'invoice',
    p_invoice_id,
    'update_issued',
    NULL,
    NULL,
    NULL,
    v_before_state,
    (SELECT to_jsonb(i) FROM invoices i WHERE i.id = p_invoice_id),
    jsonb_build_object('updates', p_updates, 'reason', p_reason)
  );
  
  RETURN jsonb_build_object('success', true);
END;
$function$;

-- public.update_job_status_safe(p_job_id uuid, p_new_status text, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=a7508c9b42b69f8df7824412beb0f79f (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_job_status_safe(p_job_id uuid, p_new_status text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_job record;
  v_old_status text;
BEGIN
  -- Fetch job
  SELECT * INTO v_job FROM jobs WHERE id = p_job_id;
  
  IF v_job.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Job not found');
  END IF;
  
  -- Check permission
  IF NOT can_modify_jobs(auth.uid(), v_job.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
  END IF;
  
  v_old_status := v_job.status;
  
  -- Update job
  UPDATE jobs SET status = p_new_status, updated_at = now() WHERE id = p_job_id;
  
  -- Write audit log
  INSERT INTO audit_log (
    organization_id, entity_type, entity_id, action,
    field_name, old_value, new_value, user_id, metadata
  ) VALUES (
    v_job.organization_id, 'job', p_job_id, 'status_change',
    'status', v_old_status, p_new_status, auth.uid(),
    jsonb_build_object('reason', p_reason)
  );
  
  RETURN jsonb_build_object('success', true, 'old_status', v_old_status, 'new_status', p_new_status);
END;
$function$;

-- public.update_queued_email_safe(p_email_id uuid, p_subject text, p_body_html text, p_to_email text, p_scheduled_at timestamp with time zone) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=ddcb2cc22987b1d9c9a853b473ca0dd4 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_queued_email_safe(p_email_id uuid, p_subject text DEFAULT NULL::text, p_body_html text DEFAULT NULL::text, p_to_email text DEFAULT NULL::text, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_email RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_email FROM email_queue WHERE id = p_email_id;
  IF v_email.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email not found');
  END IF;

  IF NOT user_in_organization(v_user_id, v_email.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  -- FIXED: Block edits to failed emails and sending/sent
  IF v_email.status NOT IN ('draft', 'pending', 'queued') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only edit draft, pending, or queued emails');
  END IF;

  UPDATE email_queue SET
    subject = COALESCE(p_subject, subject),
    body_html = COALESCE(p_body_html, body_html),
    to_email = COALESCE(p_to_email, to_email),
    scheduled_at = COALESCE(p_scheduled_at, scheduled_at),
    updated_at = now()
  WHERE id = p_email_id;

  RETURN jsonb_build_object('success', true, 'email_id', p_email_id);
END;
$function$;

-- public.update_shareholder_on_allotment() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=00c70ff77af4b8a92ff23e780666ed1d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_shareholder_on_allotment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Update shareholder shares_held
  UPDATE company_shareholders
  SET 
    shares_held = shares_held + NEW.shares_allotted,
    as_at_date = NEW.allotment_date,
    updated_at = now()
  WHERE id = NEW.shareholder_id;
  
  -- Update share class total
  UPDATE company_share_classes
  SET 
    total_shares_issued = total_shares_issued + NEW.shares_allotted,
    updated_at = now()
  WHERE id = NEW.share_class_id;
  
  -- Create register event
  INSERT INTO company_register_events (
    company_id, event_type, event_date, source, details,
    shareholder_id, allotment_id, created_by
  )
  VALUES (
    NEW.company_id, 'allotment', NEW.allotment_date, 'workpaper',
    jsonb_build_object(
      'shares_allotted', NEW.shares_allotted,
      'price_per_share', NEW.price_per_share,
      'total_consideration', NEW.total_consideration
    ),
    NEW.shareholder_id, NEW.id, auth.uid()
  );
  
  RETURN NEW;
END;
$function$;

-- public.update_shareholders_on_transfer() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=ae6e2c842a5db94605d3b3af530793ac (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.update_shareholders_on_transfer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Decrease from_shareholder
  UPDATE company_shareholders
  SET 
    shares_held = shares_held - NEW.shares_transferred,
    as_at_date = NEW.transfer_date,
    updated_at = now()
  WHERE id = NEW.from_shareholder_id;
  
  -- Increase to_shareholder
  UPDATE company_shareholders
  SET 
    shares_held = shares_held + NEW.shares_transferred,
    as_at_date = NEW.transfer_date,
    updated_at = now()
  WHERE id = NEW.to_shareholder_id;
  
  -- Create register event
  INSERT INTO company_register_events (
    company_id, event_type, event_date, source, details,
    transfer_id, created_by
  )
  VALUES (
    NEW.company_id, 'transfer', NEW.transfer_date, 'workpaper',
    jsonb_build_object(
      'shares_transferred', NEW.shares_transferred,
      'from_shareholder_id', NEW.from_shareholder_id,
      'to_shareholder_id', NEW.to_shareholder_id,
      'consideration', NEW.consideration
    ),
    NEW.id, auth.uid()
  );
  
  RETURN NEW;
END;
$function$;

