-- public.user_has_org_role(check_user_id uuid, check_org_id uuid, required_role text) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=dfddd98d1fb5a3c5d9a60ae8f3eb1a1c (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.user_has_org_role(check_user_id uuid, check_org_id uuid, required_role text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 
    FROM public.organization_users 
    WHERE user_id = check_user_id 
      AND organization_id = check_org_id
      AND role = required_role
  );
$function$;

