-- public.user_has_role_at_least(_user_id uuid, _org_id uuid, _min_role text) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=d34c99bd939d620dc012d3a743b05485 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.user_has_role_at_least(_user_id uuid, _org_id uuid, _min_role text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 
    FROM public.organization_users
    WHERE user_id = _user_id 
      AND organization_id = _org_id
      AND CASE _min_role
        WHEN 'viewer' THEN role IN ('viewer', 'staff', 'manager', 'admin', 'owner')
        WHEN 'staff' THEN role IN ('staff', 'manager', 'admin', 'owner')
        WHEN 'manager' THEN role IN ('manager', 'admin', 'owner')
        WHEN 'admin' THEN role IN ('admin', 'owner')
        WHEN 'owner' THEN role = 'owner'
        ELSE false
      END
  )
$function$;

