-- public.user_role_is_at_least(check_user_id uuid, check_org_id uuid, min_role text) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=20e0e5a529b9c33e0c14531daa7162fa (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.user_role_is_at_least(check_user_id uuid, check_org_id uuid, min_role text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 
    FROM public.organization_users 
    WHERE user_id = check_user_id 
      AND organization_id = check_org_id
      AND role_level(role) >= role_level(min_role)
  );
$function$;

-- public.validate_filing_approval_token(p_token text) -> TABLE(filing_id uuid, is_valid boolean, error_message text)
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=2c83113b319662f7b1ae76a4e11d83de (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.validate_filing_approval_token(p_token text)
 RETURNS TABLE(filing_id uuid, is_valid boolean, error_message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filing RECORD;
BEGIN
  -- Find filing by token
  SELECT f.id, f.status, f.approval_token_expires_at
  INTO v_filing
  FROM public.filings f
  WHERE f.approval_token = p_token;
  
  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::UUID, FALSE, 'Invalid approval token'::TEXT;
    RETURN;
  END IF;
  
  IF v_filing.approval_token_expires_at < NOW() THEN
    RETURN QUERY SELECT v_filing.id, FALSE, 'Approval token has expired'::TEXT;
    RETURN;
  END IF;
  
  IF v_filing.status != 'awaiting_approval' THEN
    RETURN QUERY SELECT v_filing.id, FALSE, 'Filing is not awaiting approval'::TEXT;
    RETURN;
  END IF;
  
  RETURN QUERY SELECT v_filing.id, TRUE, NULL::TEXT;
END;
$function$;

-- public.validate_filing_status_transition() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=b63bc58cdaf12943db9b900ae230b844 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.validate_filing_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  valid_transitions jsonb := '{
    "draft": ["in_progress", "ready_for_review"],
    "in_progress": ["ready_for_review", "draft"],
    "ready_for_review": ["approved", "draft", "in_progress"],
    "approved": ["ready_to_file", "draft"],
    "ready_to_file": ["submitted", "approved"],
    "submitted": ["accepted", "rejected", "error"],
    "accepted": [],
    "rejected": ["ready_to_file", "draft"],
    "error": ["ready_to_file", "submitted"],
    "sent_to_client": ["client_approved", "client_rejected", "draft"],
    "client_approved": ["ready_to_file", "submitted"],
    "client_rejected": ["draft", "in_progress"]
  }'::jsonb;
  allowed_next jsonb;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  allowed_next := valid_transitions -> COALESCE(OLD.status, 'draft');
  IF allowed_next IS NOT NULL AND jsonb_typeof(allowed_next) = 'array' THEN
    IF NOT (allowed_next ? NEW.status) THEN
      RAISE EXCEPTION 'Invalid filing status transition: % -> % is not allowed', COALESCE(OLD.status, 'draft'), NEW.status;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

-- public.validate_filing_submission(p_filing_id uuid, p_filing_type text, p_user_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=56683658f978da1a6f5bd28f4e66a490 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.validate_filing_submission(p_filing_id uuid, p_filing_type text, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filing RECORD;
  v_approval RECORD;
  v_errors TEXT[] := ARRAY[]::TEXT[];
  v_user_role TEXT;
BEGIN
  -- Get filing
  SELECT * INTO v_filing FROM public.filings WHERE id = p_filing_id;
  
  IF v_filing.id IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'errors', ARRAY['Filing not found']);
  END IF;
  
  -- Check user role (must be accountant)
  SELECT role INTO v_user_role 
  FROM public.organization_users 
  WHERE user_id = p_user_id AND organization_id = v_filing.organization_id;
  
  IF v_user_role NOT IN ('owner', 'admin', 'staff') THEN
    v_errors := array_append(v_errors, 'Only accountants can submit filings');
  END IF;
  
  -- Check approval exists and is valid
  SELECT * INTO v_approval 
  FROM public.filing_approvals 
  WHERE filing_id = p_filing_id 
    AND approval_scope = CASE WHEN p_filing_type = 'ACCOUNTS_CH' THEN 'ACCOUNTS' ELSE 'CT600' END
    AND revoked_at IS NULL
  ORDER BY approved_at DESC
  LIMIT 1;
  
  IF v_approval.id IS NULL THEN
    v_errors := array_append(v_errors, 'Approval required before submission');
  ELSE
    -- Verify snapshot hash matches
    IF p_filing_type = 'ACCOUNTS_CH' THEN
      IF v_approval.snapshot_hash != (
        SELECT snapshot_hash FROM public.accounts_model_snapshots WHERE id = v_filing.accounts_snapshot_id
      ) THEN
        v_errors := array_append(v_errors, 'Snapshot hash mismatch - approval invalid');
      END IF;
    ELSE
      IF v_approval.snapshot_hash != (
        SELECT snapshot_hash FROM public.ct_computation_snapshots WHERE id = v_filing.ct_snapshot_id
      ) THEN
        v_errors := array_append(v_errors, 'Snapshot hash mismatch - approval invalid');
      END IF;
    END IF;
  END IF;
  
  RETURN jsonb_build_object(
    'valid', array_length(v_errors, 1) IS NULL,
    'errors', COALESCE(v_errors, ARRAY[]::TEXT[]),
    'approval_id', v_approval.id
  );
END;
$function$;

-- public.validate_job_status_transition() -> trigger
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=94f57dc51d4d402d8160e2d693c7de03 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.validate_job_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  valid_transitions jsonb := '{
    "blank": ["records_requested"],
    "records_requested": ["records_received", "client_queries", "blank"],
    "records_received": ["accountant_queries", "client_queries", "accountant_review", "blank"],
    "accountant_queries": ["records_received", "client_queries", "accountant_review", "blank"],
    "client_queries": ["records_received", "accountant_queries", "accountant_review", "blank"],
    "accountant_review": ["client_review", "ready_to_file", "accountant_queries", "client_queries", "blank"],
    "client_review": ["accountant_review", "ready_to_file", "client_queries", "blank"],
    "ready_to_file": ["completed", "accountant_review", "client_review", "blank"],
    "completed": ["blank"]
  }'::jsonb;
  allowed_next jsonb;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  allowed_next := valid_transitions -> COALESCE(OLD.status, 'blank');
  IF allowed_next IS NOT NULL AND jsonb_typeof(allowed_next) = 'array' THEN
    IF NOT (allowed_next ? NEW.status) THEN
      RAISE EXCEPTION 'Invalid job status transition: % -> % is not allowed', COALESCE(OLD.status, 'blank'), NEW.status;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

-- public.validate_onboarding_access_token(p_application_id uuid, p_token text) -> boolean
--   language=sql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=0389422c9f4d62c84a3ddb83385ef767 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.validate_onboarding_access_token(p_application_id uuid, p_token text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.onboarding_applications
    WHERE id = p_application_id
      AND access_token = p_token
      AND (access_token_expires_at IS NULL OR access_token_expires_at > now())
  );
$function$;

-- public.validate_submission_integrity(p_filing_id uuid, p_filing_type text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=570b4a4233607f5e4b712bae76828661 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.validate_submission_integrity(p_filing_id uuid, p_filing_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filing RECORD;
  v_approval RECORD;
  v_snapshot RECORD;
  v_errors TEXT[] := ARRAY[]::TEXT[];
  v_valid BOOLEAN := true;
  v_approval_scope TEXT;
  v_snapshot_id UUID;
  v_snapshot_hash TEXT;
BEGIN
  -- Determine approval scope
  v_approval_scope := CASE 
    WHEN p_filing_type = 'ACCOUNTS_CH' THEN 'ACCOUNTS'
    WHEN p_filing_type = 'CT600_HMRC' THEN 'CT600'
    ELSE NULL
  END;
  
  IF v_approval_scope IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'errors', ARRAY['Invalid filing type']);
  END IF;

  -- Get filing
  SELECT * INTO v_filing FROM public.filings WHERE id = p_filing_id;
  
  IF v_filing.id IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'errors', ARRAY['Filing not found']);
  END IF;
  
  -- Check filing has not already been filed
  IF v_filing.status IN ('filed', 'accepted') AND NOT COALESCE(v_filing.is_amendment, false) THEN
    v_errors := array_append(v_errors, 'Filing already submitted - create amendment instead');
    v_valid := false;
  END IF;
  
  -- Get active approval
  SELECT * INTO v_approval 
  FROM public.filing_approvals 
  WHERE filing_id = p_filing_id 
  AND approval_scope = v_approval_scope 
  AND revoked_at IS NULL;
  
  IF v_approval.id IS NULL THEN
    v_errors := array_append(v_errors, v_approval_scope || ' approval required');
    v_valid := false;
  END IF;
  
  -- Get relevant snapshot
  IF p_filing_type = 'ACCOUNTS_CH' THEN
    v_snapshot_id := v_filing.accounts_snapshot_id;
    IF v_snapshot_id IS NOT NULL THEN
      SELECT id, snapshot_hash INTO v_snapshot 
      FROM public.accounts_model_snapshots WHERE id = v_snapshot_id;
      v_snapshot_hash := v_snapshot.snapshot_hash;
    END IF;
  ELSIF p_filing_type = 'CT600_HMRC' THEN
    v_snapshot_id := v_filing.ct_snapshot_id;
    IF v_snapshot_id IS NOT NULL THEN
      SELECT id, snapshot_hash INTO v_snapshot 
      FROM public.ct_computation_snapshots WHERE id = v_snapshot_id;
      v_snapshot_hash := v_snapshot.snapshot_hash;
    END IF;
  END IF;
  
  -- Validate snapshot exists
  IF v_snapshot_id IS NULL THEN
    v_errors := array_append(v_errors, 'No snapshot linked to filing');
    v_valid := false;
  ELSIF v_snapshot.id IS NULL THEN
    v_errors := array_append(v_errors, 'Linked snapshot not found');
    v_valid := false;
  END IF;
  
  -- Validate approval matches current snapshot
  IF v_approval.id IS NOT NULL AND v_snapshot_id IS NOT NULL THEN
    IF v_approval.model_snapshot_id != v_snapshot_id THEN
      v_errors := array_append(v_errors, 'Approval is for different snapshot - re-approval required');
      v_valid := false;
    END IF;
    
    IF v_snapshot_hash IS NOT NULL AND v_approval.snapshot_hash != v_snapshot_hash THEN
      v_errors := array_append(v_errors, 'Snapshot hash mismatch - data has changed since approval');
      v_valid := false;
    END IF;
  END IF;
  
  -- Check for superseding snapshot (newer snapshot exists for same entity/period)
  IF p_filing_type = 'ACCOUNTS_CH' AND v_filing.company_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.accounts_model_snapshots 
      WHERE company_id = v_filing.company_id 
      AND period_start = v_filing.period_start 
      AND period_end = v_filing.period_end
      AND created_at > (SELECT created_at FROM public.accounts_model_snapshots WHERE id = v_snapshot_id)
    ) THEN
      v_errors := array_append(v_errors, 'Snapshot has been superseded by newer version');
      v_valid := false;
    END IF;
  END IF;
  
  IF p_filing_type = 'CT600_HMRC' AND v_filing.company_id IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.ct_computation_snapshots 
      WHERE company_id = v_filing.company_id 
      AND period_start = v_filing.period_start 
      AND period_end = v_filing.period_end
      AND created_at > (SELECT created_at FROM public.ct_computation_snapshots WHERE id = v_snapshot_id)
    ) THEN
      v_errors := array_append(v_errors, 'CT snapshot has been superseded by newer version');
      v_valid := false;
    END IF;
  END IF;
  
  RETURN jsonb_build_object(
    'valid', v_valid,
    'errors', v_errors,
    'approval_id', v_approval.id,
    'snapshot_id', v_snapshot_id,
    'snapshot_hash', v_snapshot_hash
  );
END;
$function$;

-- public.validate_template(p_template_id uuid, p_context jsonb) -> jsonb
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=public
--   definition_hash=09b1ab2eccae84bf01878b7f66f8f569 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.validate_template(p_template_id uuid, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t record;
  errs text[] := ARRAY[]::text[];
  body text;
  subject text;
BEGIN
  SELECT * INTO t FROM templates WHERE id = p_template_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('valid',false,'errors',ARRAY['template_not_found']);
  END IF;
  IF t.organization_id IS NOT NULL AND NOT user_in_organization(auth.uid(), t.organization_id) THEN
    RAISE EXCEPTION 'not a member';
  END IF;
  subject := coalesce(t.content->>'subject','');
  body := coalesce(t.content->>'body', t.content->>'body_html', '');
  IF length(trim(subject)) = 0 THEN errs := errs || 'subject_blank'; END IF;
  IF length(trim(body)) = 0 THEN errs := errs || 'body_blank'; END IF;
  IF t.requires_unsubscribe_link AND position('{{unsubscribe_url}}' in body) = 0 THEN
    errs := errs || 'missing_unsubscribe_link';
  END IF;
  IF t.recipient_rule IS NULL OR length(trim(t.recipient_rule)) = 0 THEN
    errs := errs || 'missing_recipient_rule';
  END IF;
  IF t.required_merge_fields IS NOT NULL THEN
    DECLARE f text;
    BEGIN
      FOREACH f IN ARRAY t.required_merge_fields LOOP
        IF position('{{'||f||'}}' in body) = 0 AND position('{{'||f||'}}' in subject) = 0 THEN
          errs := errs || ('missing_merge:'||f);
        END IF;
      END LOOP;
    END;
  END IF;
  RETURN jsonb_build_object('valid', array_length(errs,1) IS NULL, 'errors', to_jsonb(errs));
END;$function$;

-- public.vault_secret_exists(p_name text) -> boolean
--   language=plpgsql volatility=stable security_definer=True search_path=search_path=pg_catalog, public
--   definition_hash=fe0ffb8683474d7928ad50ab7d1dfec6 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.vault_secret_exists(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  RETURN EXISTS (SELECT 1 FROM vault.secrets WHERE name = p_name);
EXCEPTION WHEN undefined_table OR invalid_schema_name THEN
  RETURN false;
END;
$function$;

-- public.verify_aml(p_onboarding_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=ae5b5e79f68ab028c81d24e0545fbb55 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.verify_aml(p_onboarding_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_onboarding record;
BEGIN
  SELECT * INTO v_onboarding FROM onboarding_applications WHERE id = p_onboarding_id;
  
  IF v_onboarding.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found';
  END IF;
  
  IF NOT user_has_organization_access(v_onboarding.organization_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  
  UPDATE onboarding_applications
  SET 
    aml_status = 'verified',
    aml_verified_at = now(),
    aml_expiry_date = CURRENT_DATE + INTERVAL '5 years'
  WHERE id = p_onboarding_id;
  
  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, old_value, new_value, user_id)
  VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'aml_verified', 
    v_onboarding.aml_status, 'verified', auth.uid());
  
  RETURN jsonb_build_object(
    'success', true,
    'aml_status', 'verified',
    'aml_verified_at', now(),
    'aml_expiry_date', CURRENT_DATE + INTERVAL '5 years'
  );
END;
$function$;

-- public.verify_aml_and_approve(p_onboarding_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=e150c924ed993163ed94de77f180140e (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.verify_aml_and_approve(p_onboarding_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_onboarding record;
  v_approval jsonb;
  v_approval_error text;
BEGIN
  SELECT * INTO v_onboarding FROM onboarding_applications WHERE id = p_onboarding_id;
  IF v_onboarding.id IS NULL THEN
    RAISE EXCEPTION 'Onboarding application not found';
  END IF;

  IF NOT user_has_organization_access(v_onboarding.organization_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF v_onboarding.aml_status IS DISTINCT FROM 'verified' THEN
    UPDATE onboarding_applications
    SET aml_status = 'verified',
        aml_verified_at = now(),
        aml_expiry_date = CURRENT_DATE + INTERVAL '5 years'
    WHERE id = p_onboarding_id;

    INSERT INTO audit_log (organization_id, entity_type, entity_id, action, old_value, new_value, user_id)
    VALUES (v_onboarding.organization_id, 'onboarding', p_onboarding_id, 'aml_verified',
      v_onboarding.aml_status, 'verified', auth.uid());
  END IF;

  IF v_onboarding.status IN ('approved', 'rejected') THEN
    RETURN jsonb_build_object(
      'aml_status', 'verified',
      'aml_verified_at', now(),
      'aml_expiry_date', CURRENT_DATE + INTERVAL '5 years',
      'already_finalized', true,
      'status', v_onboarding.status
    );
  END IF;

  BEGIN
    v_approval := public.approve_onboarding_transactional(p_onboarding_id, auth.uid());
  EXCEPTION WHEN OTHERS THEN
    v_approval_error := SQLERRM;
    RETURN jsonb_build_object(
      'aml_status', 'verified',
      'aml_verified_at', now(),
      'aml_expiry_date', CURRENT_DATE + INTERVAL '5 years',
      'approval_error', v_approval_error
    );
  END;

  IF (v_approval->>'blocked')::boolean IS TRUE THEN
    RETURN jsonb_build_object(
      'aml_status', 'verified',
      'aml_verified_at', now(),
      'aml_expiry_date', CURRENT_DATE + INTERVAL '5 years',
      'approval_error', v_approval->>'reason'
    );
  END IF;

  RETURN v_approval
    || jsonb_build_object(
      'aml_status', 'verified',
      'aml_verified_at', now(),
      'aml_expiry_date', CURRENT_DATE + INTERVAL '5 years'
    );
END;
$function$;

-- public.void_bill(p_bill_id uuid, p_reason text, p_user_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=76a5553855b78e9f5144b588e060cbd2 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.void_bill(p_bill_id uuid, p_reason text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_bill RECORD;
  v_journal_id uuid;
  v_entries jsonb := '[]'::jsonb;
  v_line RECORD;
  v_post_result jsonb;
  v_entity_type text;
  v_entity_id uuid;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
BEGIN
  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Bill not found');
  END IF;
  IF v_bill.status = 'VOIDED' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_voided', 'error_message', 'Bill already voided');
  END IF;
  IF COALESCE(v_bill.amount_paid,0) > 0 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'has_payments', 'error_message', 'Cannot void bill with payments. Refund first.');
  END IF;
  IF NOT (auth.role() = 'service_role'
          OR public.user_in_organization(auth.uid(), v_bill.organization_id)) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_authorized', 'error_message', 'Not authorized for this organization');
  END IF;
  v_uid := CASE WHEN auth.role() = 'service_role' THEN COALESCE(p_user_id, auth.uid()) ELSE auth.uid() END;

  v_entity_type := CASE WHEN v_bill.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_bill.client_id, v_bill.company_id);

  IF v_bill.is_posted THEN
    SELECT journal_id INTO v_journal_id FROM ledger_entries
      WHERE source_type = 'BILL' AND source_id = p_bill_id LIMIT 1;

    IF v_journal_id IS NOT NULL THEN
      FOR v_line IN
        SELECT account_id, debit, credit, description, vat_code_id
          FROM ledger_entries WHERE journal_id = v_journal_id
      LOOP
        v_entries := v_entries || jsonb_build_array(jsonb_build_object(
          'account_id', v_line.account_id,
          'debit',  v_line.credit,
          'credit', v_line.debit,
          'description', 'REVERSAL: ' || COALESCE(v_line.description,'') ||
                         CASE WHEN p_reason IS NOT NULL THEN ' - ' || p_reason ELSE '' END,
          'vat_code_id', v_line.vat_code_id
        ));
      END LOOP;

      v_post_result := post_to_ledger(
        p_organization_id := v_bill.organization_id,
        p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
        p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
        p_journal_date    := CURRENT_DATE,
        p_reference       := 'VOID-' || COALESCE(v_bill.bill_number, substr(p_bill_id::text,1,8)),
        p_description     := 'BILL void',
        p_journal_type    := 'SYSTEM',
        p_source_type     := 'JOURNAL',
        p_source_id       := v_journal_id,
        p_currency        := COALESCE(v_bill.currency,'GBP'),
        p_fx_rate         := 1.0,
        p_created_by      := v_uid,
        p_entries         := v_entries
      );

      IF NOT (v_post_result->>'success')::boolean THEN
        RAISE EXCEPTION 'Reversal failed: %', v_post_result->>'error_message'
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;

  UPDATE bills SET status='VOIDED', is_posted=false, updated_at=now() WHERE id = p_bill_id;
  RETURN jsonb_build_object('success', true);
END;
$function$;

-- public.void_bill_safe(p_bill_id uuid, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=1e5a0d0d2a8385b1a2041adad2aaab92 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.void_bill_safe(p_bill_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_bill record;
BEGIN
  PERFORM set_config('app.rpc', '1', true);

  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_bill FROM bills WHERE id = p_bill_id;
  IF v_bill.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bill not found');
  END IF;

  IF NOT public.user_in_organization(v_user_id, v_bill.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;

  IF NOT public.user_has_role_at_least(v_user_id, v_bill.organization_id, 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin role required');
  END IF;

  UPDATE bills SET status = 'VOIDED', void_reason = p_reason, voided_at = now(), voided_by = v_user_id
  WHERE id = p_bill_id;

  INSERT INTO audit_log (organization_id, entity_type, entity_id, action, user_id, after_state)
  VALUES (v_bill.organization_id, 'bill', p_bill_id, 'voided', v_user_id,
    jsonb_build_object('reason', p_reason));

  RETURN jsonb_build_object('success', true, 'bill_id', p_bill_id);
END;
$function$;

-- public.void_invoice(p_invoice_id uuid, p_reason text, p_user_id uuid) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=627f3305de2a0aede59f91d6e7757252 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.void_invoice(p_invoice_id uuid, p_reason text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice RECORD;
  v_journal_id uuid;
  v_entries jsonb := '[]'::jsonb;
  v_line RECORD;
  v_post_result jsonb;
  v_entity_type text;
  v_entity_id uuid;
  v_uid uuid := COALESCE(p_user_id, auth.uid());
BEGIN
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_found', 'error_message', 'Invoice not found');
  END IF;
  IF v_invoice.status = 'VOIDED' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'already_voided', 'error_message', 'Invoice already voided');
  END IF;
  IF COALESCE(v_invoice.amount_paid,0) > 0 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'has_payments', 'error_message', 'Cannot void invoice with payments. Refund first.');
  END IF;
  IF NOT (auth.role() = 'service_role'
          OR public.user_in_organization(auth.uid(), v_invoice.organization_id)) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'not_authorized', 'error_message', 'Not authorized for this organization');
  END IF;
  v_uid := CASE WHEN auth.role() = 'service_role' THEN COALESCE(p_user_id, auth.uid()) ELSE auth.uid() END;

  v_entity_type := CASE WHEN v_invoice.client_id IS NOT NULL THEN 'client' ELSE 'company' END;
  v_entity_id   := COALESCE(v_invoice.client_id, v_invoice.company_id);

  IF v_invoice.is_posted THEN
    SELECT journal_id INTO v_journal_id FROM ledger_entries
      WHERE source_type = 'INVOICE' AND source_id = p_invoice_id LIMIT 1;

    IF v_journal_id IS NOT NULL THEN
      FOR v_line IN
        SELECT account_id, debit, credit, description, vat_code_id
          FROM ledger_entries WHERE journal_id = v_journal_id
      LOOP
        v_entries := v_entries || jsonb_build_array(jsonb_build_object(
          'account_id', v_line.account_id,
          'debit',  v_line.credit,
          'credit', v_line.debit,
          'description', 'REVERSAL: ' || COALESCE(v_line.description,'') ||
                         CASE WHEN p_reason IS NOT NULL THEN ' - ' || p_reason ELSE '' END,
          'vat_code_id', v_line.vat_code_id
        ));
      END LOOP;

      v_post_result := post_to_ledger(
        p_organization_id := v_invoice.organization_id,
        p_client_id       := CASE WHEN v_entity_type='client'  THEN v_entity_id ELSE NULL END,
        p_company_id      := CASE WHEN v_entity_type='company' THEN v_entity_id ELSE NULL END,
        p_journal_date    := CURRENT_DATE,
        p_reference       := 'VOID-' || COALESCE(v_invoice.invoice_number, substr(p_invoice_id::text,1,8)),
        p_description     := 'INVOICE void',
        p_journal_type    := 'SYSTEM',
        p_source_type     := 'JOURNAL',
        p_source_id       := v_journal_id,
        p_currency        := COALESCE(v_invoice.currency,'GBP'),
        p_fx_rate         := 1.0,
        p_created_by      := v_uid,
        p_entries         := v_entries
      );

      IF NOT (v_post_result->>'success')::boolean THEN
        RAISE EXCEPTION 'Reversal failed: %', v_post_result->>'error_message'
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;

  UPDATE invoices SET status='VOIDED', is_posted=false, updated_at=now() WHERE id = p_invoice_id;
  RETURN jsonb_build_object('success', true);
END;
$function$;

-- public.void_invoice_safe(p_invoice_id uuid, p_reason text) -> jsonb
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=c5bea7aecf24ef82c52e634314bf8a87 (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.void_invoice_safe(p_invoice_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_invoice record;
  v_res jsonb;
BEGIN
  PERFORM set_config('app.rpc', '1', true);
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
  END IF;
  IF NOT public.user_in_organization(v_user_id, v_invoice.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Access denied');
  END IF;
  IF NOT public.can_void_invoices(v_user_id, v_invoice.organization_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Permission denied: cannot void invoices');
  END IF;
  v_res := public.void_invoice(p_invoice_id, p_reason, v_user_id);
  IF NOT COALESCE((v_res->>'success')::boolean, false) THEN
    RETURN jsonb_build_object('success', false,
      'error', COALESCE(v_res->>'error_message', v_res->>'error', 'Could not void invoice'));
  END IF;
  RETURN jsonb_build_object('success', true, 'invoice_id', p_invoice_id);
END;
$function$;

-- public.write_audit_log(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_action text, p_field_name text, p_old_value text, p_new_value text, p_before_state jsonb, p_after_state jsonb, p_metadata jsonb) -> uuid
--   language=plpgsql volatility=volatile security_definer=True search_path=search_path=public
--   definition_hash=170e8b3a295f89c61e1de082db6d027d (hash of the ORIGINAL, pre-sanitization body)
CREATE OR REPLACE FUNCTION public.write_audit_log(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_action text, p_field_name text DEFAULT NULL::text, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_before_state jsonb DEFAULT NULL::jsonb, p_after_state jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_audit_id UUID;
  v_user_id UUID;
  v_user_role TEXT;
BEGIN
  v_user_id := auth.uid();
  
  -- Get user's role in org
  SELECT role INTO v_user_role
  FROM organization_users
  WHERE user_id = v_user_id AND organization_id = p_org_id;
  
  INSERT INTO audit_log (
    organization_id,
    entity_type,
    entity_id,
    action,
    field_name,
    old_value,
    new_value,
    user_id,
    actor_role,
    before_state,
    after_state,
    metadata
  ) VALUES (
    p_org_id,
    p_entity_type,
    p_entity_id,
    p_action,
    p_field_name,
    p_old_value,
    p_new_value,
    v_user_id,
    v_user_role,
    p_before_state,
    p_after_state,
    p_metadata
  )
  RETURNING id INTO v_audit_id;
  
  RETURN v_audit_id;
END;
$function$;

